files.src/adapters/ascii_renderer.rs:
 1: use crate::domain::entities::grid::Grid;
 2: 
 3: /// Interface for rendering the grid.
 4: pub trait GridRenderer {
 5:     fn render(&self, grid: &Grid) -> String;
 6: }
 7: 
 8: /// A concrete adapter that renders the Grid as an ASCII string.
 9: /// This fulfills the Clean Architecture requirement of decoupling the domain logic
10: /// from the presentation layer.
11: pub struct AsciiRenderer;
12: 
13: impl GridRenderer for AsciiRenderer {
14:     fn render(&self, grid: &Grid) -> String {
15:         let mut output = String::new();
16:         
17:         for y in 0..grid.depth() {
18:             // Top walls for this row
19:             for x in 0..grid.width() {
20:                 let cell = grid.get(x, y).unwrap();
21:                 output.push('+');
22:                 if cell.walls[0] { // North
23:                     output.push_str("---");
24:                 } else {
25:                     output.push_str("   ");
26:                 }
27:             }
28:             output.push_str("+\n");
29:             
30:             // Side walls for this row
31:             for x in 0..grid.width() {
32:                 let cell = grid.get(x, y).unwrap();
33:                 if cell.walls[3] { // West
34:                     output.push('|');
35:                 } else {
36:                     output.push(' ');
37:                 }
38:                 output.push_str("   "); // Inside of the room
39:             }
40:             // East wall of the last cell in the row
41:             let last_cell = grid.get(grid.width() - 1, y).unwrap();
42:             if last_cell.walls[1] { // East
43:                 output.push('|');
44:             } else {
45:                 output.push(' ');
46:             }
47:             output.push('\n');
48:         }
49:         
50:         // Bottom walls for the last row
51:         for x in 0..grid.width() {
52:             let cell = grid.get(x, grid.depth() - 1).unwrap();
53:             output.push('+');
54:             if cell.walls[2] { // South
55:                 output.push_str("---");
56:             } else {
57:                 output.push_str("   ");
58:             }
59:         }
60:         output.push_str("+\n");
61:         
62:         output
63:     }
64: }
65: 
66: #[cfg(test)]
67: mod tests {
68:     use super::*;
69:     use crate::domain::entities::grid::Grid;
70: 
71:     #[test]
72:     fn test_ascii_renderer() {
73:         let mut grid = Grid::new(2, 2);
74:         // Modify some walls to test rendering
75:         if let Some(cell) = grid.get_mut(0, 0) {
76:             cell.walls[1] = false; // Remove East wall of (0,0)
77:         }
78:         if let Some(cell) = grid.get_mut(1, 0) {
79:             cell.walls[3] = false; // Remove West wall of (1,0)
80:         }
81: 
82:         let renderer = AsciiRenderer;
83:         let output = renderer.render(&grid);
84:         
85:         // Very basic validation, actual visual check is better in integration tests
86:         assert!(output.contains("+---+---+"));
87:     }
88: }

files.src/adapters/json_presenter.rs:
 1: use crate::adapters::voxel_mapper::{MergedQuad, FaceDirection, VoxelType};
 2: 
 3: /// Interface Adapter to convert MergedQuads to JSON format for the web presentation layer.
 4: pub struct JsonPresenter;
 5: 
 6: impl JsonPresenter {
 7:     pub fn render_voxels(quads: &[MergedQuad]) -> String {
 8:         let mut json = String::with_capacity(quads.len() * 100);
 9:         json.push('[');
10:         
11:         for (i, quad) in quads.iter().enumerate() {
12:             let dir_str = match quad.dir {
13:                 FaceDirection::Up => "\"up\"",
14:                 FaceDirection::Down => "\"down\"",
15:                 FaceDirection::North => "\"north\"",
16:                 FaceDirection::South => "\"south\"",
17:                 FaceDirection::East => "\"east\"",
18:                 FaceDirection::West => "\"west\"",
19:             };
20:             
21:             let type_str = match quad.v_type {
22:                 VoxelType::Wall => "\"wall\"",
23:                 VoxelType::Floor => "\"floor\"",
24:                 VoxelType::Ceiling => "\"ceiling\"",
25:                 VoxelType::Light => "\"light\"",
26:                 VoxelType::RedWall => "\"redwall\"",
27:             };
28:             
29:             let obj = format!(
30:                 "{{\"x\":{},\"y\":{},\"z\":{},\"w\":{},\"h\":{},\"dir\":{},\"type\":{},\"color\":{}}}",
31:                 quad.x, quad.y, quad.z, quad.w, quad.h, dir_str, type_str, quad.color
32:             );
33:             
34:             json.push_str(&obj);
35:             if i < quads.len() - 1 {
36:                 json.push(',');
37:             }
38:         }
39:         
40:         json.push(']');
41:         json
42:     }
43: }
44: 
45: #[cfg(test)]
46: mod tests {
47:     use super::*;
48: 
49:     #[test]
50:     fn test_json_rendering() {
51:         let quads = vec![
52:             MergedQuad { x: 0.0, y: 1.0, z: 2.0, w: 4.0, h: 1.0, dir: FaceDirection::Up, v_type: VoxelType::Wall, color: 1441813 }
53:         ];
54:         
55:         let json = JsonPresenter::render_voxels(&quads);
56:         assert_eq!(json, r#"[{"x":0,"y":1,"z":2,"w":4,"h":1,"dir":"up","type":"wall","color":1441813}]"#);
57:     }
58: }

