files.src/adapters/octree_gpu_serializer.rs:
  1: use crate::domain::entities::sparse_voxel_octree::{SparseVoxelOctree, SvoNode};
  2: 
  3: /// Represents SVO flattened data formatted for direct WebGL2 texture upload.
  4: #[derive(Debug, Clone)]
  5: pub struct OctreeGpuData {
  6:     pub texture_width: u32,
  7:     pub texture_height: u32,
  8:     pub texel_data: Vec<u32>,
  9: }
 10: 
 11: /// GPU Adapter to flatten the Sparse Voxel Octree into a GPU-compatible texture format.
 12: ///
 13: /// DOCUMENTED ENCODING SCHEME (RGBA32UI texture format):
 14: /// Each SVO node occupies exactly one texel (4 x 32-bit unsigned integers: R, G, B, A).
 15: ///
 16: /// CHANNEL LAYOUT:
 17: /// - **R (x):** Node Type Flag
 18: ///   * `0` = Internal Parent Node
 19: ///   * `1` = Leaf Voxel Node
 20: ///
 21: /// - **G (y):** Payload 1
 22: ///   * If Internal Node (`R == 0`): `child_base_index` (uint32) - Index in the texture
 23: ///     of the first child. The remaining 7 children are stored contiguously at indices
 24: ///     `child_base_index + 1` through `child_base_index + 7`.
 25: ///   * If Leaf Node (`R == 1`): `voxel_type` (uint32) - Voxel type ID (e.g., WALL, FLOOR, etc.).
 26: ///
 27: /// - **B (z):** Payload 2
 28: ///   * If Internal Node (`R == 0`): `child_mask` (uint32) - 8-bit active children mask.
 29: ///     Bit `i` is `1` if child `i` is non-empty, and `0` if child `i` is empty air.
 30: ///   * If Leaf Node (`R == 1`): `color` (uint32) - 24-bit packed RGB color (`0xRRGGBB`).
 31: ///
 32: /// - **A (w):** Payload 3
 33: ///   * If Internal Node (`R == 0`): `0` (Padding).
 34: ///   * If Leaf Node (`R == 1`): `light_level` (uint32) - BFS-propagated light level (`0` to `15`).
 35: pub struct OctreeGpuSerializer;
 36: 
 37: impl OctreeGpuSerializer {
 38:     /// Serializes SVO nodes into texture-ready data, padding the last row to maintain grid alignment.
 39:     pub fn serialize_to_gpu_data(octree: &SparseVoxelOctree) -> OctreeGpuData {
 40:         let num_nodes = octree.nodes.len();
 41:         let texture_width = 1024; // Standard GPU texture row size
 42:         let total_texels = ((num_nodes + texture_width - 1) / texture_width) * texture_width;
 43: 
 44:         let mut texel_data = Vec::with_capacity(total_texels * 4);
 45: 
 46:         for node in &octree.nodes {
 47:             match *node {
 48:                 SvoNode::Leaf { voxel_type, color, light_level } => {
 49:                     texel_data.push(1); // R
 50:                     texel_data.push(voxel_type as u32); // G
 51:                     texel_data.push(color); // B
 52:                     texel_data.push(light_level as u32); // A
 53:                 }
 54:                 SvoNode::Internal { child_base_index, child_mask } => {
 55:                     texel_data.push(0); // R
 56:                     texel_data.push(child_base_index); // G
 57:                     texel_data.push(child_mask as u32); // B
 58:                     texel_data.push(0); // A
 59:                 }
 60:             }
 61:         }
 62: 
 63:         // Pad the last row with empty leaves to prevent out-of-bound shader fetches
 64:         let padded_nodes_count = total_texels - num_nodes;
 65:         for _ in 0..padded_nodes_count {
 66:             texel_data.push(1); // Leaf
 67:             texel_data.push(0); // Air
 68:             texel_data.push(0); // Color
 69:             texel_data.push(0); // Light Level
 70:         }
 71: 
 72:         let texture_height = (total_texels / texture_width) as u32;
 73: 
 74:         OctreeGpuData {
 75:             texture_width: texture_width as u32,
 76:             texture_height,
 77:             texel_data,
 78:         }
 79:     }
 80: }
 81: 
 82: #[cfg(test)]
 83: mod tests {
 84:     use super::*;
 85: 
 86:     #[test]
 87:     fn test_gpu_serialization_padding() {
 88:         let mut octree = SparseVoxelOctree::new(2, 4.0);
 89:         octree.set(0, 0, 0, 1, 0xFF00FF, 15);
 90: 
 91:         let gpu_data = OctreeGpuSerializer::serialize_to_gpu_data(&octree);
 92: 
 93:         // Verification tests
 94:         assert_eq!(gpu_data.texture_width, 1024);
 95:         assert_eq!(gpu_data.texel_data.len(), (gpu_data.texture_width * gpu_data.texture_height * 4) as usize);
 96: 
 97:         // Index 0 maps to texel (0, 0)
 98:         let index = 0;
 99:         let tx = index % 1024;
100:         let ty = index / 1024;
101:         assert_eq!(tx, 0);
102:         assert_eq!(ty, 0);
103: 
104:         // Ensure child_base_index values stay within texture range
105:         for node in &octree.nodes {
106:             if let SvoNode::Internal { child_base_index, .. } = *node {
107:                 let max_index = child_base_index + 7;
108:                 assert!(max_index < (gpu_data.texture_width * gpu_data.texture_height));
109:             }
110:         }
111:     }
112: }

files.src/adapters/voxel_mapper.rs:
  1: use crate::domain::entities::voxel_grid::{
  2:     VoxelGrid, VOXEL_AIR, VOXEL_WALL, VOXEL_FLOOR, VOXEL_CEILING, VOXEL_LIGHT, VOXEL_RED_WALL,
  3: };
  4: 
  5: #[derive(Debug, Clone, PartialEq, Eq)]
  6: pub enum VoxelType {
  7:     Wall,
  8:     Floor,
  9:     Ceiling,
 10:     Light,
 11:     RedWall,
 12: }
 13: 
 14: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
 15: pub enum FaceDirection {
 16:     Up,
 17:     Down,
 18:     North,
 19:     South,
 20:     East,
 21:     West,
 22: }
 23: 
 24: #[derive(Debug, Clone, PartialEq)]
 25: pub struct MergedQuad {
 26:     pub x: f32,
 27:     pub y: f32,
 28:     pub z: f32,
 29:     pub w: f32,
 30:     pub h: f32,
 31:     pub dir: FaceDirection,
 32:     pub v_type: VoxelType,
 33:     pub color: u32,
 34: }
 35: 
 36: pub struct VoxelMapper {
 37:     pub voxel_scale: f32,
 38: }
 39: 
 40: impl VoxelMapper {
 41:     pub fn new(voxel_scale: f32) -> Self {
 42:         Self { voxel_scale }
 43:     }
 44: 
 45:     /// Maps the 3D VoxelGrid into a list of merged quads using Greedy Meshing.
 46:     pub fn map_voxel_grid(&self, grid: &VoxelGrid) -> Vec<MergedQuad> {
 47:         let mut quads = Vec::new();
 48:         let scale = self.voxel_scale;
 49: 
 50:         let apply_light = |base_color: u32, light_level: u8| -> u32 {
 51:             let normalized = light_level as f32 / 15.0;
 52:             let mult = 0.25 + (normalized * normalized) * 0.75;
 53:             let r = ((base_color >> 16) & 0xFF) as f32 * mult;
 54:             let g = ((base_color >> 8) & 0xFF) as f32 * mult;
 55:             let b = (base_color & 0xFF) as f32 * mult;
 56:             ((r as u32) << 16) | ((g as u32) << 8) | (b as u32)
 57:         };
 58: 
 59:         let get_voxel_type = |v_id: u8| -> VoxelType {
 60:             match v_id {
 61:                 VOXEL_WALL => VoxelType::Wall,
 62:                 VOXEL_FLOOR => VoxelType::Floor,
 63:                 VOXEL_CEILING => VoxelType::Ceiling,
 64:                 VOXEL_LIGHT => VoxelType::Light,
 65:                 VOXEL_RED_WALL => VoxelType::RedWall,
 66:                 _ => VoxelType::Wall,
 67:             }
 68:         };
 69: 
 70:         let get_voxel_color = |x: usize, y: usize, z: usize| -> u32 {
 71:             let v_id = grid.get(x, y, z);
 72:             let ll = grid.get_light(x, y, z);
 73:             let base_color = match v_id {
 74:                 VOXEL_WALL => 0xddcc66,
 75:                 VOXEL_FLOOR => 0x998811,
 76:                 VOXEL_CEILING => 0xcccccc,
 77:                 VOXEL_LIGHT => 0xffffff,
 78:                 VOXEL_RED_WALL => 0x880000,
 79:                 _ => 0x000000,
 80:             };
 81: 
 82:             if v_id == VOXEL_LIGHT {
 83:                 0xffffff
 84:             } else {
 85:                 apply_light(base_color, ll)
 86:             }
 87:         };
 88: 
 89:         let w_dim = grid.width();
 90:         let h_dim = grid.height();
 91:         let d_dim = grid.depth();
 92: 
 93:         // 1. UP FACES (+Y)
 94:         for y in 0..h_dim {
 95:             let get_face = |x: usize, z: usize| -> Option<(VoxelType, u32)> {
 96:                 let v = grid.get(x, y, z);
 97:                 if v != VOXEL_AIR && (y == h_dim - 1 || grid.get(x, y + 1, z) == VOXEL_AIR) {
 98:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
 99:                 } else {
100:                     None
101:                 }
102:             };
103:             let merged = self.greedy_mesh_2d(w_dim, d_dim, &get_face);
104:             for (u, v, qw, qh, vt, col) in merged {
105:                 quads.push(MergedQuad {
106:                     x: u as f32 * scale,
107:                     y: y as f32 * scale,
108:                     z: v as f32 * scale,
109:                     w: qw as f32 * scale,
110:                     h: qh as f32 * scale,
111:                     dir: FaceDirection::Up,
112:                     v_type: vt,
113:                     color: col,
114:                 });
115:             }
116:         }
117: 
118:         // 2. DOWN FACES (-Y)
119:         for y in 0..h_dim {
120:             let get_face = |x: usize, z: usize| -> Option<(VoxelType, u32)> {
121:                 let v = grid.get(x, y, z);
122:                 if v != VOXEL_AIR && (y == 0 || grid.get(x, y - 1, z) == VOXEL_AIR) {
123:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
124:                 } else {
125:                     None
126:                 }
127:             };
128:             let merged = self.greedy_mesh_2d(w_dim, d_dim, &get_face);
129:             for (u, v, qw, qh, vt, col) in merged {
130:                 quads.push(MergedQuad {
131:                     x: u as f32 * scale,
132:                     y: y as f32 * scale,
133:                     z: v as f32 * scale,
134:                     w: qw as f32 * scale,
135:                     h: qh as f32 * scale,
136:                     dir: FaceDirection::Down,
137:                     v_type: vt,
138:                     color: col,
139:                 });
140:             }
141:         }
142: 
143:         // 3. NORTH FACES (-Z)
144:         for z in 0..d_dim {
145:             let get_face = |x: usize, y: usize| -> Option<(VoxelType, u32)> {
146:                 let v = grid.get(x, y, z);
147:                 if v != VOXEL_AIR && (z == 0 || grid.get(x, y, z - 1) == VOXEL_AIR) {
148:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
149:                 } else {
150:                     None
151:                 }
152:             };
153:             let merged = self.greedy_mesh_2d(w_dim, h_dim, &get_face);
154:             for (u, v, qw, qh, vt, col) in merged {
155:                 quads.push(MergedQuad {
156:                     x: u as f32 * scale,
157:                     y: v as f32 * scale,
158:                     z: z as f32 * scale,
159:                     w: qw as f32 * scale,
160:                     h: qh as f32 * scale,
161:                     dir: FaceDirection::North,
162:                     v_type: vt,
163:                     color: col,
164:                 });
165:             }
166:         }
167: 
168:         // 4. SOUTH FACES (+Z)
169:         for z in 0..d_dim {
170:             let get_face = |x: usize, y: usize| -> Option<(VoxelType, u32)> {
171:                 let v = grid.get(x, y, z);
172:                 if v != VOXEL_AIR && (z == d_dim - 1 || grid.get(x, y, z + 1) == VOXEL_AIR) {
173:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
174:                 } else {
175:                     None
176:                 }
177:             };
178:             let merged = self.greedy_mesh_2d(w_dim, h_dim, &get_face);
179:             for (u, v, qw, qh, vt, col) in merged {
180:                 quads.push(MergedQuad {
181:                     x: u as f32 * scale,
182:                     y: v as f32 * scale,
183:                     z: z as f32 * scale,
184:                     w: qw as f32 * scale,
185:                     h: qh as f32 * scale,
186:                     dir: FaceDirection::South,
187:                     v_type: vt,
188:                     color: col,
189:                 });
190:             }
191:         }
192: 
193:         // 5. EAST FACES (+X)
194:         for x in 0..w_dim {
195:             let get_face = |z: usize, y: usize| -> Option<(VoxelType, u32)> {
196:                 let v = grid.get(x, y, z);
197:                 if v != VOXEL_AIR && (x == w_dim - 1 || grid.get(x + 1, y, z) == VOXEL_AIR) {
198:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
199:                 } else {
200:                     None
201:                 }
202:             };
203:             let merged = self.greedy_mesh_2d(d_dim, h_dim, &get_face);
204:             for (u, v, qw, qh, vt, col) in merged {
205:                 quads.push(MergedQuad {
206:                     x: x as f32 * scale,
207:                     y: v as f32 * scale,
208:                     z: u as f32 * scale,
209:                     w: qw as f32 * scale,
210:                     h: qh as f32 * scale,
211:                     dir: FaceDirection::East,
212:                     v_type: vt,
213:                     color: col,
214:                 });
215:             }
216:         }
217: 
218:         // 6. WEST FACES (-X)
219:         for x in 0..w_dim {
220:             let get_face = |z: usize, y: usize| -> Option<(VoxelType, u32)> {
221:                 let v = grid.get(x, y, z);
222:                 if v != VOXEL_AIR && (x == 0 || grid.get(x - 1, y, z) == VOXEL_AIR) {
223:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
224:                 } else {
225:                     None
226:                 }
227:             };
228:             let merged = self.greedy_mesh_2d(d_dim, h_dim, &get_face);
229:             for (u, v, qw, qh, vt, col) in merged {
230:                 quads.push(MergedQuad {
231:                     x: x as f32 * scale,
232:                     y: v as f32 * scale,
233:                     z: u as f32 * scale,
234:                     w: qw as f32 * scale,
235:                     h: qh as f32 * scale,
236:                     dir: FaceDirection::West,
237:                     v_type: vt,
238:                     color: col,
239:                 });
240:             }
241:         }
242: 
243:         quads
244:     }
245: 
246:     /// Helper that performs 2D greedy meshing on a slice.
247:     fn greedy_mesh_2d(
248:         &self,
249:         w_slice: usize,
250:         h_slice: usize,
251:         get_face: &dyn Fn(usize, usize) -> Option<(VoxelType, u32)>,
252:     ) -> Vec<(usize, usize, usize, usize, VoxelType, u32)> {
253:         let mut visited = vec![vec![false; h_slice]; w_slice];
254:         let mut quads = Vec::new();
255: 
256:         for v in 0..h_slice {
257:             for u in 0..w_slice {
258:                 if visited[u][v] {
259:                     continue;
260:                 }
261: 
262:                 if let Some((v_type, color)) = get_face(u, v) {
263:                     // Find max width along u
264:                     let mut quad_w = 1;
265:                     while u + quad_w < w_slice {
266:                         if visited[u + quad_w][v] {
267:                             break;
268:                         }
269:                         if let Some((next_type, next_color)) = get_face(u + quad_w, v) {
270:                             if next_type == v_type && next_color == color {
271:                                 quad_w += 1;
272:                                 continue;
273:                             }
274:                         }
275:                         break;
276:                     }
277: 
278:                     // Find max height along v
279:                     let mut quad_h = 1;
280:                     'expand_h: while v + quad_h < h_slice {
281:                         for du in 0..quad_w {
282:                             if visited[u + du][v + quad_h] {
283:                                 break 'expand_h;
284:                             }
285:                             if let Some((next_type, next_color)) = get_face(u + du, v + quad_h) {
286:                                 if next_type != v_type || next_color != color {
287:                                     break 'expand_h;
288:                                 }
289:                             } else {
290:                                 break 'expand_h;
291:                             }
292:                         }
293:                         quad_h += 1;
294:                     }
295: 
296:                     // Mark matched area as visited
297:                     for dv in 0..quad_h {
298:                         for du in 0..quad_w {
299:                             visited[u + du][v + dv] = true;
300:                         }
301:                     }
302: 
303:                     quads.push((u, v, quad_w, quad_h, v_type, color));
304:                 }
305:             }
306:         }
307:         quads
