  1: /// Represents a node inside the Sparse Voxel Octree (SVO).
  2: /// Implements a linearized, GPU-friendly design stored in a flat arena array.
  3: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
  4: pub enum SvoNode {
  5:     /// Leaf node storing actual voxel attributes
  6:     Leaf {
  7:         voxel_type: u8,
  8:         color: u32,
  9:         light_level: u8,
 10:     },
 11:     /// Internal parent node directing traversal to 8 children
 12:     Internal {
 13:         /// Base index in the arena vector where the 8 children nodes are stored contiguously.
 14:         child_base_index: u32,
 15:         /// Bitmask where bit `i` represents if child `i` is non-empty (1) or empty air (0).
 16:         child_mask: u8,
 17:     },
 18: }
 19: 
 20: /// The Sparse Voxel Octree aggregate root entity.
 21: #[derive(Debug, Clone, PartialEq)]
 22: pub struct SparseVoxelOctree {
 23:     pub root: usize,
 24:     pub nodes: Vec<SvoNode>,
 25:     pub depth: u32,
 26:     pub world_size: f32,
 27: }
 28: 
 29: impl SparseVoxelOctree {
 30:     /// Creates a new empty Sparse Voxel Octree.
 31:     pub fn new(depth: u32, world_size: f32) -> Self {
 32:         let root_node = SvoNode::Leaf {
 33:             voxel_type: 0,
 34:             color: 0,
 35:             light_level: 0,
 36:         };
 37:         Self {
 38:             root: 0,
 39:             nodes: vec![root_node],
 40:             depth,
 41:             world_size,
 42:         }
 43:     }
 44: 
 45:     /// Checks if the SVO is entirely empty (air).
 46:     pub fn is_empty(&self) -> bool {
 47:         match self.nodes[self.root] {
 48:             SvoNode::Leaf { voxel_type, .. } => voxel_type == 0,
 49:             SvoNode::Internal { child_mask, .. } => child_mask == 0,
 50:         }
 51:     }
 52: 
 53:     /// Queries the SVO for voxel attributes at integer coordinates `(x, y, z)`.
 54:     pub fn get(&self, x: u32, y: u32, z: u32) -> Option<(u8, u32, u8)> {
 55:         let max_coord = 1 << self.depth;
 56:         if x >= max_coord || y >= max_coord || z >= max_coord {
 57:             return None;
 58:         }
 59:         self.get_recursive(self.root, x, y, z, self.depth)
 60:     }
 61: 
 62:     fn get_recursive(&self, node_idx: usize, x: u32, y: u32, z: u32, depth: u32) -> Option<(u8, u32, u8)> {
 63:         if node_idx >= self.nodes.len() {
 64:             return None;
 65:         }
 66: 
 67:         match self.nodes[node_idx] {
 68:             SvoNode::Leaf { voxel_type, color, light_level } => {
 69:                 Some((voxel_type, color, light_level))
 70:             }
 71:             SvoNode::Internal { child_base_index, child_mask } => {
 72:                 if depth == 0 {
 73:                     return None;
 74:                 }
 75: 
 76:                 let bit = depth - 1;
 77:                 let octant_x = (x >> bit) & 1;
 78:                 let octant_y = (y >> bit) & 1;
 79:                 let octant_z = (z >> bit) & 1;
 80:                 let octant_idx = (octant_z << 2) | (octant_y << 1) | octant_x;
 81: 
 82:                 // Check if the octant is active in the child mask
 83:                 if (child_mask & (1 << octant_idx)) == 0 {
 84:                     return Some((0, 0, 0)); // Empty air
 85:                 }
 86: 
 87:                 let child_node_idx = child_base_index as usize + octant_idx as usize;
 88:                 let mask = (1 << bit) - 1;
 89:                 self.get_recursive(child_node_idx, x & mask, y & mask, z & mask, depth - 1)
 90:             }
 91:         }
 92:     }
 93: 
 94:     /// Sets voxel attributes at coordinate `(x, y, z)`. Splits nodes and collapses uniform subtrees recursively.
 95:     pub fn set(&mut self, x: u32, y: u32, z: u32, voxel_type: u8, color: u32, light_level: u8) {
 96:         let max_coord = 1 << self.depth;
 97:         if x >= max_coord || y >= max_coord || z >= max_coord {
 98:             return;
 99:         }
100:         self.set_recursive(self.root, x, y, z, self.depth, voxel_type, color, light_level);
101:     }
102: 
103:     fn set_recursive(
104:         &mut self,
105:         node_idx: usize,
106:         x: u32,
107:         y: u32,
108:         z: u32,
109:         depth: u32,
110:         v_type: u8,
111:         col: u32,
112:         ll: u8,
113:     ) {
114:         match self.nodes[node_idx] {
115:             SvoNode::Leaf { voxel_type, color, light_level } => {
116:                 if voxel_type == v_type && color == col && light_level == ll {
117:                     return;
118:                 }
119: 
120:                 if depth == 0 {
121:                     self.nodes[node_idx] = SvoNode::Leaf {
122:                         voxel_type: v_type,
123:                         color: col,
124:                         light_level: ll,
125:                     };
126:                     return;
127:                 }
128: 
129:                 // Split leaf node
130:                 let child_base_index = self.nodes.len() as u32;
131:                 let child_mask = if voxel_type == 0 { 0 } else { 0xFF };
132: 
133:                 for _ in 0..8 {
134:                     self.nodes.push(SvoNode::Leaf {
135:                         voxel_type,
136:                         color,
137:                         light_level,
138:                     });
139:                 }
140: 
141:                 self.nodes[node_idx] = SvoNode::Internal {
142:                     child_base_index,
143:                     child_mask,
144:                 };
145: 
146:                 self.set_recursive(node_idx, x, y, z, depth, v_type, col, ll);
147:             }
148:             SvoNode::Internal { child_base_index, mut child_mask } => {
149:                 let bit = depth - 1;
150:                 let octant_x = (x >> bit) & 1;
151:                 let octant_y = (y >> bit) & 1;
152:                 let octant_z = (z >> bit) & 1;
153:                 let octant_idx = (octant_z << 2) | (octant_y << 1) | octant_x;
154: 
155:                 let child_node_idx = child_base_index as usize + octant_idx as usize;
156: 
157:                 if v_type != 0 {
158:                     child_mask |= 1 << octant_idx;
159:                 }
160: 
161:                 self.nodes[node_idx] = SvoNode::Internal {
162:                     child_base_index,
163:                     child_mask,
164:                 };
165: 
166:                 let mask = (1 << bit) - 1;
167:                 self.set_recursive(child_node_idx, x & mask, y & mask, z & mask, depth - 1, v_type, col, ll);
168: 
169:                 // Try to collapse
170:                 self.collapse_if_uniform(node_idx);
171:             }
172:         }
173:     }
174: 
175:     fn collapse_if_uniform(&mut self, node_idx: usize) {
176:         if let SvoNode::Internal { child_base_index, .. } = self.nodes[node_idx] {
177:             let first_child_idx = child_base_index as usize;
178:             let mut uniform = true;
179:             let mut first_val = None;
180: 
181:             for i in 0..8 {
182:                 match self.nodes[first_child_idx + i] {
183:                     SvoNode::Internal { .. } => {
184:                         uniform = false;
185:                         break;
186:                     }
187:                     SvoNode::Leaf { voxel_type, color, light_level } => {
188:                         if let Some((vt, col, ll)) = first_val {
189:                             if vt != voxel_type || col != color || ll != light_level {
190:                                 uniform = false;
191:                                 break;
192:                             }
193:                         } else {
194:                             first_val = Some((voxel_type, color, light_level));
195:                         }
196:                     }
197:                 }
198:             }
199: 
200:             if uniform {
201:                 if let Some((vt, col, ll)) = first_val {
202:                     self.nodes[node_idx] = SvoNode::Leaf {
203:                         voxel_type: vt,
204:                         color: col,
205:                         light_level: ll,
206:                     };
207:                 }
208:             }
209:         }
210:     }
211: }

 1: use crate::domain::entities::voxel_grid::{VoxelGrid, VOXEL_AIR, VOXEL_LIGHT};
 2: use std::collections::VecDeque;
 3: 
 4: /// Calculates 3D voxel lighting across the dense VoxelGrid using a BFS flood-fill algorithm.
 5: /// Time Complexity: O(n) where n is the number of voxels.
 6: /// Achieves pure voxel cast lighting.
 7: pub fn calculate_voxel_lighting(grid: &mut VoxelGrid) {
 8:     let w = grid.width();
 9:     let h = grid.height();
10:     let d = grid.depth();
11:     
12:     let max_light: u8 = 15;
13:     let falloff: u8 = 1;
14: 
15:     let mut queue: VecDeque<(usize, usize, usize)> = VecDeque::new();
16: 
17:     // Pass 1: Find all light sources
18:     for z in 0..d {
19:         for y in 0..h {
20:             for x in 0..w {
21:                 if grid.get(x, y, z) == VOXEL_LIGHT {
22:                     grid.set_light(x, y, z, max_light);
23:                     queue.push_back((x, y, z));
24:                 }
25:             }
26:         }
27:     }
28: 
29:     // Pass 2: BFS flood-fill 3D
30:     while let Some((cx, cy, cz)) = queue.pop_front() {
31:         let current_light = grid.get_light(cx, cy, cz);
32:         if current_light <= falloff {
33:             continue;
34:         }
35: 
36:         let next_light = current_light - falloff;
37: 
38:         // Check 6 directions
39:         let neighbors: [(isize, isize, isize); 6] = [
40:             (cx as isize + 1, cy as isize, cz as isize),
41:             (cx as isize - 1, cy as isize, cz as isize),
42:             (cx as isize, cy as isize + 1, cz as isize),
43:             (cx as isize, cy as isize - 1, cz as isize),
44:             (cx as isize, cy as isize, cz as isize + 1),
45:             (cx as isize, cy as isize, cz as isize - 1),
46:         ];
47: 
48:         for &(nx, ny, nz) in &neighbors {
49:             if nx >= 0 && nx < w as isize && ny >= 0 && ny < h as isize && nz >= 0 && nz < d as isize {
50:                 let (nx, ny, nz) = (nx as usize, ny as usize, nz as usize);
51:                 
52:                 // Light only travels through Air (or maybe we allow it to light up solid faces)
53:                 // We want to light up the faces of solid blocks! So we update the light level of ANY block.
54:                 // But light only PROPAGATES through AIR!
55:                 
56:                 let n_type = grid.get(nx, ny, nz);
57:                 let n_light = grid.get_light(nx, ny, nz);
58:                 
59:                 if n_light < next_light {
60:                     grid.set_light(nx, ny, nz, next_light);
61:                     // Only continue propagating if it's air
62:                     if n_type == VOXEL_AIR {
63:                         queue.push_back((nx, ny, nz));
64:                     }
65:                 }
66:             }
67:         }
68:     }
69: }
70: 
71: #[cfg(test)]
72: mod tests {
73:     use super::*;
74: 
75:     #[test]
76:     fn test_light_propagation() {
77:         let mut grid = VoxelGrid::new(3, 3, 3);
78:         
79:         // Setup:
80:         // A single light in the middle
81:         grid.set(1, 1, 1, VOXEL_LIGHT);
82:         // A wall blocking light
83:         grid.set(2, 1, 1, crate::domain::entities::voxel_grid::VOXEL_WALL);
84:         
85:         calculate_voxel_lighting(&mut grid);
86:         
87:         assert_eq!(grid.get_light(1, 1, 1), 15);
88:         assert_eq!(grid.get_light(1, 2, 1), 14); // Above
89:         assert_eq!(grid.get_light(2, 1, 1), 14); // Wall itself lights up
90:         assert_eq!(grid.get_light(3, 1, 1), 0);  // Behind the wall is out of bounds, so it returns 0 anyway
91:     }
92: }

