  1: use crate::domain::entities::voxel_grid::{VoxelGrid, VOXEL_AIR, VOXEL_LIGHT};
  2: use rand::RngExt;
  3: use rand::rngs::StdRng;
  4: use rand::SeedableRng;
  5: 
  6: /// A simple 3D DDA (Digital Differential Analyzer) Raycaster
  7: fn cast_ray(
  8:     grid: &VoxelGrid,
  9:     x: f32,
 10:     y: f32,
 11:     z: f32,
 12:     dx: f32,
 13:     dy: f32,
 14:     dz: f32,
 15:     max_steps: usize,
 16: ) -> Option<(usize, usize, usize, u8)> {
 17:     let step_x = if dx > 0.0 { 1 } else { -1 };
 18:     let step_y = if dy > 0.0 { 1 } else { -1 };
 19:     let step_z = if dz > 0.0 { 1 } else { -1 };
 20: 
 21:     let mut t_max_x = if dx != 0.0 { (x.floor() + if dx > 0.0 { 1.0 } else { 0.0 } - x) / dx } else { f32::INFINITY };
 22:     let mut t_max_y = if dy != 0.0 { (y.floor() + if dy > 0.0 { 1.0 } else { 0.0 } - y) / dy } else { f32::INFINITY };
 23:     let mut t_max_z = if dz != 0.0 { (z.floor() + if dz > 0.0 { 1.0 } else { 0.0 } - z) / dz } else { f32::INFINITY };
 24: 
 25:     let t_delta_x = if dx != 0.0 { (1.0 / dx).abs() } else { f32::INFINITY };
 26:     let t_delta_y = if dy != 0.0 { (1.0 / dy).abs() } else { f32::INFINITY };
 27:     let t_delta_z = if dz != 0.0 { (1.0 / dz).abs() } else { f32::INFINITY };
 28: 
 29:     let mut ix = x as isize;
 30:     let mut iy = y as isize;
 31:     let mut iz = z as isize;
 32: 
 33:     for _ in 0..max_steps {
 34:         if t_max_x < t_max_y {
 35:             if t_max_x < t_max_z {
 36:                 ix += step_x;
 37:                 t_max_x += t_delta_x;
 38:             } else {
 39:                 iz += step_z;
 40:                 t_max_z += t_delta_z;
 41:             }
 42:         } else {
 43:             if t_max_y < t_max_z {
 44:                 iy += step_y;
 45:                 t_max_y += t_delta_y;
 46:             } else {
 47:                 iz += step_z;
 48:                 t_max_z += t_delta_z;
 49:             }
 50:         }
 51: 
 52:         if ix < 0 || iy < 0 || iz < 0 || ix >= grid.width() as isize || iy >= grid.height() as isize || iz >= grid.depth() as isize {
 53:             break;
 54:         }
 55: 
 56:         let vx = ix as usize;
 57:         let vy = iy as usize;
 58:         let vz = iz as usize;
 59:         
 60:         let v = grid.get(vx, vy, vz);
 61:         if v != VOXEL_AIR {
 62:             return Some((vx, vy, vz, v));
 63:         }
 64:     }
 65:     None
 66: }
 67: 
 68: /// Bakes lighting into the VoxelGrid using Monte Carlo Path Tracing
 69: pub fn bake_path_traced_lighting(grid: &mut VoxelGrid) {
 70:     let w = grid.width();
 71:     let h = grid.height();
 72:     let d = grid.depth();
 73: 
 74:     let rays_per_voxel = 64;
 75:     let max_bounces = 1; // 0 for direct only, 1 for one bounce
 76:     let max_steps = 30; // Max ray distance
 77: 
 78:     let mut rng = StdRng::seed_from_u64(42);
 79: 
 80:     // We only need to bake lighting into AIR blocks that are adjacent to solid blocks,
 81:     // but for simplicity we can bake all AIR blocks, or directly bake solid blocks.
 82:     // Actually, baking solid blocks is better. We evaluate light slightly outside the solid block face.
 83:     // Since our map_voxel_grid just uses `grid.get_light(x, y, z)` for the solid block itself,
 84:     // we can just store the light level in the solid block!
 85: 
 86:     for z in 0..d {
 87:         for y in 0..h {
 88:             for x in 0..w {
 89:                 let v = grid.get(x, y, z);
 90:                 if v == VOXEL_AIR || v == VOXEL_LIGHT {
 91:                     continue;
 92:                 }
 93: 
 94:                 // It's a solid block. Let's do path tracing from its center slightly offset by normals.
 95:                 // To keep it simple, we shoot rays from the center of the block. If it immediately hits itself,
 96:                 // we ignore it. Actually, start rays from the adjacent AIR voxels.
 97:                 
 98:                 let mut total_light = 0.0;
 99:                 
100:                 // Find an adjacent air voxel to act as the emission point
101:                 let mut px = x as f32 + 0.5;
102:                 let mut py = y as f32 + 0.5;
103:                 let mut pz = z as f32 + 0.5;
104:                 
105:                 // Shift point slightly towards the air
106:                 if x > 0 && grid.get(x - 1, y, z) == VOXEL_AIR { px -= 0.55; }
107:                 else if x < w - 1 && grid.get(x + 1, y, z) == VOXEL_AIR { px += 0.55; }
108:                 else if y > 0 && grid.get(x, y - 1, z) == VOXEL_AIR { py -= 0.55; }
109:                 else if y < h - 1 && grid.get(x, y + 1, z) == VOXEL_AIR { py += 0.55; }
110:                 else if z > 0 && grid.get(x, y, z - 1) == VOXEL_AIR { pz -= 0.55; }
111:                 else if z < d - 1 && grid.get(x, y, z + 1) == VOXEL_AIR { pz += 0.55; }
112:                 else {
113:                     continue; // Completely surrounded by solids, no light needed
114:                 }
115: 
116:                 for _ in 0..rays_per_voxel {
117:                     // Random spherical direction
118:                     let theta = rng.random::<f32>() * 2.0 * std::f32::consts::PI;
119:                     let phi = (rng.random::<f32>() * 2.0 - 1.0).acos();
120:                     let dx = phi.sin() * theta.cos();
121:                     let dy = phi.cos();
122:                     let dz = phi.sin() * theta.sin();
123: 
124:                     if let Some((_hx, _hy, _hz, hit_type)) = cast_ray(grid, px, py, pz, dx, dy, dz, max_steps) {
125:                         if hit_type == VOXEL_LIGHT {
126:                             total_light += 1.0;
127:                         } else if max_bounces > 0 {
128:                             // Secondary bounce (simplified)
129:                             // We don't do a full recursive call to avoid stack/performance issues,
130:                             // just a small probability addition to simulate ambient bounce.
131:                             // If we hit a wall, it bounces a bit of light.
132:                             total_light += 0.05; 
133:                         }
134:                     }
135:                 }
136: 
137:                 // Normalize and map to 0-15 scale for compatibility with voxel_mapper
138:                 let mut light_level = ((total_light / rays_per_voxel as f32) * 15.0 * 2.0) as u8; 
139:                 if light_level > 15 { light_level = 15; }
140:                 
141:                 grid.set_light(x, y, z, light_level);
142:             }
143:         }
144:     }
145: }

