  1: use crate::domain::entities::voxel_grid::VoxelGrid;
  2: use crate::adapters::voxel_mapper::VoxelMapper;
  3: use crate::adapters::json_presenter::JsonPresenter;
  4: use crate::domain::use_cases::build_octree::BuildOctreeUseCase;
  5: use crate::adapters::octree_gpu_serializer::OctreeGpuSerializer;
  6: 
  7: /// WebRendererAdapter acts as a Presenter in Clean Architecture.
  8: /// It translates the core domain object (VoxelGrid) into formats
  9: /// suitable for the Web Presentation layer.
 10: pub struct WebRendererAdapter;
 11: 
 12: impl WebRendererAdapter {
 13:     /// Translates VoxelGrid into a JSON string representing greedy-meshed quads.
 14:     pub fn to_json(grid: &VoxelGrid, _chunk_size: f32) -> String {
 15:         let mapper = VoxelMapper::new(0.1);
 16:         let quads = mapper.map_voxel_grid(grid);
 17:         JsonPresenter::render_voxels(&quads)
 18:     }
 19: 
 20:     /// Converts VoxelGrid into a Sparse Voxel Octree (SVO) and serializes
 21:     /// the flattened node texture buffer and structural metadata to JSON.
 22:     pub fn to_octree_json(grid: &VoxelGrid, depth: u32, world_size: f32) -> String {
 23:         let builder = BuildOctreeUseCase::new();
 24:         let svo = builder.execute(grid, depth, world_size);
 25:         let gpu_data = OctreeGpuSerializer::serialize_to_gpu_data(&svo);
 26: 
 27:         let mut json = String::with_capacity(gpu_data.texel_data.len() * 8 + 128);
 28:         json.push_str("{\"root\":");
 29:         json.push_str(&svo.root.to_string());
 30:         json.push_str(",\"depth\":");
 31:         json.push_str(&svo.depth.to_string());
 32:         json.push_str(",\"world_size\":");
 33:         json.push_str(&svo.world_size.to_string());
 34:         json.push_str(",\"nodes\":[");
 35: 
 36:         for (i, &val) in gpu_data.texel_data.iter().enumerate() {
 37:             json.push_str(&val.to_string());
 38:             if i < gpu_data.texel_data.len() - 1 {
 39:                 json.push(',');
 40:             }
 41:         }
 42:         json.push_str("]}");
 43:         json
 44:     }
 45: 
 46:     /// High-performance Binary Serializer for SVO Raymarching:
 47:     /// Compiles SVO nodes directly to little-endian bytes to avoid JSON parsing cost.
 48:     ///
 49:     /// BINARY SCHEMATIC (Byte offset -> payload):
 50:     /// - `0..4`: `root` node index (u32, little-endian)
 51:     /// - `4..8`: `depth` of tree (u32, little-endian)
 52:     /// - `8..12`: `world_size` scale (f32, little-endian)
 53:     /// - `12..16`: `texture_width` (u32, little-endian)
 54:     /// - `16..20`: `texture_height` (u32, little-endian)
 55:     /// - `20..24`: `voxel_scale` (f32, little-endian)
 56:     /// - `24..28`: `chunk_size` (f32, little-endian)
 57:     /// - `28..`: flat `u32` texel array data (4 * width * height * 4 bytes)
 58:     pub fn to_octree_binary(
 59:         grid: &VoxelGrid,
 60:         depth: u32,
 61:         world_size: f32,
 62:         voxel_scale: f32,
 63:         chunk_size: f32,
 64:     ) -> Vec<u8> {
 65:         let builder = BuildOctreeUseCase::new();
 66:         let svo = builder.execute(grid, depth, world_size);
 67:         let gpu_data = OctreeGpuSerializer::serialize_to_gpu_data(&svo);
 68: 
 69:         let header_size = 28; // 7 values * 4 bytes
 70:         let mut binary = Vec::with_capacity(header_size + gpu_data.texel_data.len() * 4);
 71: 
 72:         binary.extend_from_slice(&(svo.root as u32).to_le_bytes());
 73:         binary.extend_from_slice(&depth.to_le_bytes());
 74:         binary.extend_from_slice(&world_size.to_le_bytes());
 75:         binary.extend_from_slice(&gpu_data.texture_width.to_le_bytes());
 76:         binary.extend_from_slice(&gpu_data.texture_height.to_le_bytes());
 77:         binary.extend_from_slice(&voxel_scale.to_le_bytes());
 78:         binary.extend_from_slice(&chunk_size.to_le_bytes());
 79: 
 80:         for &val in &gpu_data.texel_data {
 81:             binary.extend_from_slice(&val.to_le_bytes());
 82:         }
 83: 
 84:         binary
 85:     }
 86: }
 87: 
 88: #[cfg(test)]
 89: mod tests {
 90:     use super::*;
 91:     use crate::domain::entities::voxel_grid::VOXEL_WALL;
 92: 
 93:     #[test]
 94:     fn test_to_json_format() {
 95:         let mut grid = VoxelGrid::new(2, 2, 2);
 96:         grid.set(0, 0, 0, VOXEL_WALL);
 97:         let json = WebRendererAdapter::to_json(&grid, 2.0);
 98:         assert!(json.starts_with("["));
 99:     }
100: 
101:     #[test]
102:     fn test_to_octree_binary_format() {
103:         let mut grid = VoxelGrid::new(2, 2, 2);
104:         grid.set(0, 0, 0, VOXEL_WALL);
105:         let binary = WebRendererAdapter::to_octree_binary(&grid, 8, 25.6, 0.1, 20.0);
106:         
107:         // Header is 28 bytes
108:         assert!(binary.len() >= 28);
109:         // Total bytes must be aligned to 4-byte boundaries
110:         assert_eq!(binary.len() % 4, 0);
111:     }
112: }

files.src/use_cases/grassland_level.rs:
  1: //! Level 34-B — "The Grassland".
  2: //!
  3: //! A safe, flat, endless grass plane you can noclip into from Level 0:
  4: //! * grass ground everywhere, with smooth-noise **lakes** of shallow water,
  5: //! * scattered **trees** (solid trunk, leaf canopy) on a hashed world grid,
  6: //! * a glowing **sky layer** at the top of the grid plus dim ground glow
  7: //!   sources hidden inside the turf, so the plane reads as daylight even
  8: //!   though lighting is the same BFS flood used indoors.
  9: //!
 10: //! Like every [`LevelGenerator`], all placement is a pure function of
 11: //! world-space coordinates so chunks tile seamlessly.
 12: 
 13: use crate::domain::entities::voxel_grid::{
 14:     VoxelGrid, VOXEL_GRASS, VOXEL_LIGHT, VOXEL_TREE, VOXEL_WATER,
 15: };
 16: use crate::entities::models::Position;
 17: use crate::use_cases::generate_chunk::GeneratorConfig;
 18: use crate::use_cases::level_generator::LevelGenerator;
 19: use crate::use_cases::ports::NoiseProvider;
 20: 
 21: /// Grid height in world units; the sky glow layer sits at the top.
 22: const GRID_HEIGHT_UNITS: f32 = 5.8;
 23: /// Trees sit on a world grid of this period (units); most cells are empty.
 24: const TREE_PERIOD: f32 = 9.0;
 25: /// Ground glow sources ("sun-lit turf") every N units.
 26: const GLOW_PERIOD: f32 = 3.2;
 27: 
 28: pub struct GrasslandLevel;
 29: 
 30: impl GrasslandLevel {
 31:     /// Uniform per-cell hash in [0, 1): samples the value noise exactly on
 32:     /// its lattice (provider frequency 0.05 → inputs that are multiples of
 33:     /// 20 hit lattice points, where the noise is a raw uniform hash).
 34:     fn hash(noise: &dyn NoiseProvider, seed: u32, salt: u32, cx: i64, cz: i64) -> f32 {
 35:         let v = noise.evaluate_2d(
 36:             seed ^ salt,
 37:             Position::new(cx as f32 * 20.0, cz as f32 * 20.0),
 38:         );
 39:         (v * 0.5 + 0.5).clamp(0.0, 0.999)
 40:     }
 41: }
 42: 
 43: impl LevelGenerator for GrasslandLevel {
 44:     fn generate(
 45:         &self,
 46:         chunk_pos: Position,
 47:         seed: u32,
 48:         config: GeneratorConfig,
 49:         noise: &dyn NoiseProvider,
 50:     ) -> VoxelGrid {
 51:         let s = config.voxel_scale;
 52:         let width = (config.chunk_size / s) as usize;
 53:         let depth = (config.chunk_size / s) as usize;
 54:         let height = (GRID_HEIGHT_UNITS / s) as usize;
 55:         let mut grid = VoxelGrid::new(width, height, depth);
 56:         let sky_y = height - 1;
 57: 
 58:         for z in 0..depth {
 59:             for x in 0..width {
 60:                 let wx = chunk_pos.x + (x as f32 + 0.5) * s;
 61:                 let wz = chunk_pos.z + (z as f32 + 0.5) * s;
 62: 
 63:                 // Lakes: smooth blobs of the world-space noise field.
 64:                 let lake = noise.evaluate_2d(seed ^ 0x1A5E, Position::new(wx * 0.7, wz * 0.7));
 65:                 let ground = if lake > 0.62 { VOXEL_WATER } else { VOXEL_GRASS };
 66:                 grid.set(x, 0, z, ground);
 67: 
 68:                 // Sky glow: an unbroken luminous layer overhead.
 69:                 grid.set(x, sky_y, z, VOXEL_LIGHT);
 70: 
 71:                 // Ground glow grid keeps the turf bright at eye level (the
 72:                 // BFS light from the sky layer alone fades before the floor).
 73:                 let gx = wx.rem_euclid(GLOW_PERIOD);
 74:                 let gz = wz.rem_euclid(GLOW_PERIOD);
 75:                 if ground == VOXEL_GRASS && gx < s && gz < s {
 76:                     grid.set(x, 0, z, VOXEL_LIGHT);
 77:                 }
 78: 
 79:                 // Trees: hashed world cells, never in water.
 80:                 let cell_x = (wx / TREE_PERIOD).floor() as i64;
 81:                 let cell_z = (wz / TREE_PERIOD).floor() as i64;
 82:                 if Self::hash(noise, seed, 0x7EE5, cell_x, cell_z) > 0.6 && ground == VOXEL_GRASS {
 83:                     // Trunk position jittered inside the cell.
 84:                     let jx = Self::hash(noise, seed, 0x7EE6, cell_x, cell_z) * (TREE_PERIOD - 2.0)
 85:                         + 1.0;
 86:                     let jz = Self::hash(noise, seed, 0x7EE7, cell_x, cell_z) * (TREE_PERIOD - 2.0)
 87:                         + 1.0;
 88:                     let tx = cell_x as f32 * TREE_PERIOD + jx;
 89:                     let tz = cell_z as f32 * TREE_PERIOD + jz;
 90:                     let dx = wx - tx;
 91:                     let dz = wz - tz;
 92:                     let d2 = dx * dx + dz * dz;
 93: 
 94:                     let trunk_top = (2.2 / s) as usize;
 95:                     let canopy_top = (3.6 / s) as usize;
 96:                     if d2 < (0.25f32).powi(2) {
 97:                         for y in 1..trunk_top.min(height - 2) {
 98:                             grid.set(x, y, z, VOXEL_TREE);
 99:                         }
100:                     }
101:                     if d2 < (1.6f32).powi(2) {
102:                         for y in trunk_top..canopy_top.min(height - 2) {
103:                             grid.set(x, y, z, VOXEL_GRASS);
104:                         }
105:                     }
106:                 }
107:             }
108:         }
109: 
110:         grid
111:     }
112: }
113: 
114: #[cfg(test)]
115: mod tests {
116:     use super::*;
117:     use crate::frameworks_drivers::simple_noise::SimpleNoiseProvider;
118: 
119:     fn generate(ox: f32, oz: f32) -> VoxelGrid {
120:         GrasslandLevel.generate(
121:             Position::new(ox, oz),
122:             42,
123:             GeneratorConfig::low_spec(),
124:             &SimpleNoiseProvider::new(),
125:         )
126:     }
127: 
128:     #[test]
129:     fn grassland_has_grass_sky_and_open_walkway() {
130:         let grid = generate(0.0, 0.0);
131:         let sky_y = grid.height() - 1;
132:         let mut grass = 0;
133:         let mut open_at_eye = 0;
134:         for z in 0..grid.depth() {
135:             for x in 0..grid.width() {
136:                 assert_eq!(grid.get(x, sky_y, z), VOXEL_LIGHT, "sky layer must glow");
137:                 let g = grid.get(x, 0, z);
138:                 if g == VOXEL_GRASS || g == VOXEL_LIGHT {
139:                     grass += 1;
140:                 }
141:                 if grid.get(x, 8, z) == 0 {
142:                     open_at_eye += 1; // eye height 1.7 u = voxel y 8
143:                 }
144:             }
145:         }
146:         let total = grid.width() * grid.depth();
147:         assert!(grass > total / 2, "mostly grass, got {grass}/{total}");
148:         assert!(open_at_eye > total * 9 / 10, "plane must be open at eye height");
149:     }
150: 
151:     #[test]
152:     fn grassland_scatters_trees_deterministically() {
153:         let a = generate(0.0, 0.0);
154:         let b = generate(0.0, 0.0);
155:         let mut trees = 0;
156:         for z in 0..a.depth() {
157:             for x in 0..a.width() {
158:                 assert_eq!(a.get(x, 3, z), b.get(x, 3, z), "must be deterministic");
159:                 if a.get(x, 3, z) == VOXEL_TREE {
160:                     trees += 1;
161:                 }
162:             }
163:         }
164:         // Trees are sparse but should exist across a few chunks.
165:         let mut total_trees = trees;
166:         for (ox, oz) in [
167:             (10.0, 0.0),
168:             (0.0, 10.0),
169:             (10.0, 10.0),
170:             (-10.0, 0.0),
171:             (0.0, -10.0),
172:             (-10.0, -10.0),
173:             (20.0, 0.0),
174:             (0.0, 20.0),
175:         ] {
176:             let g = generate(ox, oz);
177:             for z in 0..g.depth() {
178:                 for x in 0..g.width() {
179:                     if g.get(x, 3, z) == VOXEL_TREE {
180:                         total_trees += 1;
181:                     }
182:                 }
183:             }
184:         }
185:         assert!(total_trees > 0, "expected at least one tree trunk in 4 chunks");
186:     }
187: }

files.src/use_cases/ports.rs:
 1: use crate::entities::models::Position;
 2: 
 3: /// The Ports layer implements the Dependency Inversion Principle (SOLID).
 4: /// Instead of the Use Cases depending on a concrete external noise library or framework,
 5: /// the Use Cases define the interface (Port) they need, and the external layers
 6: /// (Adapters/Drivers) must implement this interface.
 7: 
 8: /// NoiseProvider is a pure interface for extracting deterministic continuous noise.
 9: /// We use this to evaluate the Macro Field (Drift, Density, Motif Selection).
10: pub trait NoiseProvider {
11:     /// Returns a noise value, ideally in the range [-1.0, 1.0].
12:     /// The function must be deterministic given the same seed and position.
13:     fn evaluate_2d(&self, seed: u32, position: Position) -> f32;
14: }
15: 
16: /// TelemetryPort abstracts wall-clock access and log emission so Use Cases
17: /// never touch `std::time` or stdout directly. Both are frameworks concerns,
18: /// and `SystemTime::now()` panics on `wasm32-unknown-unknown`.
19: pub trait TelemetryPort {
20:     /// Monotonic-ish timestamp in microseconds from an arbitrary epoch.
21:     /// Only ever used to compute durations, never absolute dates.
22:     fn now_micros(&self) -> u64;
23:     /// Emits one log line to whatever sink the outer layer provides.
24:     fn log(&self, message: &str);
25: }
26: 
27: /// Silent TelemetryPort used by default and in tests.
28: pub struct NullTelemetry;
29: 
30: impl TelemetryPort for NullTelemetry {
31:     fn now_micros(&self) -> u64 { 0 }
32:     fn log(&self, _message: &str) {}
33: }
34: 
35: /// Shared instance so constructors can hand out `&'static dyn TelemetryPort`
36: /// without forcing callers to own a telemetry object.
37: pub static NULL_TELEMETRY: NullTelemetry = NullTelemetry;

