 10: use vackrooms::use_cases::generate_chunk::GenerateChunkArchitectureUseCase;
 11: 
 12: /// Presentation Layer & Driver:
 13: /// A minimalist, zero-dependency HTTP server that connects our 
 14: /// Clean Architecture engine to the Browser Voxel Renderer.
 15: fn main() {
 16:     let port = 8080;
 17:     let listener = TcpListener::bind(format!("127.0.0.1:{}", port)).unwrap();
 18:     println!("--- Backrooms Engine Running ---");
 19:     println!("Server listening on http://localhost:{}", port);
 20:     println!("Open the above URL in your browser to view the Voxel Rendering.");
 21: 
 22:     for stream in listener.incoming() {
 23:         match stream {
 24:             Ok(stream) => {
 25:                 thread::spawn(move || {
 26:                     handle_client(stream);
 27:                 });
 28:             }
 29:             Err(e) => {
 30:                 eprintln!("Failed to accept connection: {}", e);
 31:             }
 32:         }
 33:     }
 34: }
 35: 
 36: fn handle_client(mut stream: TcpStream) {
 37:     let mut buffer = [0; 1024];
 38:     if let Ok(bytes_read) = stream.read(&mut buffer) {
 39:         if bytes_read == 0 {
 40:             return;
 41:         }
 42: 
 43:         let request = String::from_utf8_lossy(&buffer[..bytes_read]);
 44:         let request_line = request.lines().next().unwrap_or("");
 45:         
 46:         if request_line.starts_with("GET /maze") {
 47:             // Serve the Procedural Voxel Data with support for coordinate query parameters
 48:             let parts: Vec<&str> = request_line.split_whitespace().collect();
 49:             let url = parts.get(1).unwrap_or(&"/maze");
 50:             
 51:             let mut chunk_x = 0.0;
 52:             let mut chunk_z = 0.0;
 53:             let mut spec = "high";
 54:             
 55:             if let Some(query_idx) = url.find('?') {
 56:                 let query = &url[query_idx + 1..];
 57:                 for param in query.split('&') {
 58:                     let key_val: Vec<&str> = param.split('=').collect();
 59:                     if key_val.len() == 2 {
 60:                         match key_val[0] {
 61:                             "x" => chunk_x = key_val[1].parse().unwrap_or(0.0),
 62:                             "z" => chunk_z = key_val[1].parse().unwrap_or(0.0),
 63:                             "spec" => spec = key_val[1],
 64:                             _ => {}
 65:                         }
 66:                     }
 67:                 }
 68:             }
 69:             
 70:             let config = if spec == "low" {
 71:                 vackrooms::use_cases::generate_chunk::GeneratorConfig::low_spec()
 72:             } else {
 73:                 vackrooms::use_cases::generate_chunk::GeneratorConfig::high_spec()
 74:             };
 75:             
 76:             let noise_provider = SimpleNoiseProvider::new();
 77:             let telemetry = StdTelemetry;
 78:             let generator = GenerateChunkArchitectureUseCase::with_telemetry(&noise_provider, &telemetry);
 79:             
 80:             let chunk = generator.execute(Position::new(chunk_x, chunk_z), 42, config);
 81:             
 82:             // Adapt to Web Format (greedy meshed faces)
 83:             let json = WebRendererAdapter::to_json(&chunk, config.chunk_size);
 84:             
 85:             let response = format!(
 86:                 "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
 87:                 json.len(),
 88:                 json
 89:             );
 90:             let _ = stream.write_all(response.as_bytes());
 91:             
 92:         } else if request_line.starts_with("GET /octree") {
 93:             // Serve the SVO Packed Data
 94:             let parts: Vec<&str> = request_line.split_whitespace().collect();
 95:             let url = parts.get(1).unwrap_or(&"/octree");
 96:             
 97:             let mut chunk_x = 0.0;
 98:             let mut chunk_z = 0.0;
 99:             let mut spec = "high";
100:             
101:             if let Some(query_idx) = url.find('?') {
102:                 let query = &url[query_idx + 1..];
103:                 for param in query.split('&') {
104:                     let key_val: Vec<&str> = param.split('=').collect();
105:                     if key_val.len() == 2 {
106:                         match key_val[0] {
107:                             "x" => chunk_x = key_val[1].parse().unwrap_or(0.0),
108:                             "z" => chunk_z = key_val[1].parse().unwrap_or(0.0),
109:                             "spec" => spec = key_val[1],
110:                             _ => {}
111:                         }
112:                     }
113:                 }
114:             }
115:             
116:             let config = if spec == "low" {
117:                 vackrooms::use_cases::generate_chunk::GeneratorConfig::low_spec()
118:             } else {
119:                 vackrooms::use_cases::generate_chunk::GeneratorConfig::high_spec()
120:             };
121:             
122:             let noise_provider = SimpleNoiseProvider::new();
123:             let telemetry = StdTelemetry;
124:             let generator = GenerateChunkArchitectureUseCase::with_telemetry(&noise_provider, &telemetry);
125:             
126:             // Generate chunk at position with GeneratorConfig
127:             let chunk = generator.execute(Position::new(chunk_x, chunk_z), 42, config);
128:             
129:             // Adapt to Web Format using SVO representation
130:             let depth = config.svo_depth();
131:             let world_size = config.svo_world_size();
132:             let binary = WebRendererAdapter::to_octree_binary(&chunk, depth, world_size, config.voxel_scale, config.chunk_size);
133:             
134:             let header = format!(
135:                 "HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: {}\r\n\r\n",
136:                 binary.len()
137:             );
138:             let mut response = Vec::with_capacity(header.len() + binary.len());
139:             response.extend_from_slice(header.as_bytes());
140:             response.extend_from_slice(&binary);
141:             let _ = stream.write_all(&response);
142: 
143:         } else if request_line.starts_with("GET ") {
144:             // Static file service for the wasm front end (and the legacy page).
145:             let parts: Vec<&str> = request_line.split_whitespace().collect();
146:             let url = parts.get(1).unwrap_or(&"/");
147:             let path = url.split('?').next().unwrap_or("/");
148:             serve_static(&mut stream, path);
149:         } else {
150:             let error = "HTTP/1.1 404 Not Found\r\n\r\n";
151:             let _ = stream.write_all(error.as_bytes());
152:         }
153:     }
154: }
155: 
156: /// Maps a URL path to a file under `static/` and serves it with the correct
157: /// MIME type. `application/wasm` matters: browsers refuse to instantiate
158: /// wasm streams served under the wrong content type.
159: fn serve_static(stream: &mut TcpStream, url_path: &str) {
160:     let relative = match url_path {
161:         "/" | "/index.html" => "index.html",
162:         "/legacy" => "legacy_threejs.html",
163:         other => other.trim_start_matches('/'),
164:     };
165: 
166:     // Path traversal guard: reject anything trying to escape `static/`.
167:     if relative.split('/').any(|seg| seg == "..") || relative.contains('\\') {
168:         let _ = stream.write_all(b"HTTP/1.1 403 Forbidden\r\n\r\n");
169:         return;
170:     }
171: 
172:     let file_path = format!("static/{}", relative);
173:     match fs::read(&file_path) {
174:         Ok(body) => {
175:             let mime = match file_path.rsplit('.').next() {
176:                 Some("html") => "text/html; charset=utf-8",
177:                 Some("js") | Some("mjs") => "text/javascript",
178:                 Some("wasm") => "application/wasm",
179:                 Some("css") => "text/css",
180:                 Some("json") => "application/json",
181:                 Some("png") => "image/png",
182:                 _ => "application/octet-stream",
183:             };
184:             let header = format!(
185:                 "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\n\r\n",
186:                 mime,
187:                 body.len()
188:             );
189:             let mut response = Vec::with_capacity(header.len() + body.len());
190:             response.extend_from_slice(header.as_bytes());
191:             response.extend_from_slice(&body);
192:             let _ = stream.write_all(&response);
193:         }
194:         Err(_) => {
195:             let _ = stream.write_all(b"HTTP/1.1 404 Not Found\r\n\r\nFile not found.");
196:         }
197:     }
198: }

