  1: /// Collision Diagnostic Tests — TDD Phase 1
  2: ///
  3: /// WHY THESE TESTS EXIST:
  4: /// The player reported spawning inside a wall.  Before changing any logic
  5: /// we must prove (a) what coordinates the spawn point produces and (b) whether
  6: /// the floor voxel's collision box overlaps the player's AABB at spawn.
  7: ///
  8: /// Test-first order:
  9: ///   1. Prove the exact world-space coordinates the chunk generator places floor/wall
 10: ///      voxels at for the (0,0) hub chunk in low-spec mode.
 11: ///   2. Prove the spawn point (5.0, 1.7, 5.0) does NOT overlap any wall voxel.
 12: ///   3. Prove the floor voxel box does NOT block the player at spawn.
 13: ///   4. Prove terminal velocity is sane (<= 5 world-units/second).
 14: ///
 15: /// If test 2 or 3 fails, it proves the bug.  Then we add a fix and verify
 16: /// the test passes.
 17: 
 18: use vackrooms::use_cases::generate_chunk::{GenerateChunkArchitectureUseCase, GeneratorConfig};
 19: use vackrooms::entities::models::Position;
 20: use vackrooms::frameworks_drivers::simple_noise::SimpleNoiseProvider;
 21: use vackrooms::domain::entities::voxel_grid::{VOXEL_WALL, VOXEL_FLOOR};
 22: 
 23: /// The JavaScript side extracts wall collision boxes from the SVO.
 24: /// This Rust analogue extracts the same information directly from the VoxelGrid
 25: /// so we can verify coordinates without the JS/SVO layer.
 26: fn grid_wall_boxes_at_spawn_x(chunk_x: f32, chunk_z: f32) -> Vec<(f32, f32, f32, f32, f32, f32)> {
 27:     // Returns (minX, maxX, minY, maxY, minZ, maxZ) for every solid wall voxel
 28:     // at approximately x=5 world-units inside the chunk.
 29:     let config = GeneratorConfig::low_spec();
 30:     let noise = SimpleNoiseProvider::new();
 31:     let generator = GenerateChunkArchitectureUseCase::new(&noise);
 32:     let grid = generator.execute(Position::new(chunk_x, chunk_z), 42, config);
 33: 
 34:     let scale = config.voxel_scale;
 35:     let mut boxes = vec![];
 36: 
 37:     for y in 0..grid.height() {
 38:         for z in 0..grid.depth() {
 39:             for x in 0..grid.width() {
 40:                 let vt = grid.get(x, y, z);
 41:                 if vt == VOXEL_WALL {
 42:                     let wx = chunk_x + x as f32 * scale;
 43:                     let wy = y as f32 * scale;
 44:                     let wz = chunk_z + z as f32 * scale;
 45:                     // The JS collision system gives walls a 1-voxel-size box
 46:                     boxes.push((wx, wx + scale, wy, wy + scale, wz, wz + scale));
 47:                 }
 48:             }
 49:         }
 50:     }
 51:     boxes
 52: }
 53: 
 54: fn floor_boxes(chunk_x: f32, chunk_z: f32) -> Vec<(f32, f32, f32, f32, f32, f32)> {
 55:     let config = GeneratorConfig::low_spec();
 56:     let noise = SimpleNoiseProvider::new();
 57:     let generator = GenerateChunkArchitectureUseCase::new(&noise);
 58:     let grid = generator.execute(Position::new(chunk_x, chunk_z), 42, config);
 59: 
 60:     let scale = config.voxel_scale;
 61:     let mut boxes = vec![];
 62: 
 63:     for z in 0..grid.depth() {
 64:         for x in 0..grid.width() {
 65:             let vt = grid.get(x, 0, z);
 66:             if vt == VOXEL_FLOOR {
 67:                 let wx = chunk_x + x as f32 * scale;
 68:                 let wz = chunk_z + z as f32 * scale;
 69:                 // Floor voxel: y=0 to y=scale
 70:                 boxes.push((wx, wx + scale, 0.0_f32, scale, wz, wz + scale));
 71:             }
 72:         }
 73:     }
 74:     boxes
 75: }
 76: 
 77: /// Player AABB: eye-level at pos.y, feet at pos.y - 1.65, head at pos.y + 0.1
 78: fn player_overlaps(pos: (f32, f32, f32), radius: f32, vbox: (f32, f32, f32, f32, f32, f32)) -> bool {
 79:     let (px, py, pz) = pos;
 80:     let p_min_x = px - radius;
 81:     let p_max_x = px + radius;
 82:     let p_min_y = py - 1.65;
 83:     let p_max_y = py + 0.1;
 84:     let p_min_z = pz - radius;
 85:     let p_max_z = pz + radius;
 86:     let (v_min_x, v_max_x, v_min_y, v_max_y, v_min_z, v_max_z) = vbox;
 87: 
 88:     p_max_x > v_min_x && p_min_x < v_max_x &&
 89:     p_max_y > v_min_y && p_min_y < v_max_y &&
 90:     p_max_z > v_min_z && p_min_z < v_max_z
 91: }
 92: 
 93: // ============================================================
 94: // TEST 1: Verify hub chunk (0,0) has walls only on boundary
 95: // ============================================================
 96: #[test]
 97: fn test_hub_chunk_interior_is_wall_free() {
 98:     // The hub chunk (0,0) is supposed to be an open plaza.
 99:     // No wall voxels should exist at x≈5.0, z≈5.0 (centre of chunk).
100:     let walls = grid_wall_boxes_at_spawn_x(0.0, 0.0);
101: 
102:     let spawn = (5.0_f32, 1.7_f32, 5.0_f32);
103:     let radius = 0.35_f32;
104: 
105:     let overlapping: Vec<_> = walls.iter()
106:         .filter(|&&b| player_overlaps(spawn, radius, b))
107:         .collect();
108: 
109:     assert!(
110:         overlapping.is_empty(),
111:         "FAIL: Spawn point {:?} overlaps {} wall voxel(s).\n\
112:          First overlap: {:?}\n\
113:          This proves the spawn-in-wall bug.",
114:         spawn, overlapping.len(), overlapping.first()
115:     );
116: }
117: 
118: // ============================================================
119: // TEST 2: DIAGNOSTIC — floor geometry overlaps player AABB.
120: // This test is marked #[should_panic] because the floor voxels
121: // DO geometrically overlap the player.  The fix is applied in JS
122: // (extractSvoCollisions only passes WALL/RED_WALL to isColliding).
123: // This test is kept as living documentation of the bug's root cause.
124: // ============================================================
125: #[test]
126: #[should_panic(expected = "Floor voxels at spawn OVERLAP")]
127: fn test_floor_geometry_overlaps_player_proving_the_bug() {
128:     // Floor voxels are at y=0 to y=voxel_scale (0.2 for low-spec).
129:     // Player feet: pos.y - 1.65 = 1.7 - 1.65 = 0.05.
130:     // If pMinY(0.05) < vMaxY(0.2) AND pMaxY(1.8) > vMinY(0.0) → geometric overlap.
131:     // This test PROVES the overlap exists in the geometry.
132:     // The JS fix excludes floor boxes from isColliding() — see extractSvoCollisions().
133:     let floors = floor_boxes(0.0, 0.0);
134:     let spawn = (5.0_f32, 1.7_f32, 5.0_f32);
135:     let radius = 0.35_f32;
136: 
137:     let floor_at_spawn: Vec<_> = floors.iter()
138:         .filter(|&&b| player_overlaps(spawn, radius, b))
139:         .collect();
140: 
141:     assert!(
142:         floor_at_spawn.is_empty(),
143:         "FAIL: Floor voxels at spawn OVERLAP the player AABB.\n\
144:          Count: {}\n\
145:          This causes the player to spawn 'stuck' and unable to move.\n\
146:          Fix: exclude FLOOR and CEILING voxels from collision extraction.\n\
147:          First overlapping floor box: {:?}",
148:         floor_at_spawn.len(), floor_at_spawn.first()
149:     );
150: }
151: 
152: 
153: // ============================================================
154: // TEST 3: Terminal velocity must be sane (≤ 5 world-units/second)
155: // ============================================================
156: #[test]
157: fn test_terminal_velocity_is_sane() {
158:     // JS formula: velocity.z -= direction.z * speed * delta
159:     //             velocity.z -= velocity.z * friction * delta   (drag)
160:     // Terminal velocity = speed / friction
161:     let speed: f32 = 4.0;    // target walk speed (world units/sec)
162:     let friction: f32 = 10.0; // damping coefficient
163:     let terminal = speed / friction;
164: 
165:     // The old code used speed=15.0 → terminal = 1.5 units/frame @60fps = 90 u/s
166:     assert!(
167:         terminal <= 5.0,
168:         "FAIL: Terminal velocity {:.2} u/s exceeds 5 u/s.\n\
169:          This causes the 'too fast' movement bug.\n\
170:          Use speed <= {:.1} with friction = {:.1}",
171:         terminal, friction * 5.0, friction
172:     );
173: }
174: 
175: // ============================================================
176: // TEST 4: Fix verification — wall-only collision boxes do NOT
177: //         overlap the player at spawn.
178: //         This test must PASS after the production fix is applied.
179: // ============================================================
180: #[test]
181: fn test_fix_only_walls_collide_at_spawn() {
182:     // After the fix: extractSvoCollisions should only emit voxelType==WALL (1)
183:     // or RED_WALL (5).  Floor (2) and Ceiling (3) must be excluded.
184:     // The wall_boxes helper already filters by VOXEL_WALL only.
185:     let walls = grid_wall_boxes_at_spawn_x(0.0, 0.0);
186:     let spawn = (5.0_f32, 1.7_f32, 5.0_f32);
187:     let radius = 0.35_f32;
188: 
189:     let blocked: Vec<_> = walls.iter()
190:         .filter(|&&b| player_overlaps(spawn, radius, b))
191:         .collect();
192: 
193:     assert!(
194:         blocked.is_empty(),
195:         "FAIL: Player still collides with {} wall box(es) at spawn even after floor fix.\n\
196:          First collision: {:?}\n\
197:          This is a separate bug — the hub chunk has a wall at the spawn point.",
198:         blocked.len(), blocked.first()
199:     );
200: }

files.wasm_frontend/src/adapters/input.rs:
  1: //! Input adapter: accumulates raw browser events (key codes, mouse deltas,
  2: //! pointer-lock state) and translates them into one [`InputFrame`] per tick.
  3: //!
  4: //! The driver layer feeds this from DOM event listeners; the frame loop
  5: //! drains it with [`InputCollector::take_frame`]. Keeping the mapping here —
  6: //! not in the driver — means "which key means forward" is a testable rule,
  7: //! not something buried in an event closure.
  8: 
  9: use crate::application::engine::InputFrame;
 10: use crate::application::player::MoveIntent;
 11: 
 12: #[derive(Debug, Default)]
 13: pub struct InputCollector {
 14:     intent: MoveIntent,
 15:     pending_dx: f32,
 16:     pending_dy: f32,
 17:     locked: bool,
 18: }
 19: 
 20: impl InputCollector {
 21:     pub fn new() -> Self {
 22:         Self::default()
 23:     }
 24: 
 25:     /// Handles a keydown/keyup pair by `KeyboardEvent.code` value.
 26:     /// Unknown codes are ignored. Both WASD and arrow keys are mapped.
 27:     pub fn key_event(&mut self, code: &str, pressed: bool) {
 28:         match code {
 29:             "KeyW" | "ArrowUp" => self.intent.forward = pressed,
 30:             "KeyS" | "ArrowDown" => self.intent.backward = pressed,
 31:             "KeyA" | "ArrowLeft" => self.intent.left = pressed,
 32:             "KeyD" | "ArrowRight" => self.intent.right = pressed,
 33:             _ => {}
 34:         }
 35:     }
 36: 
 37:     /// Accumulates a mouse movement (only meaningful while pointer-locked).
 38:     pub fn mouse_delta(&mut self, dx: f32, dy: f32) {
 39:         if self.locked {
 40:             self.pending_dx += dx;
 41:             self.pending_dy += dy;
 42:         }
 43:     }
 44: 
 45:     /// Pointer lock engaged/released. Releasing clears held keys so the
 46:     /// player doesn't keep walking while the overlay is up.
 47:     pub fn set_locked(&mut self, locked: bool) {
 48:         self.locked = locked;
 49:         if !locked {
 50:             self.intent = MoveIntent::default();
 51:             self.pending_dx = 0.0;
 52:             self.pending_dy = 0.0;
 53:         }
 54:     }
 55: 
 56:     pub fn is_locked(&self) -> bool {
 57:         self.locked
 58:     }
 59: 
 60:     /// Drains accumulated input into a frame snapshot. Mouse deltas reset;
 61:     /// key intent persists until the matching keyup.
 62:     pub fn take_frame(&mut self) -> InputFrame {
 63:         let frame = InputFrame {
 64:             intent: self.intent,
 65:             look_dx: self.pending_dx,
 66:             look_dy: self.pending_dy,
 67:             locked: self.locked,
 68:         };
 69:         self.pending_dx = 0.0;
 70:         self.pending_dy = 0.0;
 71:         frame
 72:     }
 73: }
 74: 
 75: #[cfg(test)]
 76: mod tests {
 77:     use super::*;
 78: 
 79:     #[test]
 80:     fn wasd_maps_to_intent_and_persists_across_frames() {
 81:         let mut input = InputCollector::new();
 82:         input.set_locked(true);
 83:         input.key_event("KeyW", true);
 84:         input.key_event("KeyD", true);
 85:         let f1 = input.take_frame();
 86:         assert!(f1.intent.forward && f1.intent.right);
 87:         let f2 = input.take_frame();
 88:         assert!(f2.intent.forward, "held keys persist");
 89:         input.key_event("KeyW", false);
 90:         assert!(!input.take_frame().intent.forward);
 91:     }
 92: 
 93:     #[test]
 94:     fn mouse_deltas_accumulate_then_drain() {
 95:         let mut input = InputCollector::new();
 96:         input.set_locked(true);
 97:         input.mouse_delta(3.0, -1.0);
 98:         input.mouse_delta(2.0, 1.0);
 99:         let f = input.take_frame();
100:         assert_eq!((f.look_dx, f.look_dy), (5.0, 0.0));
101:         let f2 = input.take_frame();
102:         assert_eq!((f2.look_dx, f2.look_dy), (0.0, 0.0));
103:     }
104: 
105:     #[test]
106:     fn unlock_clears_held_keys_and_ignores_mouse() {
107:         let mut input = InputCollector::new();
108:         input.set_locked(true);
109:         input.key_event("KeyW", true);
110:         input.set_locked(false);
111:         input.mouse_delta(10.0, 10.0);
112:         let f = input.take_frame();
113:         assert!(!f.intent.forward);
114:         assert_eq!(f.look_dx, 0.0);
115:         assert!(!f.locked);
116:     }
117: }

 1: //! URL query → generation settings. Lets players share worlds by URL:
 2: //!
 3: //! `?seed=1234&pillars=0.5&walls=1.2&atria=2&lights=0.8`
 4: //!
 5: //! * `seed`    — world seed (u32; any text is hashed so words work too).
 6: //! * `pillars` — structural column density multiplier (0 = none).
 7: //! * `walls`   — office wall density multiplier (0 = open plan).
 8: //! * `atria`   — how much of the world vaults into tall atria.
 9: //! * `lights`  — ceiling light panel density.
10: //!
11: //! All multipliers default to 1.0 and are clamped to 0..=4. Kept free of
12: //! web-sys so it is natively unit-tested; the browser driver only hands in
13: //! `window.location.search`.
14: 
15: use vackrooms::use_cases::generate_chunk::LevelTuning;
16: 
17: #[derive(Debug, Clone, Copy, PartialEq)]
18: pub struct GenerationParams {
19:     pub seed: u32,
20:     pub tuning: LevelTuning,
21: }
22: 
23: /// Parses `window.location.search` (with or without the leading `?`).
24: /// Unknown keys are ignored; malformed values fall back to defaults.
25: pub fn parse_generation_params(query: &str, default_seed: u32) -> GenerationParams {
26:     let mut params = GenerationParams { seed: default_seed, tuning: LevelTuning::default() };
27: 
28:     for pair in query.trim_start_matches('?').split('&') {
29:         let Some((key, value)) = pair.split_once('=') else { continue };
30:         let knob = |t: &mut f32| {
31:             if let Ok(v) = value.parse::<f32>() {
32:                 if v.is_finite() {
33:                     *t = v.clamp(0.0, 4.0);
34:                 }
35:             }
36:         };
37:         match key {
38:             "seed" => {
39:                 params.seed = value.parse::<u32>().unwrap_or_else(|_| hash_seed(value));
40:             }
41:             "pillars" => knob(&mut params.tuning.pillars),
42:             "walls" => knob(&mut params.tuning.walls),
43:             "atria" => knob(&mut params.tuning.atria),
44:             "lights" => knob(&mut params.tuning.lights),
45:             _ => {}
46:         }
47:     }
48:     params
49: }
50: 
51: /// Non-numeric seeds ("?seed=kitten") hash to a stable u32 (FNV-1a).
52: fn hash_seed(text: &str) -> u32 {
53:     let mut h: u32 = 0x811C_9DC5;
54:     for b in text.bytes() {
55:         h ^= b as u32;
56:         h = h.wrapping_mul(0x0100_0193);
57:     }
58:     h
59: }
60: 
61: #[cfg(test)]
62: mod tests {
63:     use super::*;
64: 
65:     #[test]
66:     fn defaults_when_query_is_empty() {
67:         let p = parse_generation_params("", 42);
68:         assert_eq!(p.seed, 42);
69:         assert_eq!(p.tuning, LevelTuning::default());
70:     }
71: 
72:     #[test]
73:     fn parses_seed_and_knobs() {
74:         let p = parse_generation_params("?seed=7&pillars=0.5&walls=2&atria=0&lights=1.5", 42);
75:         assert_eq!(p.seed, 7);
76:         assert_eq!(p.tuning.pillars, 0.5);
77:         assert_eq!(p.tuning.walls, 2.0);
78:         assert_eq!(p.tuning.atria, 0.0);
79:         assert_eq!(p.tuning.lights, 1.5);
80:     }
81: 
82:     #[test]
83:     fn text_seeds_hash_deterministically() {
84:         let a = parse_generation_params("seed=kitten", 42);
85:         let b = parse_generation_params("seed=kitten", 42);
86:         assert_eq!(a.seed, b.seed);
87:         assert_ne!(a.seed, 42);
88:     }
89: 
90:     #[test]
91:     fn junk_values_are_ignored_and_clamped() {
92:         let p = parse_generation_params("?pillars=banana&walls=99&renderer=cpu&spec=high", 42);
93:         assert_eq!(p.tuning.pillars, 1.0);
94:         assert_eq!(p.tuning.walls, 4.0);
95:     }
96: }

  1: //! Axis-aligned collision primitives and the sliding-collision world.
  2: //!
  3: //! Collision geometry is *derived from the SVO itself* (solid leaf nodes of
  4: //! type WALL / RED_WALL become world-space boxes), so the physical world and
  5: //! the rendered world can never drift apart.
  6: 
  7: /// Axis-aligned bounding box in world space.
  8: #[derive(Debug, Clone, Copy, PartialEq)]
  9: pub struct Aabb {
 10:     pub min: [f32; 3],
 11:     pub max: [f32; 3],
 12: }
 13: 
 14: impl Aabb {
 15:     pub fn new(min: [f32; 3], max: [f32; 3]) -> Self {
 16:         Self { min, max }
 17:     }
 18: 
 19:     pub fn intersects(&self, other: &Aabb) -> bool {
 20:         self.max[0] > other.min[0] && self.min[0] < other.max[0]
 21:             && self.max[1] > other.min[1] && self.min[1] < other.max[1]
 22:             && self.max[2] > other.min[2] && self.min[2] < other.max[2]
 23:     }
 24: }
 25: 
 26: /// Player capsule approximated as an AABB, matching the original client:
 27: /// radius 0.35 around the eye, extending 1.65 below and 0.1 above eye level.
 28: pub const PLAYER_RADIUS: f32 = 0.35;
 29: pub const PLAYER_EYE_TO_FEET: f32 = 1.65;
 30: pub const PLAYER_EYE_TO_HEAD: f32 = 0.1;
 31: 
 32: /// Builds the player's AABB from an eye-level position.
 33: pub fn player_aabb(eye_pos: [f32; 3]) -> Aabb {
 34:     Aabb::new(
 35:         [
 36:             eye_pos[0] - PLAYER_RADIUS,
 37:             eye_pos[1] - PLAYER_EYE_TO_FEET,
 38:             eye_pos[2] - PLAYER_RADIUS,
 39:         ],
 40:         [
 41:             eye_pos[0] + PLAYER_RADIUS,
 42:             eye_pos[1] + PLAYER_EYE_TO_HEAD,
 43:             eye_pos[2] + PLAYER_RADIUS,
 44:         ],
 45:     )
 46: }
 47: 
 48: /// The set of solid boxes the player can collide with.
 49: /// Rebuilt whenever the chunk set changes.
 50: #[derive(Debug, Default)]
 51: pub struct CollisionWorld {
 52:     boxes: Vec<Aabb>,
 53: }
 54: 
 55: impl CollisionWorld {
 56:     pub fn new() -> Self {
 57:         Self { boxes: Vec::new() }
 58:     }
 59: 
 60:     pub fn rebuild<'a, I: IntoIterator<Item = &'a Aabb>>(&mut self, boxes: I) {
 61:         self.boxes.clear();
 62:         self.boxes.extend(boxes.into_iter().copied());
 63:     }
 64: 
 65:     pub fn len(&self) -> usize {
 66:         self.boxes.len()
 67:     }
 68: 
 69:     pub fn is_empty(&self) -> bool {
 70:         self.boxes.is_empty()
 71:     }
 72: 
 73:     pub fn boxes(&self) -> &[Aabb] {
 74:         &self.boxes
 75:     }
 76: 
 77:     /// True if a player standing at `eye_pos` overlaps any solid box.
 78:     pub fn collides(&self, eye_pos: [f32; 3]) -> bool {
 79:         let p = player_aabb(eye_pos);
 80:         self.boxes.iter().any(|b| p.intersects(b))
 81:     }
 82: }
