 1: //! Application (use-case) layer of the browser client.
 2: //!
 3: //! Everything in this module is pure Rust with no browser dependencies:
 4: //! it can be exercised by native unit tests. Outer layers communicate with
 5: //! it exclusively through the ports declared in [`ports`].
 6: 
 7: pub mod ports;
 8: pub mod collision;
 9: pub mod player;
10: pub mod streaming;
11: pub mod atlas;
12: pub mod engine;

  1: //! Chunk streaming policy and the in-memory chunk store.
  2: //!
  3: //! The world is an infinite plane of square chunks. Each frame the policy
  4: //! computes the set of chunk origins that should be resident around the
  5: //! player; the engine loads missing ones (budgeted, to avoid frame hitches —
  6: //! wasm has no threads, so time-slicing replaces the background meshing
  7: //! thread a native engine would use) and evicts the rest.
  8: 
  9: use std::collections::HashMap;
 10: 
 11: use crate::application::collision::Aabb;
 12: use crate::application::ports::ChunkPayload;
 13: 
 14: /// Integer key for a chunk, quantized from its world origin.
 15: /// Origins are always integer multiples of `chunk_size`, so rounding to
 16: /// millimetres gives a stable, hashable key.
 17: pub type ChunkKey = (i64, i64);
 18: 
 19: pub fn chunk_key(origin_x: f32, origin_z: f32) -> ChunkKey {
 20:     ((origin_x * 1000.0).round() as i64, (origin_z * 1000.0).round() as i64)
 21: }
 22: 
 23: /// Decides which chunks should be resident for a given player position.
 24: #[derive(Debug, Clone, Copy)]
 25: pub struct StreamingPolicy {
 26:     /// World-space side length of a chunk.
 27:     pub chunk_size: f32,
 28:     /// Chebyshev radius in chunks: 1 -> 3x3 resident set, 2 -> 5x5.
 29:     pub radius: i32,
 30: }
 31: 
 32: impl StreamingPolicy {
 33:     /// Returns the desired chunk origins, sorted nearest-first so the load
 34:     /// budget is always spent on the most urgent chunk.
 35:     pub fn desired_origins(&self, player_x: f32, player_z: f32) -> Vec<(f32, f32)> {
 36:         let px = if player_x.is_finite() { player_x } else { 0.0 };
 37:         let pz = if player_z.is_finite() { player_z } else { 0.0 };
 38:         let base_x = (px / self.chunk_size).floor() * self.chunk_size;
 39:         let base_z = (pz / self.chunk_size).floor() * self.chunk_size;
 40: 
 41:         let mut origins = Vec::with_capacity(((2 * self.radius + 1).pow(2)) as usize);
 42:         for dz in -self.radius..=self.radius {
 43:             for dx in -self.radius..=self.radius {
 44:                 origins.push((
 45:                     base_x + dx as f32 * self.chunk_size,
 46:                     base_z + dz as f32 * self.chunk_size,
 47:                 ));
 48:             }
 49:         }
 50:         origins.sort_by(|a, b| {
 51:             let da = (a.0 + self.chunk_size * 0.5 - px).powi(2) + (a.1 + self.chunk_size * 0.5 - pz).powi(2);
 52:             let db = (b.0 + self.chunk_size * 0.5 - px).powi(2) + (b.1 + self.chunk_size * 0.5 - pz).powi(2);
 53:             da.total_cmp(&db)
 54:         });
 55:         origins
 56:     }
 57: }
 58: 
 59: /// A resident chunk: payload plus its world origin.
 60: #[derive(Debug, Clone)]
 61: pub struct LoadedChunk {
 62:     pub origin: (f32, f32),
 63:     pub payload: ChunkPayload,
 64: }
 65: 
 66: /// Keyed store of resident chunks. Iteration order is the insertion order of
 67: /// keys (tracked separately) so atlas offsets stay deterministic.
 68: #[derive(Debug, Default)]
 69: pub struct ChunkStore {
 70:     chunks: HashMap<ChunkKey, LoadedChunk>,
 71:     order: Vec<ChunkKey>,
 72: }
 73: 
 74: impl ChunkStore {
 75:     pub fn new() -> Self {
 76:         Self { chunks: HashMap::new(), order: Vec::new() }
 77:     }
 78: 
 79:     pub fn len(&self) -> usize {
 80:         self.order.len()
 81:     }
 82: 
 83:     pub fn is_empty(&self) -> bool {
 84:         self.order.is_empty()
 85:     }
 86: 
 87:     pub fn contains(&self, key: ChunkKey) -> bool {
 88:         self.chunks.contains_key(&key)
 89:     }
 90: 
 91:     pub fn insert(&mut self, key: ChunkKey, chunk: LoadedChunk) {
 92:         if self.chunks.insert(key, chunk).is_none() {
 93:             self.order.push(key);
 94:         }
 95:     }
 96: 
 97:     /// Removes every chunk whose key is not in `keep`, returning whether
 98:     /// anything changed.
 99:     pub fn retain_keys(&mut self, keep: &[ChunkKey]) -> bool {
100:         let before = self.order.len();
101:         self.order.retain(|k| keep.contains(k));
102:         self.chunks.retain(|k, _| keep.contains(k));
103:         before != self.order.len()
104:     }
105: 
106:     /// Chunks in deterministic (insertion) order.
107:     pub fn iter_ordered(&self) -> impl Iterator<Item = &LoadedChunk> {
108:         self.order.iter().filter_map(|k| self.chunks.get(k))
109:     }
110: 
111:     /// All collision boxes of all resident chunks.
112:     pub fn all_collision_boxes(&self) -> impl Iterator<Item = &Aabb> {
113:         self.iter_ordered().flat_map(|c| c.payload.collision.iter())
114:     }
115: }
116: 
117: #[cfg(test)]
118: mod tests {
119:     use super::*;
120: 
121:     #[test]
122:     fn desired_origins_covers_square_around_player() {
123:         let policy = StreamingPolicy { chunk_size: 10.0, radius: 1 };
124:         let origins = policy.desired_origins(5.0, 5.0);
125:         assert_eq!(origins.len(), 9);
126:         // Nearest-first: the chunk containing the player comes first.
127:         assert_eq!(origins[0], (0.0, 0.0));
128:         assert!(origins.contains(&(-10.0, -10.0)));
129:         assert!(origins.contains(&(10.0, 10.0)));
130:     }
131: 
132:     #[test]
133:     fn desired_origins_handles_negative_coordinates() {
134:         let policy = StreamingPolicy { chunk_size: 10.0, radius: 1 };
135:         let origins = policy.desired_origins(-0.1, -0.1);
136:         assert_eq!(origins[0], (-10.0, -10.0));
137:     }
138: 
139:     #[test]
140:     fn store_eviction_reports_change() {
141:         let mut store = ChunkStore::new();
142:         let payload = ChunkPayload { root: 0, nodes: vec![], world_size: 10.0, collision: vec![] };
143:         store.insert(chunk_key(0.0, 0.0), LoadedChunk { origin: (0.0, 0.0), payload: payload.clone() });
144:         store.insert(chunk_key(10.0, 0.0), LoadedChunk { origin: (10.0, 0.0), payload });
145:         assert_eq!(store.len(), 2);
146:         assert!(store.retain_keys(&[chunk_key(0.0, 0.0)]));
147:         assert_eq!(store.len(), 1);
148:         assert!(!store.retain_keys(&[chunk_key(0.0, 0.0)]));
149:     }
150: }

