 1: //! Canvas-2D blit driver for the CPU splatting renderer.
 2: //!
 3: //! All rendering logic lives in the platform-free
 4: //! `adapters::cpu_splatter::SoftwareRasterizer`; this wrapper's only job is
 5: //! to copy the finished RGBA framebuffer into the canvas via `ImageData` —
 6: //! no WebGL context is created at all.
 7: 
 8: use wasm_bindgen::{Clamped, JsCast, JsValue};
 9: use web_sys::{CanvasRenderingContext2d, HtmlCanvasElement, ImageData};
10: 
11: use crate::adapters::cpu_splatter::SoftwareRasterizer;
12: use crate::application::ports::{ChunkDraw, FrameParams, RendererPort};
13: 
14: pub struct CpuCanvasRenderer {
15:     rasterizer: SoftwareRasterizer,
16:     ctx: CanvasRenderingContext2d,
17: }
18: 
19: impl CpuCanvasRenderer {
20:     pub fn new(canvas: &HtmlCanvasElement) -> Result<Self, JsValue> {
21:         let ctx = canvas
22:             .get_context("2d")?
23:             .ok_or_else(|| JsValue::from_str("no 2d context available"))?
24:             .dyn_into::<CanvasRenderingContext2d>()?;
25:         Ok(Self {
26:             rasterizer: SoftwareRasterizer::new(canvas.width() as usize, canvas.height() as usize),
27:             ctx,
28:         })
29:     }
30: 
31:     pub fn resize(&mut self, width: u32, height: u32) {
32:         self.rasterizer.resize(width as usize, height as usize);
33:     }
34: }
35: 
36: impl RendererPort for CpuCanvasRenderer {
37:     fn upload_atlas(&mut self, texels: &[u32]) {
38:         self.rasterizer.upload_atlas(texels);
39:     }
40: 
41:     fn draw(&mut self, frame: &FrameParams, chunks: &[ChunkDraw]) {
42:         self.rasterizer.draw(frame, chunks);
43:         let width = self.rasterizer.width() as u32;
44:         if let Ok(image) = ImageData::new_with_u8_clamped_array_and_sh(
45:             Clamped(self.rasterizer.framebuffer()),
46:             width,
47:             self.rasterizer.height() as u32,
48:         ) {
49:             let _ = self.ctx.put_image_data(&image, 0.0, 0.0);
50:         }
51:     }
52: }

