 20: #[derive(Debug, Clone, Copy)]
 21: #[allow(dead_code)] // `t`/`voxel_type` exist for the Debug dump on failure
 22: struct Hit {
 23:     chunk: usize,
 24:     t: f32,
 25:     /// Leaf box in chunk-local space.
 26:     box_min: [f32; 3],
 27:     box_max: [f32; 3],
 28:     voxel_type: u32,
 29: }
