 31: /// 1:1 Rust port of the GLSL `raymarchSVO` (same constants, same epsilons).
 32: fn raymarch_svo(
 33:     atlas: &[u32],
 34:     ro: [f32; 3],
 35:     rd: [f32; 3],
 36:     chunk_root_idx: usize,
 37:     t_entry: f32,
 38:     world_size: f32,
 39: ) -> Option<(f32, [f32; 3], [f32; 3], u32)> {
 40:     let mut t = t_entry;
 41:     let mut p = [ro[0] + t * rd[0], ro[1] + t * rd[1], ro[2] + t * rd[2]];
 42: 
 43:     let mut stack: Vec<(usize, [f32; 3], [f32; 3])> = Vec::new();
 44:     let mut current_node = chunk_root_idx;
 45:     let mut cmin = [0.0f32; 3];
 46:     let mut cmax = [world_size; 3];
 47: 
 48:     for _ in 0..160 {
 49:         let tx = current_node * 4;
 50:         let (is_leaf, a, b) = (atlas[tx] == 1, atlas[tx + 1], atlas[tx + 2]);
 51: 
 52:         if is_leaf {
 53:             if a != 0 {
 54:                 return Some((t, cmin, cmax, a));
 55:             }
 56:             // Empty-space skip to this leaf's exit plane.
 57:             let exit = |lo: f32, hi: f32, o: f32, d: f32| (if d > 0.0 { hi } else { lo } - o) / d;
 58:             let tx = exit(cmin[0], cmax[0], ro[0], rd[0]);
 59:             let ty = exit(cmin[1], cmax[1], ro[1], rd[1]);
 60:             let tz = exit(cmin[2], cmax[2], ro[2], rd[2]);
 61:             let t_exit = tx.min(ty).min(tz);
 62:             t = t_exit;
 63:             p = [ro[0] + t * rd[0], ro[1] + t * rd[1], ro[2] + t * rd[2]];
 64:             // Snap every tied axis past its exit plane (a ray exactly
 65:             // through a corner advances diagonally; leaving an axis ON its
 66:             // plane stalls the march instead).
 67:             if (t_exit - tx).abs() < 1e-4 { p[0] = (if rd[0] > 0.0 { cmax[0] } else { cmin[0] }) + (if rd[0] > 0.0 { 0.001 } else { -0.001 }); }
 68:             if (t_exit - ty).abs() < 1e-4 { p[1] = (if rd[1] > 0.0 { cmax[1] } else { cmin[1] }) + (if rd[1] > 0.0 { 0.001 } else { -0.001 }); }
 69:             if (t_exit - tz).abs() < 1e-4 { p[2] = (if rd[2] > 0.0 { cmax[2] } else { cmin[2] }) + (if rd[2] > 0.0 { 0.001 } else { -0.001 }); }
 70:             // Multi-level pop, mirroring the shader: the skip may cross
 71:             // boundaries shared by several ancestor boxes at once.
 72:             while outside(p, cmin, cmax) {
 73:                 let Some(f) = stack.pop() else { return None };
 74:                 current_node = f.0;
 75:                 cmin = f.1;
 76:                 cmax = f.2;
 77:             }
 78:         } else {
 79:             let center = [
 80:                 (cmin[0] + cmax[0]) * 0.5,
 81:                 (cmin[1] + cmax[1]) * 0.5,
 82:                 (cmin[2] + cmax[2]) * 0.5,
 83:             ];
 84:             let ox = (p[0] >= center[0]) as usize;
 85:             let oy = (p[1] >= center[1]) as usize;
 86:             let oz = (p[2] >= center[2]) as usize;
 87:             let child_idx = (oz << 2) | (oy << 1) | ox;
 88: 
 89:             if b & (1 << child_idx) != 0 {
 90:                 if stack.len() < 8 {
 91:                     stack.push((current_node, cmin, cmax));
 92:                 }
 93:                 if ox == 1 { cmin[0] = center[0] } else { cmax[0] = center[0] }
 94:                 if oy == 1 { cmin[1] = center[1] } else { cmax[1] = center[1] }
 95:                 if oz == 1 { cmin[2] = center[2] } else { cmax[2] = center[2] }
 96:                 current_node = a as usize + child_idx;
 97:             } else {
 98:                 let omin = [
 99:                     if ox == 1 { center[0] } else { cmin[0] },
100:                     if oy == 1 { center[1] } else { cmin[1] },
101:                     if oz == 1 { center[2] } else { cmin[2] },
102:                 ];
103:                 let omax = [
104:                     if ox == 1 { cmax[0] } else { center[0] },
105:                     if oy == 1 { cmax[1] } else { center[1] },
106:                     if oz == 1 { cmax[2] } else { center[2] },
107:                 ];
108:                 let exit =
109:                     |lo: f32, hi: f32, o: f32, d: f32| (if d > 0.0 { hi } else { lo } - o) / d;
110:                 let tx = exit(omin[0], omax[0], ro[0], rd[0]);
111:                 let ty = exit(omin[1], omax[1], ro[1], rd[1]);
112:                 let tz = exit(omin[2], omax[2], ro[2], rd[2]);
113:                 let t_exit = tx.min(ty).min(tz);
114:                 t = t_exit;
115:                 p = [ro[0] + t * rd[0], ro[1] + t * rd[1], ro[2] + t * rd[2]];
116:                 if (t_exit - tx).abs() < 1e-4 { p[0] = (if rd[0] > 0.0 { omax[0] } else { omin[0] }) + (if rd[0] > 0.0 { 0.001 } else { -0.001 }); }
117:                 if (t_exit - ty).abs() < 1e-4 { p[1] = (if rd[1] > 0.0 { omax[1] } else { omin[1] }) + (if rd[1] > 0.0 { 0.001 } else { -0.001 }); }
118:                 if (t_exit - tz).abs() < 1e-4 { p[2] = (if rd[2] > 0.0 { omax[2] } else { omin[2] }) + (if rd[2] > 0.0 { 0.001 } else { -0.001 }); }
119:                 while outside(p, cmin, cmax) {
120:                     let Some(f) = stack.pop() else { return None };
121:                     current_node = f.0;
122:                     cmin = f.1;
123:                     cmax = f.2;
124:                 }
125:             }
126:         }
127:     }
128:     None
129: }
130: 
131: fn outside(p: [f32; 3], min: [f32; 3], max: [f32; 3]) -> bool {
132:     p[0] < min[0] || p[0] > max[0] || p[1] < min[1] || p[1] > max[1] || p[2] < min[2]
133:         || p[2] > max[2]
134: }
135: 
136: /// Mirrors the shader's `main()`: slab-test all chunks, sort by entry, march
137: /// nearest first, return the first hit.
138: fn march_scene(
139:     atlas: &[u32],
140:     draws: &[wasm_frontend::application::ports::ChunkDraw],
141:     ro: [f32; 3],
142:     rd: [f32; 3],
143: ) -> Option<Hit> {
144:     let safe = |v: f32| if v.abs() < 1e-4 { 1e-4f32.copysign(v) } else { v };
145:     // The shader passes safe_rd (not raw rd) into raymarchSVO too.
146:     let rd = [safe(rd[0]), safe(rd[1]), safe(rd[2])];
147:     let inv = [1.0 / rd[0], 1.0 / rd[1], 1.0 / rd[2]];
148: 
149:     let mut hits: Vec<(usize, f32)> = Vec::new();
150:     for (i, d) in draws.iter().enumerate() {
151:         let lro = [ro[0] - d.origin[0], ro[1] - d.origin[1], ro[2] - d.origin[2]];
152:         let mut t_entry = f32::MIN;
153:         let mut t_exit = f32::MAX;
154:         for a in 0..3 {
155:             let t1 = (0.0 - lro[a]) * inv[a];
156:             let t2 = (d.world_size - lro[a]) * inv[a];
157:             t_entry = t_entry.max(t1.min(t2));
158:             t_exit = t_exit.min(t1.max(t2));
159:         }
160:         if t_entry < t_exit && t_exit > 0.0 {
161:             hits.push((i, t_entry.max(0.0)));
162:         }
163:     }
164:     hits.sort_by(|a, b| a.1.total_cmp(&b.1));
165: 
166:     for (i, t_min) in hits {
167:         let d = &draws[i];
168:         let lro = [ro[0] - d.origin[0], ro[1] - d.origin[1], ro[2] - d.origin[2]];
169:         if let Some((t, bmin, bmax, vt)) =
170:             raymarch_svo(atlas, lro, rd, d.root_index as usize, t_min, d.world_size)
171:         {
172:             return Some(Hit { chunk: i, t, box_min: bmin, box_max: bmax, voxel_type: vt });
173:         }
174:     }
175:     None
176: }
177: 
178: /// Every hit the reference ray-marcher reports must be a genuinely solid
179: /// region of the source octree — otherwise the renderer shows phantom boxes.
180: #[test]
181: fn multi_chunk_raymarch_reports_no_phantom_geometry() {
182:     let seed = 42;
183:     let config = GeneratorConfig::low_spec();
184:     let noise = SimpleNoiseProvider::new();
185:     let source = LocalChunkSource::new(SimpleNoiseProvider::new(), seed, config);
186: 
187:     // 3x3 resident set around spawn, same as the engine with radius 1.
188:     let mut chunks = Vec::new();
189:     for dz in -1..=1 {
190:         for dx in -1..=1 {
191:             let (ox, oz) = (dx as f32 * 10.0, dz as f32 * 10.0);
192:             chunks.push(LoadedChunk { origin: (ox, oz), payload: source.load(ox, oz, 0) });
193:         }
194:     }
195:     let build = build_atlas(chunks.iter());
196: 
197:     // Ground truth: rebuild each chunk's SVO exactly like LocalChunkSource.
198:     let svos: Vec<_> = chunks
199:         .iter()
200:         .map(|c| {
201:             let generator = GenerateChunkArchitectureUseCase::new(&noise);
202:             let grid = generator.execute(
203:                 Position::new(c.origin.0, c.origin.1),
204:                 seed,
205:                 config,
206:             );
207:             BuildOctreeUseCase::new().execute(&grid, config.svo_depth(), config.svo_world_size())
208:         })
209:         .collect();
210: 
211:     let ro = [5.0f32, 1.7, 5.0]; // spawn eye position
212:     let mut phantoms = Vec::new();
213:     let mut hit_count = 0usize;
214: 
215:     // Dense direction sweep: 64 yaw steps x 17 pitch steps.
216:     for yi in 0..64 {
217:         for pi in -8..=8i32 {
218:             let yaw = yi as f32 / 64.0 * std::f32::consts::TAU;
219:             let pitch = pi as f32 / 8.0 * 1.2;
220:             let (sy, cy) = yaw.sin_cos();
221:             let (sp, cp) = pitch.sin_cos();
222:             let rd = [-cp * sy, sp, -cp * cy];
223: 
224:             let Some(hit) = march_scene(&build.texels, &build.draws, ro, rd) else { continue };
225:             hit_count += 1;
226: 
227:             // The leaf box center, in voxel coordinates of the owning chunk.
228:             let scale = config.voxel_scale;
229:             let c = [
230:                 (hit.box_min[0] + hit.box_max[0]) * 0.5,
231:                 (hit.box_min[1] + hit.box_max[1]) * 0.5,
232:                 (hit.box_min[2] + hit.box_max[2]) * 0.5,
233:             ];
234:             let (vx, vy, vz) =
235:                 ((c[0] / scale) as u32, (c[1] / scale) as u32, (c[2] / scale) as u32);
236:             let truth = svos[hit.chunk].get(vx, vy, vz);
237:             let solid = truth.map(|(vt, _, _)| vt != 0).unwrap_or(false);
238:             if !solid {
239:                 phantoms.push((yaw, pitch, hit));
240:             }
241:         }
242:     }
243: 
244:     assert!(hit_count > 200, "sanity: the sweep must actually hit walls, got {hit_count}");
245:     assert!(
246:         phantoms.is_empty(),
247:         "{} phantom hits out of {}; first 5: {:#?}",
248:         phantoms.len(),
249:         hit_count,
250:         &phantoms[..phantoms.len().min(5)]
251:     );
252: }
253: 
254: /// The world is a closed slab (floor everywhere at y=0, ceiling at the top),
255: /// so every ray with meaningful up/down pitch MUST hit something. A miss is
256: /// a traversal crack — the "black bars in walls" artifact caused by popping
257: /// only one stack level when a skip crosses several octree levels at once.
258: #[test]
259: fn pitched_rays_never_escape_through_cracks() {
260:     let seed = 42;
261:     let config = GeneratorConfig::low_spec();
262:     let source = LocalChunkSource::new(SimpleNoiseProvider::new(), seed, config);
263: 
264:     let mut chunks = Vec::new();
265:     for dz in -1..=1 {
266:         for dx in -1..=1 {
267:             let (ox, oz) = (dx as f32 * 10.0, dz as f32 * 10.0);
268:             chunks.push(LoadedChunk { origin: (ox, oz), payload: source.load(ox, oz, 0) });
269:         }
270:     }
271:     let build = build_atlas(chunks.iter());
272: 
273:     let mut misses = 0usize;
274:     let mut total = 0usize;
275:     for px in 0..8 {
276:         for pz in 0..8 {
277:             let ro = [1.0137 + px as f32 * 1.11, 1.7, 0.9713 + pz as f32 * 1.19];
278:             for yi in 0..128 {
279:                 for pi in [-40i32, -25, 25, 40] {
280:                     let yaw = (yi as f32 + 0.173) / 128.0 * std::f32::consts::TAU;
281:                     let pitch = pi as f32 / 60.0 * 1.2;
282:                     let (sy, cy) = yaw.sin_cos();
283:                     let (sp, cp) = pitch.sin_cos();
284:                     let rd = [-cp * sy, sp, -cp * cy];
285:                     total += 1;
286:                     if march_scene(&build.texels, &build.draws, ro, rd).is_none() {
287:                         misses += 1;
288:                     }
289:                 }
290:             }
291:         }
292:     }
293:     assert_eq!(misses, 0, "{misses} of {total} pitched rays escaped through cracks");
294: }

