 18: #[wasm_bindgen]
 19: impl CPURaycaster {
 20:     #[wasm_bindgen(constructor)]
 21:     pub fn new(screen_width: usize, screen_height: usize) -> Self {
 22:         Self {
 23:             grid_data: Vec::new(),
 24:             light_data: Vec::new(),
 25:             width: 0,
 26:             height: 0,
 27:             depth: 0,
 28:             frame_buffer: vec![255; screen_width * screen_height * 4],
 29:             screen_width,
 30:             screen_height,
 31:         }
 32:     }
 33: 
 34:     pub fn set_grid(&mut self, width: usize, height: usize, depth: usize, data: &[u8], light: &[u8]) {
 35:         self.width = width;
 36:         self.height = height;
 37:         self.depth = depth;
 38:         self.grid_data = data.to_vec();
 39:         self.light_data = light.to_vec();
 40:     }
 41:     
 42:     pub fn get_frame_buffer(&self) -> *const u8 {
 43:         self.frame_buffer.as_ptr()
 44:     }
 45: 
 46:     fn get_voxel(&self, x: isize, y: isize, z: isize) -> u8 {
 47:         if x < 0 || y < 0 || z < 0 || x >= self.width as isize || y >= self.height as isize || z >= self.depth as isize {
 48:             return VOXEL_AIR;
 49:         }
 50:         self.grid_data[(y as usize * self.width * self.depth) + (z as usize * self.width) + (x as usize)]
 51:     }
 52: 
 53:     fn get_light(&self, x: isize, y: isize, z: isize) -> u8 {
 54:         if x < 0 || y < 0 || z < 0 || x >= self.width as isize || y >= self.height as isize || z >= self.depth as isize {
 55:             return 0;
 56:         }
 57:         self.light_data[(y as usize * self.width * self.depth) + (z as usize * self.width) + (x as usize)]
 58:     }
 59: 
 60:     pub fn render(&mut self, px: f32, py: f32, pz: f32, yaw: f32, pitch: f32, fov_deg: f32) {
 61:         // Clear background to dark fog
 62:         for i in (0..self.frame_buffer.len()).step_by(4) {
 63:             self.frame_buffer[i] = 10;     // R
 64:             self.frame_buffer[i + 1] = 10; // G
 65:             self.frame_buffer[i + 2] = 10; // B
 66:             self.frame_buffer[i + 3] = 255; // A
 67:         }
 68: 
 69:         if self.width == 0 {
 70:             return;
 71:         }
 72: 
 73:         let fov_rad = fov_deg * std::f32::consts::PI / 180.0;
 74:         let half_fov = fov_rad / 2.0;
 75: 
 76:         let dir_x = -yaw.sin();
 77:         let dir_z = -yaw.cos();
 78:         let plane_x = yaw.cos() * half_fov.tan();
 79:         let plane_z = -yaw.sin() * half_fov.tan();
 80: 
 81:         for x in 0..self.screen_width {
 82:             let camera_x = 2.0 * (x as f32) / (self.screen_width as f32) - 1.0;
 83:             let ray_dir_x = dir_x + plane_x * camera_x;
 84:             let ray_dir_z = dir_z + plane_z * camera_x;
 85:             
 86:             let mut map_x = px.floor() as isize;
 87:             let mut map_z = pz.floor() as isize;
 88:             
 89:             let delta_dist_x = if ray_dir_x == 0.0 { f32::INFINITY } else { (1.0 / ray_dir_x).abs() };
 90:             let delta_dist_z = if ray_dir_z == 0.0 { f32::INFINITY } else { (1.0 / ray_dir_z).abs() };
 91:             
 92:             let mut side_dist_x;
 93:             let mut side_dist_z;
 94:             let step_x: isize;
 95:             let step_z: isize;
 96:             
 97:             if ray_dir_x < 0.0 {
 98:                 step_x = -1;
 99:                 side_dist_x = (px - map_x as f32) * delta_dist_x;
100:             } else {
101:                 step_x = 1;
102:                 side_dist_x = (map_x as f32 + 1.0 - px) * delta_dist_x;
103:             }
104:             
105:             if ray_dir_z < 0.0 {
106:                 step_z = -1;
107:                 side_dist_z = (pz - map_z as f32) * delta_dist_z;
108:             } else {
109:                 step_z = 1;
110:                 side_dist_z = (map_z as f32 + 1.0 - pz) * delta_dist_z;
111:             }
112:             
113:             let mut hit = 0;
114:             let mut side = 0;
115:             let mut perp_wall_dist = 0.0;
116:             let mut hit_y = 0;
117:             
118:             let map_y = py.floor() as isize;
119:             let max_steps = 200;
120:             let mut steps = 0;
121: 
122:             while hit == 0 && steps < max_steps {
123:                 if side_dist_x < side_dist_z {
124:                     side_dist_x += delta_dist_x;
125:                     map_x += step_x;
126:                     side = 0;
127:                 } else {
128:                     side_dist_z += delta_dist_z;
129:                     map_z += step_z;
130:                     side = 1;
131:                 }
132:                 
133:                 let v = self.get_voxel(map_x, map_y, map_z);
134:                 if v != VOXEL_AIR {
135:                     hit = v;
136:                     hit_y = map_y;
137:                 }
138:                 steps += 1;
139:             }
140:             
141:             if hit > 0 {
142:                 if side == 0 {
143:                     perp_wall_dist = side_dist_x - delta_dist_x;
144:                 } else {
145:                     perp_wall_dist = side_dist_z - delta_dist_z;
146:                 }
147:                 
148:                 let line_height = (self.screen_height as f32 / perp_wall_dist).abs() as isize;
149:                 let pitch_offset = (pitch * self.screen_height as f32) as isize;
150:                 
151:                 let mut draw_start = -line_height / 2 + self.screen_height as isize / 2 + pitch_offset;
152:                 let draw_start_clamped = if draw_start < 0 { 0 } else { draw_start as usize };
153:                 let mut draw_end = line_height / 2 + self.screen_height as isize / 2 + pitch_offset;
154:                 if draw_end >= self.screen_height as isize {
155:                     draw_end = self.screen_height as isize - 1;
156:                 }
157:                 let draw_end_clamped = draw_end as usize;
158:                 
159:                 let mut r = 200;
160:                 let mut g = 200;
161:                 let mut b = 200;
162:                 
163:                 if hit == VOXEL_LIGHT {
164:                     r = 255; g = 255; b = 200;
165:                 } else if hit == 5 {
166:                     r = 150; g = 30; b = 30;
167:                 } else if hit == 1 {
168:                     r = 180; g = 160; b = 100;
169:                 }
170:                 
171:                 let light = self.get_light(map_x, hit_y, map_z);
172:                 let light_factor = if hit == VOXEL_LIGHT { 1.0 } else { light as f32 / 15.0 };
173:                 let fog_factor = (-perp_wall_dist * 0.05).exp();
174:                 
175:                 r = (r as f32 * light_factor * fog_factor) as u8;
176:                 g = (g as f32 * light_factor * fog_factor) as u8;
177:                 b = (b as f32 * light_factor * fog_factor) as u8;
178:                 
179:                 if side == 1 && hit != VOXEL_LIGHT {
180:                     r = (r as f32 * 0.7) as u8;
181:                     g = (g as f32 * 0.7) as u8;
182:                     b = (b as f32 * 0.7) as u8;
183:                 }
184:                 
185:                 for y in draw_start_clamped..=draw_end_clamped {
186:                     let pixel_idx = (y * self.screen_width + x) * 4;
187:                     self.frame_buffer[pixel_idx] = r;
188:                     self.frame_buffer[pixel_idx + 1] = g;
189:                     self.frame_buffer[pixel_idx + 2] = b;
190:                     self.frame_buffer[pixel_idx + 3] = 255;
191:                 }
192:                 
193:                 let floor_fog = (-perp_wall_dist * 0.01).exp(); // less fog on floor to see shape
194:                 for y in (draw_end_clamped + 1)..self.screen_height {
195:                     let pixel_idx = (y * self.screen_width + x) * 4;
196:                     self.frame_buffer[pixel_idx] = (40.0 * floor_fog) as u8;
197:                     self.frame_buffer[pixel_idx + 1] = (40.0 * floor_fog) as u8;
198:                     self.frame_buffer[pixel_idx + 2] = (40.0 * floor_fog) as u8;
199:                     self.frame_buffer[pixel_idx + 3] = 255;
200:                 }
201:                 
202:                 for y in 0..draw_start_clamped {
203:                     let pixel_idx = (y * self.screen_width + x) * 4;
204:                     self.frame_buffer[pixel_idx] = (60.0 * floor_fog) as u8;
205:                     self.frame_buffer[pixel_idx + 1] = (55.0 * floor_fog) as u8;
206:                     self.frame_buffer[pixel_idx + 2] = (50.0 * floor_fog) as u8;
207:                     self.frame_buffer[pixel_idx + 3] = 255;
