 1: /// Represents a dense 3D grid of voxels.
 2: /// This is the foundation for our "smaller voxels" requirement.
 3: pub struct VoxelGrid {
 4:     width: usize,
 5:     height: usize,
 6:     depth: usize,
 7:     data: Vec<u8>,
 8:     light_data: Vec<u8>,
 9: }
10: 
11: pub const VOXEL_AIR: u8 = 0;
12: pub const VOXEL_WALL: u8 = 1;
13: pub const VOXEL_FLOOR: u8 = 2;
14: pub const VOXEL_CEILING: u8 = 3;
15: pub const VOXEL_LIGHT: u8 = 4;
16: pub const VOXEL_RED_WALL: u8 = 5;
17: /// Walkable ground cover (grassland level). Visual-only, like FLOOR.
18: pub const VOXEL_GRASS: u8 = 6;
19: /// Walkable shallow water (grassland lakes). Visual-only, like FLOOR.
20: pub const VOXEL_WATER: u8 = 7;
21: /// Tree trunk (grassland). Solid: blocks the player like WALL.
22: pub const VOXEL_TREE: u8 = 8;
23: 
24: impl VoxelGrid {
25:     pub fn new(width: usize, height: usize, depth: usize) -> Self {
26:         let size = width * height * depth;
27:         Self {
28:             width,
29:             height,
30:             depth,
31:             data: vec![VOXEL_AIR; size],
32:             light_data: vec![0; size],
33:         }
34:     }
35: 
36:     pub fn width(&self) -> usize { self.width }
37:     pub fn height(&self) -> usize { self.height }
38:     pub fn depth(&self) -> usize { self.depth }
39: 
40:     fn index(&self, x: usize, y: usize, z: usize) -> Option<usize> {
41:         if x < self.width && y < self.height && z < self.depth {
42:             Some(y * (self.width * self.depth) + z * self.width + x)
43:         } else {
44:             None
45:         }
46:     }
47: 
48:     pub fn set(&mut self, x: usize, y: usize, z: usize, voxel_type: u8) {
49:         if let Some(idx) = self.index(x, y, z) {
50:             self.data[idx] = voxel_type;
51:         }
52:     }
53: 
54:     pub fn get(&self, x: usize, y: usize, z: usize) -> u8 {
55:         if let Some(idx) = self.index(x, y, z) {
56:             self.data[idx]
57:         } else {
58:             VOXEL_AIR
59:         }
60:     }
61: 
62:     pub fn set_light(&mut self, x: usize, y: usize, z: usize, level: u8) {
63:         if let Some(idx) = self.index(x, y, z) {
64:             self.light_data[idx] = level;
65:         }
66:     }
67: 
68:     pub fn get_light(&self, x: usize, y: usize, z: usize) -> u8 {
69:         if let Some(idx) = self.index(x, y, z) {
70:             self.light_data[idx]
71:         } else {
72:             0
73:         }
74:     }
75: }

