  1: use crate::domain::entities::voxel_grid::{
  2:     VoxelGrid, VOXEL_AIR, VOXEL_WALL, VOXEL_FLOOR, VOXEL_CEILING, VOXEL_LIGHT, VOXEL_RED_WALL,
  3:     VOXEL_GRASS, VOXEL_WATER, VOXEL_TREE,
  4: };
  5: use crate::domain::entities::sparse_voxel_octree::{SparseVoxelOctree, SvoNode};
  6: 
  7: /// Use Case to convert a dense VoxelGrid into a collapsed Sparse Voxel Octree.
  8: pub struct BuildOctreeUseCase;
  9: 
 10: impl BuildOctreeUseCase {
 11:     pub fn new() -> Self {
 12:         Self
 13:     }
 14: 
 15:     /// Converts a dense VoxelGrid into an SVO of the specified depth.
 16:     pub fn execute(&self, grid: &VoxelGrid, depth: u32, world_size: f32) -> SparseVoxelOctree {
 17:         let mut nodes = Vec::new();
 18:         let size = 1 << depth;
 19:         
 20:         // Recursive build from root
 21:         let root_node = self.build_recursive(grid, &mut nodes, 0, 0, 0, size, depth);
 22:         
 23:         // Push the root node to the end of the nodes array
 24:         let root_idx = nodes.len();
 25:         nodes.push(root_node);
 26:         
 27:         SparseVoxelOctree {
 28:             root: root_idx,
 29:             nodes,
 30:             depth,
 31:             world_size,
 32:         }
 33:     }
 34: 
 35:     fn build_recursive(
 36:         &self,
 37:         grid: &VoxelGrid,
 38:         nodes: &mut Vec<SvoNode>,
 39:         x: u32,
 40:         y: u32,
 41:         z: u32,
 42:         size: u32,
 43:         depth: u32,
 44:     ) -> SvoNode {
 45:         if depth == 0 {
 46:             let (v_type, color, ll) = self.get_voxel_attrs(grid, x, y, z);
 47:             return SvoNode::Leaf {
 48:                 voxel_type: v_type,
 49:                 color,
 50:                 light_level: ll,
 51:             };
 52:         }
 53: 
 54:         let child_size = size / 2;
 55:         let mut children = [SvoNode::Leaf { voxel_type: 0, color: 0, light_level: 0 }; 8];
 56: 
 57:         for octant_idx in 0..8 {
 58:             let dx = (octant_idx & 1) * child_size;
 59:             let dy = ((octant_idx >> 1) & 1) * child_size;
 60:             let dz = ((octant_idx >> 2) & 1) * child_size;
 61: 
 62:             children[octant_idx as usize] = self.build_recursive(
 63:                 grid,
 64:                 nodes,
 65:                 x + dx,
 66:                 y + dy,
 67:                 z + dz,
 68:                 child_size,
 69:                 depth - 1,
 70:             );
 71:         }
 72: 
 73:         // Check if all 8 children are uniform leaves
 74:         let mut uniform = true;
 75:         let mut first_val = None;
 76:         for child in &children {
 77:             match child {
 78:                 SvoNode::Internal { .. } => {
 79:                     uniform = false;
 80:                     break;
 81:                 }
 82:                 SvoNode::Leaf { voxel_type, color, light_level } => {
 83:                     if let Some((vt, col, ll)) = first_val {
 84:                         if vt != *voxel_type || col != *color || ll != *light_level {
 85:                             uniform = false;
 86:                             break;
 87:                         }
 88:                     } else {
 89:                         first_val = Some((*voxel_type, *color, *light_level));
 90:                     }
 91:                 }
 92:             }
 93:         }
 94: 
 95:         if uniform {
 96:             if let Some((vt, col, ll)) = first_val {
 97:                 return SvoNode::Leaf {
 98:                     voxel_type: vt,
 99:                     color: col,
100:                     light_level: ll,
101:                 };
102:             }
103:         }
104: 
105:         // Push 8 children contiguously to arena
106:         let child_base_index = nodes.len() as u32;
107:         let mut child_mask = 0;
108: 
109:         for octant_idx in 0..8 {
110:             let child = children[octant_idx as usize];
111:             match child {
112:                 SvoNode::Leaf { voxel_type, .. } => {
113:                     if voxel_type != 0 {
114:                         child_mask |= 1 << octant_idx;
115:                     }
116:                 }
117:                 SvoNode::Internal { .. } => {
118:                     child_mask |= 1 << octant_idx;
119:                 }
120:             }
121:             nodes.push(child);
122:         }
123: 
124:         SvoNode::Internal {
125:             child_base_index,
126:             child_mask,
127:         }
128:     }
129: 
130:     fn get_voxel_attrs(&self, grid: &VoxelGrid, x: u32, y: u32, z: u32) -> (u8, u32, u8) {
131:         if x >= grid.width() as u32 || y >= grid.height() as u32 || z >= grid.depth() as u32 {
132:             return (0, 0, 0); // Out of bounds is air
133:         }
134: 
135:         let v_id = grid.get(x as usize, y as usize, z as usize);
136:         if v_id == VOXEL_AIR {
137:             return (0, 0, 0);
138:         }
139: 
140:         let ll = grid.get_light(x as usize, y as usize, z as usize);
141:         let base_color = match v_id {
142:             VOXEL_WALL => 0xddcc66,
143:             VOXEL_FLOOR => 0x998811,
144:             VOXEL_CEILING => 0xcccccc,
145:             VOXEL_LIGHT => 0xffffff,
146:             VOXEL_RED_WALL => 0x880000,
147:             VOXEL_GRASS => 0x4f9a3d,
148:             VOXEL_WATER => 0x3a6fb8,
149:             VOXEL_TREE => 0x6b4a2f,
150:             _ => 0x000000,
151:         };
152: 
153:         (v_id, base_color, ll)
154:     }
155: }
156: 
157: #[cfg(test)]
158: mod tests {
159:     use super::*;
160: 
161:     #[test]
162:     fn test_empty_grid_collapses_to_single_root_leaf() {
163:         let grid = VoxelGrid::new(4, 4, 4);
164:         let builder = BuildOctreeUseCase::new();
165:         let svo = builder.execute(&grid, 2, 4.0);
166:         
167:         // An entirely empty grid should collapse into a single root node (Leaf containing air)
168:         assert_eq!(svo.nodes.len(), 1);
169:         match svo.nodes[svo.root] {
170:             SvoNode::Leaf { voxel_type, .. } => assert_eq!(voxel_type, 0),
171:             _ => panic!("Expected root to be a collapsed leaf node"),
172:         }
173:     }
174: 
175:     #[test]
176:     fn test_single_voxel_splits_octree() {
177:         let mut grid = VoxelGrid::new(4, 4, 4);
178:         grid.set(0, 0, 0, VOXEL_WALL); // Set wall at origin
179:         
180:         let builder = BuildOctreeUseCase::new();
181:         let svo = builder.execute(&grid, 2, 4.0); // depth 2
182:         
183:         // Since there is a single wall voxel, the tree must split and cannot be collapsed completely
184:         assert!(svo.nodes.len() > 1);
185:         
186:         // The root should be an internal node
187:         match svo.nodes[svo.root] {
188:             SvoNode::Internal { child_mask, .. } => {
189:                 assert!(child_mask > 0);
190:             }
191:             _ => panic!("Expected root to be an internal parent node"),
192:         }
193:         
194:         // Let's verify we can query the wall voxel at (0,0,0)
195:         let val = svo.get(0, 0, 0);
196:         assert!(val.is_some());
197:         let (v_type, color, _) = val.unwrap();
198:         assert_eq!(v_type, VOXEL_WALL);
199:         assert_eq!(color, 0xddcc66);
200:     }
201: }

