227: pub struct GenerateChunkArchitectureUseCase<'a> {
228:     noise_provider: &'a dyn NoiseProvider,
229:     telemetry: &'a dyn TelemetryPort,
230: }
231: 
232: impl<'a> GenerateChunkArchitectureUseCase<'a> {
233:     /// Constructs the use case with silent telemetry (tests, wasm default).
234:     pub fn new(noise_provider: &'a dyn NoiseProvider) -> Self {
235:         Self { noise_provider, telemetry: &NULL_TELEMETRY }
236:     }
237: 
238:     /// Constructs the use case with an injected telemetry sink (native server,
239:     /// browser console, ...). Keeps the Dependency Rule intact: the use case
240:     /// only knows the TelemetryPort trait.
241:     pub fn with_telemetry(noise_provider: &'a dyn NoiseProvider, telemetry: &'a dyn TelemetryPort) -> Self {
242:         Self { noise_provider, telemetry }
243:     }
244: 
245:     pub fn execute(&self, chunk_pos: Position, seed: u32, config: GeneratorConfig) -> VoxelGrid {
246:         // Pluggable levels: everything except the legacy office blueprint
247:         // (level 1, kept inline below) goes through the LevelGenerator port.
248:         if config.level == 34 { // Grassland
249:             use crate::use_cases::grassland_level::GrasslandLevel;
250:             use crate::use_cases::level_generator::{LevelGenerator, LEVEL_GRASSLAND};
251: 
252:             let start_micros = self.telemetry.now_micros();
253:             let generator: &dyn LevelGenerator = &GrasslandLevel;
254:             let mut grid = generator.generate(chunk_pos, seed, config, self.noise_provider);
255:             crate::domain::use_cases::calculate_lighting::calculate_voxel_lighting(&mut grid);
256: 
257:             let elapsed_micros = self.telemetry.now_micros().saturating_sub(start_micros);
258:             self.telemetry.log(&format!(
259:                 "[TELEMETRY] level {} chunk generated. Duration={}us, Grid={}x{}x{}",
260:                 config.level, elapsed_micros, grid.width(), grid.height(), grid.depth()
261:             ));
262:             return grid;
263:         }
264: 
265:         let start_micros = self.telemetry.now_micros();
266: 
267:         let width = (config.chunk_size / config.voxel_scale) as usize;
268:         let height = (3.0 / config.voxel_scale) as usize;
269:         let depth = (config.chunk_size / config.voxel_scale) as usize;
270: 
271:         self.telemetry.log(&format!(
272:             "[INFO] Entering GenerateChunkArchitectureUseCase::execute. Args: chunk_pos={:?}, seed={}, chunk_size={} (Voxel dimensions: {}x{}x{})",
273:             chunk_pos, seed, config.chunk_size, width, height, depth
274:         ));
275: 
276:         let mut grid = VoxelGrid::new(width, height, depth);
277: 
278:         // STARTING HUB OVERRIDE: Chunk (0,0) is a massive open plaza that feeds seamlessly into the maze
279:         if chunk_pos.x.abs() < 1.0 && chunk_pos.z.abs() < 1.0 {
280:             for z in 0..depth {
281:                 for x in 0..width {
282:                     grid.set(x, 0, z, VOXEL_FLOOR);
283:                     grid.set(x, height - 1, z, VOXEL_CEILING);
284:                     
285:                     // Add some scattered lights to the ceiling and floor so it's bright
286:                     if x > 0 && z > 0 && x % 20 == 0 && z % 20 == 0 {
287:                         grid.set(x, height - 1, z, VOXEL_LIGHT);
288:                         grid.set(x, 0, z, VOXEL_LIGHT);
289:                     }
290:                 }
291:             }
292:             crate::domain::use_cases::calculate_lighting::calculate_voxel_lighting(&mut grid);
293:             return grid;
294:         }
295: 
296:         // ==========================================
297:         // DYNAMIC GENERATION (Growing Tree & BSP)
298:         // ==========================================
299:         let mut rng = StdRng::seed_from_u64((seed as u64) ^ (chunk_pos.x.to_bits() as u64) ^ (chunk_pos.z.to_bits() as u64));
300:         
301:         let cell_vw = (5.0 / config.voxel_scale) as usize;
302:         let cell_vd = (5.0 / config.voxel_scale) as usize;
303:         let cell_w = width / cell_vw;
304:         let cell_d = depth / cell_vd;
305:         
306:         let mut abstract_grid = Grid::new(cell_w, cell_d);
307:         let maze_gen = GrowingTreeGenerator {
308:             junction_density: config.tuning.junction_density,
309:         };
310:         maze_gen.generate(&mut abstract_grid, &mut rng);
311: 
312:         // Organic room segmentation
313:         let mut rooms = Vec::new();
314:         let mut room_grid = vec![None; cell_w * cell_d];
315:         
316:         // Tunable parameters
317:         let num_room_attempts = 15;
318:         for _ in 0..num_room_attempts {
319:             let cx = rng.random_range(0..cell_w);
320:             let cz = rng.random_range(0..cell_d);
321:             let rw = rng.random_range(1..=3);
322:             let rd = rng.random_range(1..=3);
323:             
324:             if cx + rw <= cell_w && cz + rd <= cell_d {
325:                 let mut overlap = false;
326:                 for i in 0..rw {
327:                     for j in 0..rd {
328:                         if room_grid[(cz + j) * cell_w + cx + i].is_some() {
329:                             overlap = true;
330:                         }
331:                     }
332:                 }
333:                 if !overlap {
334:                     let room_id = rooms.len();
335:                     for i in 0..rw {
336:                         for j in 0..rd {
337:                             room_grid[(cz + j) * cell_w + cx + i] = Some(room_id);
338:                             if let Some(cell) = abstract_grid.get_mut(cx + i, cz + j) {
339:                                 if j > 0 { cell.walls[0] = false; }
340:                                 if i < rw - 1 { cell.walls[1] = false; }
341:                                 if j < rd - 1 { cell.walls[2] = false; }
342:                                 if i > 0 { cell.walls[3] = false; }
343:                             }
344:                         }
345:                     }
346:                     rooms.push(Room {
347:                         name: "Organic",
348:                         x0: cx * cell_vw,
349:                         x1: (cx + rw) * cell_vw - 1,
350:                         z0: cz * cell_vd,
351:                         z1: (cz + rd) * cell_vd - 1,
352:                     });
353:                 }
354:             }
355:         }
356: 
357:         // Draw abstract grid to VoxelGrid
358:         let wall_max_y = height - 2;
359:         for cz in 0..cell_d {
360:             for cx in 0..cell_w {
361:                 let cell = abstract_grid.get(cx, cz).unwrap();
362:                 let v_x0 = cx * cell_vw;
363:                 let v_z0 = cz * cell_vd;
364:                 let v_x1 = v_x0 + cell_vw - 1;
365:                 let v_z1 = v_z0 + cell_vd - 1;
366: 
367:                 // Floors and Ceilings
368:                 for vx in v_x0..=v_x1 {
369:                     for vz in v_z0..=v_z1 {
370:                         grid.set(vx, 0, vz, VOXEL_FLOOR);
371:                         grid.set(vx, height - 1, vz, VOXEL_CEILING);
372:                     }
373:                 }
374:                 
375:                 // South Wall (z1)
376:                 if cz < cell_d - 1 {
377:                     let same_room = room_grid[cz * cell_w + cx] == room_grid[(cz + 1) * cell_w + cx] 
378:                         && room_grid[cz * cell_w + cx].is_some();
379:                     
380:                     if !same_room {
381:                         let width_choice = rng.random_range(0..100);
382:                         let hole_units = if width_choice < 15 { 1.2 } else if width_choice < 85 { 2.0 } else { 3.5 };
383:                         let hole_w = (hole_units / config.voxel_scale) as usize;
384:                         let min_offset = (0.5 / config.voxel_scale) as usize;
385:                         let max_offset = cell_vw.saturating_sub(hole_w + min_offset);
386:                         let offset = if max_offset > min_offset { rng.random_range(min_offset..max_offset) } else { min_offset };
387:                         let hole_x0 = v_x0 + offset;
388:                         let hole_x1 = hole_x0 + hole_w;
389: 
390:                         for vx in v_x0..=v_x1 {
391:                             if cell.walls[2] || vx < hole_x0 || vx >= hole_x1 {
392:                                 for y in 1..=wall_max_y { grid.set(vx, y, v_z1, VOXEL_WALL); }
393:                             }
394:                         }
395:                     }
396:                 } else if cz == cell_d - 1 {
397:                     // Chunk boundary (force holes for connectivity)
398:                     let hole_w = (2.0 / config.voxel_scale) as usize;
399:                     let hole_x0 = v_x0 + cell_vw / 2 - hole_w / 2;
400:                     for vx in v_x0..=v_x1 {
401:                         let is_hole = vx >= hole_x0 && vx < hole_x0 + hole_w;
402:                         if !is_hole {
403:                             for y in 1..=wall_max_y { grid.set(vx, y, v_z1, VOXEL_WALL); }
404:                         }
405:                     }
406:                 }
407: 
408:                 // East Wall (x1)
409:                 if cx < cell_w - 1 {
410:                     let same_room = room_grid[cz * cell_w + cx] == room_grid[cz * cell_w + cx + 1] 
411:                         && room_grid[cz * cell_w + cx].is_some();
412:                     
413:                     if !same_room {
414:                         let width_choice = rng.random_range(0..100);
415:                         let hole_units = if width_choice < 15 { 1.2 } else if width_choice < 85 { 2.0 } else { 3.5 };
416:                         let hole_w = (hole_units / config.voxel_scale) as usize;
417:                         let min_offset = (0.5 / config.voxel_scale) as usize;
418:                         let max_offset = cell_vd.saturating_sub(hole_w + min_offset);
419:                         let offset = if max_offset > min_offset { rng.random_range(min_offset..max_offset) } else { min_offset };
420:                         let hole_z0 = v_z0 + offset;
421:                         let hole_z1 = hole_z0 + hole_w;
422: 
423:                         for vz in v_z0..=v_z1 {
424:                             if cell.walls[1] || vz < hole_z0 || vz >= hole_z1 {
425:                                 for y in 1..=wall_max_y { grid.set(v_x1, y, vz, VOXEL_WALL); }
426:                             }
427:                         }
428:                     }
429:                 } else if cx == cell_w - 1 {
430:                     let hole_w = (2.0 / config.voxel_scale) as usize;
431:                     let hole_z0 = v_z0 + cell_vd / 2 - hole_w / 2;
432:                     for vz in v_z0..=v_z1 {
433:                         let is_hole = vz >= hole_z0 && vz < hole_z0 + hole_w;
434:                         if !is_hole {
435:                             for y in 1..=wall_max_y { grid.set(v_x1, y, vz, VOXEL_WALL); }
436:                         }
437:                     }
438:                 }
439:             }
440:         }
441:         
442:         // Chunk Boundaries (North and West)
443:         for cz in 0..cell_d {
444:             let cell = abstract_grid.get(0, cz).unwrap();
445:             let v_z0 = cz * cell_vd;
446:             let v_z1 = v_z0 + cell_vd - 1;
447:             let hole_w = (2.0 / config.voxel_scale) as usize;
448:             let hole_z0 = v_z0 + cell_vd / 2 - hole_w / 2;
449:             for vz in v_z0..=v_z1 {
450:                 let is_hole = vz >= hole_z0 && vz < hole_z0 + hole_w;
451:                 if !is_hole {
452:                     for y in 1..=wall_max_y { grid.set(0, y, vz, VOXEL_WALL); }
453:                 }
454:             }
455:         }
456:         for cx in 0..cell_w {
457:             let cell = abstract_grid.get(cx, 0).unwrap();
458:             let v_x0 = cx * cell_vw;
459:             let v_x1 = v_x0 + cell_vw - 1;
460:             let hole_w = (2.0 / config.voxel_scale) as usize;
461:             let hole_x0 = v_x0 + cell_vw / 2 - hole_w / 2;
462:             for vx in v_x0..=v_x1 {
463:                 let is_hole = vx >= hole_x0 && vx < hole_x0 + hole_w;
464:                 if !is_hole {
465:                     for y in 1..=wall_max_y { grid.set(vx, y, 0, VOXEL_WALL); }
466:                 }
467:             }
468:         }
469: 
470: 
471: 
472:         // Apply Room Stamps to generated rooms
473:         let stamps = vec![
474:             RoomStamp::cubicles(),
475:             RoomStamp::showroom(),
476:             RoomStamp::waiting(),
477:             RoomStamp::storage(),
478:             RoomStamp::lounge(),
479:             RoomStamp::server_room(),
480:             RoomStamp::cafeteria(),
481:             RoomStamp::maintenance(),
482:             RoomStamp::stairway(),
483:         ];
484:         
485:         for room in &rooms {
486:             let mut possible_stamps = Vec::new();
487:             for stamp in &stamps {
488:                 let max_stamps_w = (room.x1 - room.x0) / stamp.width.max(1);
489:                 let max_stamps_d = (room.z1 - room.z0) / stamp.depth.max(1);
490:                 if max_stamps_w > 0 && max_stamps_d > 0 {
491:                     possible_stamps.push(stamp);
492:                 }
493:             }
494:             if !possible_stamps.is_empty() {
495:                 let mut stamp = possible_stamps[rng.random_range(0..possible_stamps.len())];
496:                 
497:                 // Low-frequency stairs chance override
498:                 if rng.random_bool(0.15 * (config.tuning.stairs_density as f64)) {
499:                     stamp = &stamps[8]; // stairway
500:                 }
501:                 
502:                 let spacing = (6.0 * (config.voxel_scale / 0.1)) as usize;
503:                 let mut start_x = room.x0 + spacing;
504:                 while start_x + stamp.width <= room.x1.saturating_sub(spacing) {
505:                     let mut start_z = room.z0 + spacing;
506:                     while start_z + stamp.depth <= room.z1.saturating_sub(spacing) {
507:                         if self.validate_stamp_placement(&grid, room, stamp, start_x, start_z) {
508:                             self.place_stamp(&mut grid, stamp, start_x, start_z);
509:                         }
510:                         start_z += stamp.depth + spacing;
511:                     }
512:                     start_x += stamp.width + spacing;
513:                 }
514:             }
515:             
516:             // Basic room lighting
517:             let cx = (room.x0 + room.x1) / 2;
518:             let mut z = room.z0 + 8;
519:             while z <= room.z1.saturating_sub(8) {
520:                 grid.set(cx, height - 1, z, VOXEL_LIGHT);
521:                 z += 12;
522:             }
523:         }
524:         
525:         // Basic corridor lighting
526:         for cz in (8..depth).step_by(16) {
527:             for cx in (8..width).step_by(16) {
528:                 if grid.get(cx, height - 1, cz) == VOXEL_CEILING && grid.get(cx, 1, cz) == VOXEL_AIR {
529:                     grid.set(cx, height - 1, cz, VOXEL_LIGHT);
530:                 }
531:             }
532:         }
533: 
534: 
535:         // ==========================================
536:         // LIGHTING PROPAGATION (BFS Flood fill only)
537:         // ==========================================
538:         crate::domain::use_cases::calculate_lighting::calculate_voxel_lighting(&mut grid);
539: 
540:         let elapsed_micros = self.telemetry.now_micros().saturating_sub(start_micros);
541:         self.telemetry.log(&format!(
542:             "[TELEMETRY] execute completed. Duration={}us, OutputVoxelGridSize={}x{}x{}",
543:             elapsed_micros, grid.width(), grid.height(), grid.depth()
544:         ));
545: 
546:         grid
547:     }
548: 
549:     fn validate_stamp_placement(
550:         &self,
551:         grid: &VoxelGrid,
552:         room: &Room,
553:         stamp: &RoomStamp,
554:         start_x: usize,
555:         start_z: usize,
556:     ) -> bool {
557:         if start_x < room.x0 || start_x + stamp.width > room.x1 ||
558:            start_z < room.z0 || start_z + stamp.depth > room.z1 {
559:             return false;
560:         }
561: 
562:         for lz in 0..stamp.depth {
563:             for lx in 0..stamp.width {
564:                 let vx = start_x + lx;
565:                 let vz = start_z + lz;
566:                 if stamp.data[lz * stamp.width + lx] > 0 {
567:                     if grid.get(vx, 1, vz) != VOXEL_AIR && grid.get(vx, 1, vz) != VOXEL_FLOOR {
568:                         return false;
569:                     }
570:                 }
571:             }
572:         }
573:         
574:         true
575:     }
576: 
577:     fn place_stamp(&self, grid: &mut VoxelGrid, stamp: &RoomStamp, start_x: usize, start_z: usize) {
578:         let max_y = grid.height() - 2;
579:         for sz in 0..stamp.depth {
580:             for sx in 0..stamp.width {
581:                 let val = stamp.data[sz * stamp.width + sx];
582:                 let vx = start_x + sx;
583:                 let vz = start_z + sz;
584:                 if val == 1 {
585:                     for y in 1..=3 {
586:                         grid.set(vx, y, vz, VOXEL_WALL);
587:                     }
588:                 } else if val == 2 {
589:                     for y in 1..=max_y {
590:                         grid.set(vx, y, vz, VOXEL_WALL);
591:                     }
592:                 } else if val == 3 {
593:                     for y in 1..=1 {
594:                         grid.set(vx, y, vz, VOXEL_WALL);
595:                     }
596:                 } else if val == 4 { // Raised floor
597:                     grid.set(vx, 1, vz, VOXEL_FLOOR);
598:                     grid.set(vx, 2, vz, VOXEL_FLOOR);
599:                 } else if val == 5 { // Step 1
600:                     grid.set(vx, 1, vz, VOXEL_FLOOR);
601:                 } else if val == 6 { // Step 2
602:                     // Just floor, already set
603:                 }
604:             }
605:         }
606:     }
607: }
