635:     fn test_chunk_seeding_varies_output() {
636:         let noise = MockNoiseProvider { value: 0.0 };
637:         let generator = GenerateChunkArchitectureUseCase::new(&noise);
638:         let config = GeneratorConfig::high_spec().with_level(0);
