640:         let grid1 = generator.execute(Position::new(10.0, 10.0), 42, config);
641:         let grid2 = generator.execute(Position::new(10.0, 10.0), 43, config);
642:         
643:         let mut diff_count = 0;
644:         for z in 0..grid1.depth() {
645:             for x in 0..grid1.width() {
646:                 if grid1.get(x, 1, z) != grid2.get(x, 1, z) {
647:                     diff_count += 1;
648:                 }
649:             }
