654: 
655:     #[test]
656:     fn test_junction_density_increases_connections() {
657:         use crate::domain::use_cases::generate_maze::{GrowingTreeGenerator, MazeGenerator};
658:         use crate::domain::entities::grid::Grid;
659:         use rand::rngs::StdRng;
660:         use rand::SeedableRng;
661:         
662:         let mut grid_low = Grid::new(20, 20);
663:         let mut rng1 = StdRng::seed_from_u64(42);
664:         let gen_low = GrowingTreeGenerator { junction_density: 0.5 };
665:         gen_low.generate(&mut grid_low, &mut rng1);
666:         
667:         let mut grid_high = Grid::new(20, 20);
668:         let mut rng2 = StdRng::seed_from_u64(42);
669:         let gen_high = GrowingTreeGenerator { junction_density: 2.0 };
670:         gen_high.generate(&mut grid_high, &mut rng2);
671:         
672:         let mut open_low = 0;
673:         let mut open_high = 0;
674:         
675:         for z in 0..20 {
676:             for x in 0..20 {
677:                 if let Some(cell) = grid_low.get(x, z) {
678:                     open_low += cell.walls.iter().filter(|&&w| !w).count();
679:                 }
680:                 if let Some(cell) = grid_high.get(x, z) {
681:                     open_high += cell.walls.iter().filter(|&&w| !w).count();
682:                 }
683:             }
684:         }
685:         
686:         assert!(open_high > open_low, "Expected higher junction density to produce more open walls ({} vs {})", open_high, open_low);
687:     }
