708:                         stairs_zero_count += 1;
709:                     }
710:                 }
711:             }
712:             
713:             let grid_high = generator.execute(Position::new(i as f32, 0.0), 42, config_high);
714:             for z in 0..grid_high.depth() {
715:                 for x in 0..grid_high.width() {
716:                     if grid_high.get(x, 1, z) == VOXEL_FLOOR && grid_high.get(x, 2, z) == VOXEL_FLOOR {
717:                         stairs_high_count += 1;
718:                     }
719:                 }
720:             }
721:         }
722:         
723:         assert_eq!(stairs_zero_count, 0, "Expected zero stairs with density 0.0");
724:         assert!(stairs_high_count > 0, "Expected stairs to generate with density 3.0");
