677:         // Case A: Camera Y is 1.01 (above the center, Y-dominant)
678:         let frame_a = FrameParams { camera_pos: [-1.0, 1.01, -0.1], yaw: 0.0, pitch: 0.0 };
679:         let cam_a = Camera::new(&frame_a, 16, 16);
