681:         // Case B: Camera Y is 0.99 (below Case A, X-dominant)
682:         let frame_b = FrameParams { camera_pos: [-1.0, 0.99, -0.1], yaw: 0.0, pitch: 0.0 };
683:         let cam_b = Camera::new(&frame_b, 16, 16);
684: 
685:         // Clear rasterizer
686:         r.clear();
687:         // Call shade_and_splat for Case A
688:         r.shade_and_splat(
689:             &cam_a,
690:             center,
691:             8.0, 8.0, 1.0,
692:             1.0, // dist
693:             [100.0, 100.0, 100.0], // base color
694:             15.0, // light level
695:             false, // is_emissive
696:             1, // crowded siblings
697:         );
698:         let color_a = center_pixel(&r);
699: 
700:         // Clear rasterizer
701:         r.clear();
702:         // Call shade_and_splat for Case B
703:         r.shade_and_splat(
704:             &cam_b,
705:             center,
706:             8.0, 8.0, 1.0,
707:             1.0, // dist
708:             [100.0, 100.0, 100.0], // base color
709:             15.0, // light level
710:             false, // is_emissive
711:             1, // crowded siblings
712:         );
713:         let color_b = center_pixel(&r);
714: 
715:         // Check difference. Under the old code, Case A gives face = 1.0, Case B gives face = 0.8.
716:         // This is a 20% difference, leading to a difference in color (e.g. 20 out of 255).
717:         // Assert that the difference is very small (e.g., <= 2) to prove continuity/smoothness.
718:         let diff = (color_a[0] as i32 - color_b[0] as i32).abs();
719:         assert!(diff <= 2, "Discontinuity found: diff was {} (color_a = {:?}, color_b = {:?})", diff, color_a, color_b);
