  1: //! In-wasm chunk source: implements the application's [`ChunkSourcePort`] by
  2: //! driving the core engine use cases directly. There is no server round-trip;
  3: //! the entire pipeline — procedural generation, BFS lighting, SVO build, GPU
  4: //! serialization, collision extraction — runs inside the wasm module.
  5: //!
  6: //! Pipeline per chunk:
  7: //!   GenerateChunkArchitectureUseCase  (VoxelGrid, lighting included)
  8: //!     -> BuildOctreeUseCase           (SparseVoxelOctree)
  9: //!     -> OctreeGpuSerializer          (row-padded RGBA32UI texel stream)
 10: //!     -> collision walk               (solid leaves -> world-space AABBs)
 11: 
 12: use vackrooms::adapters::octree_gpu_serializer::OctreeGpuSerializer;
 13: use vackrooms::domain::entities::sparse_voxel_octree::{SparseVoxelOctree, SvoNode};
 14: use vackrooms::domain::use_cases::build_octree::BuildOctreeUseCase;
 15: use vackrooms::entities::models::Position;
 16: use vackrooms::use_cases::generate_chunk::{GenerateChunkArchitectureUseCase, GeneratorConfig};
 17: use vackrooms::use_cases::ports::{NoiseProvider, TelemetryPort, NULL_TELEMETRY};
 18: 
 19: use crate::application::collision::Aabb;
 20: use crate::application::ports::{ChunkPayload, ChunkSourcePort};
 21: 
 22: /// Voxel types that block the player. FLOOR/CEILING/LIGHT/GRASS/WATER are
 23: /// visual-only: including them would make the player collide with the floor
 24: /// they stand on.
 25: const SOLID_TYPES: [u8; 3] = [
 26:     vackrooms::domain::entities::voxel_grid::VOXEL_WALL,
 27:     vackrooms::domain::entities::voxel_grid::VOXEL_RED_WALL,
 28:     vackrooms::domain::entities::voxel_grid::VOXEL_TREE,
 29: ];
 30: 
 31: pub struct LocalChunkSource<N: NoiseProvider> {
 32:     noise: N,
 33:     telemetry: &'static dyn TelemetryPort,
 34:     seed: u32,
 35:     config: GeneratorConfig,
 36: }
 37: 
 38: impl<N: NoiseProvider> LocalChunkSource<N> {
 39:     pub fn new(noise: N, seed: u32, config: GeneratorConfig) -> Self {
 40:         Self { noise, telemetry: &NULL_TELEMETRY, seed, config }
 41:     }
 42: 
 43:     pub fn with_telemetry(
 44:         noise: N,
 45:         seed: u32,
 46:         config: GeneratorConfig,
 47:         telemetry: &'static dyn TelemetryPort,
 48:     ) -> Self {
 49:         Self { noise, telemetry, seed, config }
 50:     }
 51: }
 52: 
 53: impl<N: NoiseProvider> ChunkSourcePort for LocalChunkSource<N> {
 54:     fn load(&self, origin_x: f32, origin_z: f32, level: u32) -> ChunkPayload {
 55:         let generator =
 56:             GenerateChunkArchitectureUseCase::with_telemetry(&self.noise, self.telemetry);
 57:         let grid = generator.execute(
 58:             Position::new(origin_x, origin_z),
 59:             self.seed,
 60:             self.config.with_level(level),
 61:         );
 62: 
 63:         let svo = BuildOctreeUseCase::new().execute(
 64:             &grid,
 65:             self.config.svo_depth(),
 66:             self.config.svo_world_size(),
 67:         );
 68: 
 69:         let gpu = OctreeGpuSerializer::serialize_to_gpu_data(&svo);
 70:         let collision =
 71:             extract_collision_boxes(&svo, origin_x, origin_z, self.config.voxel_scale);
 72: 
 73:         ChunkPayload {
 74:             root: svo.root as u32,
 75:             nodes: gpu.texel_data,
 76:             world_size: self.config.svo_world_size(),
 77:             collision,
 78:         }
 79:     }
 80: }
 81: 
 82: /// Walks the SVO and emits one world-space AABB per solid leaf region.
 83: /// Uniform subtrees collapsed by the SVO become single large boxes for free,
 84: /// which keeps the collision set small.
 85: pub fn extract_collision_boxes(
 86:     svo: &SparseVoxelOctree,
 87:     origin_x: f32,
 88:     origin_z: f32,
 89:     voxel_scale: f32,
 90: ) -> Vec<Aabb> {
 91:     let mut boxes = Vec::new();
 92:     let size = 1u32 << svo.depth;
 93:     walk(svo, svo.root, 0, 0, 0, size, origin_x, origin_z, voxel_scale, &mut boxes);
 94:     boxes
 95: }
 96: 
 97: #[allow(clippy::too_many_arguments)]
 98: fn walk(
 99:     svo: &SparseVoxelOctree,
100:     node_idx: usize,
101:     x: u32,
102:     y: u32,
103:     z: u32,
104:     size: u32,
105:     origin_x: f32,
106:     origin_z: f32,
107:     voxel_scale: f32,
108:     out: &mut Vec<Aabb>,
109: ) {
110:     match svo.nodes[node_idx] {
111:         SvoNode::Leaf { voxel_type, .. } => {
112:             if SOLID_TYPES.contains(&voxel_type) {
113:                 let min = [
114:                     origin_x + x as f32 * voxel_scale,
115:                     y as f32 * voxel_scale,
116:                     origin_z + z as f32 * voxel_scale,
117:                 ];
118:                 let extent = size as f32 * voxel_scale;
119:                 out.push(Aabb::new(min, [min[0] + extent, min[1] + extent, min[2] + extent]));
120:             }
121:         }
122:         SvoNode::Internal { child_base_index, child_mask } => {
123:             let half = size / 2;
124:             for child in 0..8u32 {
125:                 if child_mask & (1 << child) != 0 {
126:                     walk(
127:                         svo,
128:                         child_base_index as usize + child as usize,
129:                         x + (child & 1) * half,
130:                         y + ((child >> 1) & 1) * half,
131:                         z + ((child >> 2) & 1) * half,
132:                         half,
133:                         origin_x,
134:                         origin_z,
135:                         voxel_scale,
136:                         out,
137:                     );
138:                 }
139:             }
140:         }
141:     }
142: }
143: 
