156: 
157:         let boxes = extract_collision_boxes(&svo, 10.0, 20.0, 0.5);
158:         assert_eq!(boxes.len(), 1);
159:         let b = &boxes[0];
160:         assert_eq!(b.min, [10.5, 0.0, 21.0]);
161:         assert_eq!(b.max, [11.0, 0.5, 21.5]);
