171:         let payload = source.load(10.0, 10.0, 0);
172:         // Row padding: node stream is a whole number of 1024-texel rows.
173:         assert_eq!(payload.nodes.len() % (1024 * 4), 0);
174:         assert!(payload.world_size > 0.0);
175:         assert!(!payload.collision.is_empty(), "a maze chunk must have walls");
176:     }
