 93:         let mut chunk_1_nodes = vec![0; 512 * 4];
 94:         // chunk 1 node 0: internal, child_base = 8
 95:         chunk_1_nodes[0] = 0;
 96:         chunk_1_nodes[1] = 8;
 97:         // chunk 1 node 1: leaf (type 1)
 98:         chunk_1_nodes[4] = 1;
 99:         chunk_1_nodes[5] = 42; // voxel_type
100: 
101:         let chunks = [
102:             LoadedChunk {
103:                 origin: (0.0, 0.0),
104:                 payload: ChunkPayload { root: 0, nodes: chunk_0_nodes, world_size: 10.0, collision: vec![] }
105:             },
106:             LoadedChunk {
107:                 origin: (10.0, 0.0),
108:                 payload: ChunkPayload { root: 0, nodes: chunk_1_nodes, world_size: 10.0, collision: vec![] }
109:             }
110:         ];
111: 
112:         let build = build_atlas(chunks.iter());
113: 
114:         // Chunk 0 node 0: child_base should still be 0 (since offset is 0)
115:         assert_eq!(build.texels[1], 0);
116: 
117:         // Chunk 1 node 0 (starts at texel index 256):
118:         // child_base was 8, should be shifted by chunk 0 size (256) -> 264
119:         assert_eq!(build.texels[256 * 4 + 1], 264);
120: 
121:         // Chunk 1 node 1 (leaf): should NOT be shifted since R == 1
122:         assert_eq!(build.texels[257 * 4], 1); // R
123:         assert_eq!(build.texels[257 * 4 + 1], 42); // G (voxel_type)
124:     }
125: }

