  1: //! The frame-loop orchestrator: the application's central use case.
  2: //!
  3: //! `Engine::tick` is called once per animation frame by the browser driver
  4: //! with plain data in (`InputFrame`, dt) and drives everything else through
  5: //! ports: chunk loading via [`ChunkSourcePort`], drawing via [`RendererPort`].
  6: //! No browser types appear anywhere in this file, so the whole game loop is
  7: //! natively unit-testable.
  8: 
  9: use crate::application::atlas::{build_atlas, MAX_CHUNKS};
 10: use crate::application::collision::CollisionWorld;
 11: use crate::application::player::{MoveIntent, Player};
 12: use crate::application::ports::{ChunkDraw, ChunkSourcePort, FrameParams, RendererPort};
 13: use crate::application::streaming::{chunk_key, ChunkStore, LoadedChunk, StreamingPolicy};
 14: 
 15: /// Static configuration chosen by the composition root.
 16: #[derive(Debug, Clone, Copy)]
 17: pub struct EngineConfig {
 18:     pub seed: u32,
 19:     /// World-space chunk side length (must match the generator config).
 20:     pub chunk_size: f32,
 21:     /// Streaming radius in chunks (1 = 3x3, 2 = 5x5).
 22:     pub chunk_radius: i32,
 23:     /// Player spawn (eye position).
 24:     pub spawn: [f32; 3],
 25:     /// Chunks generated per tick. 2 balances streaming latency against
 26:     /// frame hitches: one chunk costs ~15 ms native (more in wasm), so
 27:     /// higher budgets stall the frame visibly.
 28:     pub max_loads_per_tick: usize,
 29: }
 30: 
 31: impl Default for EngineConfig {
 32:     fn default() -> Self {
 33:         Self {
 34:             seed: 42,
 35:             chunk_size: 10.0,
 36:             chunk_radius: 1,
 37:             spawn: [5.0, 1.7, 5.0],
 38:             max_loads_per_tick: 2,
 39:         }
 40:     }
 41: }
 42: 
 43: /// One frame's worth of user input, already translated to domain terms by
 44: /// the input adapter.
 45: #[derive(Debug, Clone, Copy, Default)]
 46: pub struct InputFrame {
 47:     pub intent: MoveIntent,
 48:     pub look_dx: f32,
 49:     pub look_dy: f32,
 50:     /// Whether pointer lock is engaged; movement is frozen otherwise.
 51:     pub locked: bool,
 52: }
 53: 
 54: /// Snapshot for the HUD presenter.
 55: #[derive(Debug, Clone, Copy, PartialEq)]
 56: pub struct HudStats {
 57:     pub resident_chunks: usize,
 58:     pub atlas_nodes: usize,
 59:     pub collision_boxes: usize,
 60:     pub resolution_scale: f32,
 61:     /// True once the spawn chunk is resident (drives the loading overlay).
 62:     pub ready: bool,
 63: }
 64: 
 65: /// Adaptive internal-resolution governor. Low-spec machines get fewer rays
 66: /// per frame by rendering at a reduced backing-store resolution; the driver
 67: /// applies the scale to the canvas. Hysteresis + cooldown prevent flapping.
 68: #[derive(Debug, Clone, Copy)]
 69: pub struct PerfGovernor {
 70:     ema_frame_ms: f32,
 71:     scale: f32,
 72:     cooldown_frames: u32,
 73: }
 74: 
 75: impl PerfGovernor {
 76:     const SCALES: [f32; 4] = [0.5, 0.65, 0.8, 1.0];
 77: 
 78:     pub fn new() -> Self {
 79:         Self { ema_frame_ms: 16.0, scale: 0.8, cooldown_frames: 0 }
 80:     }
 81: 
 82:     pub fn scale(&self) -> f32 {
 83:         self.scale
 84:     }
 85: 
 86:     pub fn update(&mut self, frame_ms: f32) {
 87:         self.ema_frame_ms = self.ema_frame_ms * 0.95 + frame_ms.clamp(0.0, 100.0) * 0.05;
 88:         if self.cooldown_frames > 0 {
 89:             self.cooldown_frames -= 1;
 90:             return;
 91:         }
 92:         let idx = Self::SCALES.iter().position(|&s| s == self.scale).unwrap_or(2);
 93:         if self.ema_frame_ms > 33.0 && idx > 0 {
 94:             // Sustained under ~30 fps: drop one resolution step.
 95:             self.scale = Self::SCALES[idx - 1];
 96:             self.cooldown_frames = 120;
 97:         } else if self.ema_frame_ms < 15.0 && idx + 1 < Self::SCALES.len() {
 98:             // Sustained over ~66 fps: try one step up.
 99:             self.scale = Self::SCALES[idx + 1];
100:             self.cooldown_frames = 240;
101:         }
102:     }
103: }
104: 
105: /// Backrooms level ids the engine can noclip between.
106: const LEVEL_BACKROOMS: u32 = 0;
107: const LEVEL_GRASSLAND: u32 = 34;
108: /// Keep pushing into a wall this long before a noclip roll happens...
109: const NOCLIP_PUSH_SECONDS: f32 = 1.2;
110: /// ...then one roll per second of continued pushing, at this probability.
111: const NOCLIP_CHANCE: f32 = 0.2;
112: 
113: pub struct Engine {
114:     config: EngineConfig,
115:     player: Player,
116:     policy: StreamingPolicy,
117:     store: ChunkStore,
118:     world: CollisionWorld,
119:     draws: Vec<ChunkDraw>,
120:     atlas_nodes: usize,
121:     governor: PerfGovernor,
122:     renderer: Box<dyn RendererPort>,
123:     source: Box<dyn ChunkSourcePort>,
124:     /// Active Backrooms level; chunks are requested for this level.
125:     level: u32,
126:     /// How long the player has been pushing into a wall without moving.
127:     push_seconds: f32,
128:     /// Seconds until the next noclip roll is allowed.
129:     noclip_cooldown: f32,
130:     /// xorshift state for the noclip dice.
131:     rng: u64,
132: }
133: 
134: impl Engine {
135:     pub fn new(
136:         config: EngineConfig,
137:         renderer: Box<dyn RendererPort>,
138:         source: Box<dyn ChunkSourcePort>,
139:     ) -> Self {
140:         let radius = config.chunk_radius.clamp(0, 2); // 5x5 max = shader table size
141:         Self {
142:             player: Player::new(config.spawn),
143:             policy: StreamingPolicy { chunk_size: config.chunk_size, radius },
144:             store: ChunkStore::new(),
145:             world: CollisionWorld::new(),
146:             draws: Vec::new(),
147:             atlas_nodes: 0,
148:             governor: PerfGovernor::new(),
149:             renderer,
150:             source,
151:             level: LEVEL_BACKROOMS,
152:             push_seconds: 0.0,
153:             noclip_cooldown: 0.0,
154:             rng: (config.seed as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1,
155:             config,
156:         }
157:     }
158: 
159:     fn rng_next01(&mut self) -> f32 {
160:         self.rng ^= self.rng << 13;
161:         self.rng ^= self.rng >> 7;
162:         self.rng ^= self.rng << 17;
163:         (self.rng >> 40) as f32 / (1u64 << 24) as f32
164:     }
165: 
166:     /// Backrooms lore made mechanical: holding a walk into solid wall long
167:     /// enough occasionally phases the player through reality.
168:     fn update_noclip(&mut self, dt: f32, input: &InputFrame, old_pos: [f32; 3]) {
169:         self.noclip_cooldown = (self.noclip_cooldown - dt).max(0.0);
170: 
171:         let i = input.intent;
172:         let pushing = input.locked && (i.forward || i.backward || i.left || i.right);
173:         let dx = self.player.position[0] - old_pos[0];
174:         let dz = self.player.position[2] - old_pos[2];
175:         let pinned = pushing && (dx * dx + dz * dz) < 0.002 * 0.002;
176: 
177:         if !pinned {
178:             self.push_seconds = 0.0;
179:             return;
180:         }
181:         self.push_seconds += dt;
182:         if self.push_seconds < NOCLIP_PUSH_SECONDS || self.noclip_cooldown > 0.0 {
183:             return;
184:         }
185:         self.noclip_cooldown = 1.0;
186:         if self.rng_next01() < NOCLIP_CHANCE {
187:             self.noclip();
188:         }
189:     }
190: 
191:     /// Phase between Level 0 and the grassland: drop every resident chunk so
192:     /// the streamer rebuilds the world from the new level's generator.
193:     fn noclip(&mut self) {
194:         self.level = if self.level == LEVEL_BACKROOMS {
195:             LEVEL_GRASSLAND
196:         } else {
197:             LEVEL_BACKROOMS
198:         };
199:         self.store.retain_keys(&[]);
200:         self.world.rebuild([].iter());
201:         self.draws.clear();
202:         self.push_seconds = 0.0;
203:         // Into the grassland you phase in place; the way back drops you at
204:         // the spawn clearing so you can't rematerialize inside a wall.
205:         if self.level == LEVEL_BACKROOMS {
206:             self.player.position = self.config.spawn;
207:         }
208:     }
209: 
210:     /// The active Backrooms level id.
211:     pub fn level(&self) -> u32 {
212:         self.level
213:     }
214: 
215:     /// Advances the simulation one frame and issues the draw.
216:     pub fn tick(&mut self, dt_seconds: f32, input: &InputFrame) {
217:         // Clamp dt so a background-tab hitch can't teleport the player.
218:         let dt = dt_seconds.clamp(0.0, 0.1);
219:         self.governor.update(dt_seconds * 1000.0);
220: 
221:         let old_pos = self.player.position;
222:         if input.locked {
223:             self.player.apply_look(input.look_dx, input.look_dy);
224:             self.player.step(dt, &input.intent, &self.world);
225:         }
226:         self.update_noclip(dt, input, old_pos);
227: 
228:         self.stream_chunks();
229: 
230:         let frame = FrameParams {
231:             camera_pos: self.player.position,
232:             yaw: self.player.yaw,
233:             pitch: self.player.pitch,
234:         };
235:         self.renderer.draw(&frame, &self.draws);
236:     }
237: 
238:     /// Loads at most `max_loads_per_tick` missing chunks (nearest first),
239:     /// evicts out-of-range ones, and rebuilds the atlas + collision world
240:     /// only when the resident set actually changed.
241:     fn stream_chunks(&mut self) {
242:         let desired = self
243:             .policy
244:             .desired_origins(self.player.position[0], self.player.position[2]);
245:         let keep: Vec<_> = desired.iter().map(|&(x, z)| chunk_key(x, z)).collect();
246: 
247:         let mut changed = self.store.retain_keys(&keep);
248: 
249:         let mut loads = 0;
250:         for &(ox, oz) in &desired {
251:             if loads >= self.config.max_loads_per_tick {
252:                 break;
253:             }
254:             let key = chunk_key(ox, oz);
255:             if !self.store.contains(key) {
256:                 let payload = self.source.load(ox, oz, self.level);
257:                 self.store.insert(key, LoadedChunk { origin: (ox, oz), payload });
258:                 loads += 1;
259:                 changed = true;
260:             }
261:         }
262: 
263:         if changed {
264:             let build = build_atlas(self.store.iter_ordered());
265:             self.atlas_nodes = build.texels.len() / 4;
266:             self.draws = build.draws;
267:             self.draws.truncate(MAX_CHUNKS);
268:             self.renderer.upload_atlas(&build.texels);
269: 
270:             let boxes: Vec<_> = self.store.all_collision_boxes().copied().collect();
271:             self.world.rebuild(boxes.iter());
272:         }
273:     }
274: 
275:     pub fn player(&self) -> &Player {
276:         &self.player
277:     }
278: 
279:     pub fn collision_world(&self) -> &CollisionWorld {
280:         &self.world
281:     }
282: 
283:     pub fn stats(&self) -> HudStats {
284:         let spawn_key = chunk_key(
285:             (self.config.spawn[0] / self.config.chunk_size).floor() * self.config.chunk_size,
286:             (self.config.spawn[2] / self.config.chunk_size).floor() * self.config.chunk_size,
287:         );
288:         HudStats {
289:             resident_chunks: self.store.len(),
290:             atlas_nodes: self.atlas_nodes,
291:             collision_boxes: self.world.len(),
292:             resolution_scale: self.governor.scale(),
293:             ready: self.store.contains(spawn_key),
294:         }
295:     }
296: }
297: 
298: #[cfg(test)]
299: mod tests {
300:     use super::*;
301:     use crate::application::collision::Aabb;
302:     use crate::application::ports::ChunkPayload;
303:     use std::cell::RefCell;
304:     use std::rc::Rc;
305: 
306:     #[derive(Default)]
307:     struct RecordingRenderer {
308:         uploads: Rc<RefCell<Vec<usize>>>,
309:         draws: Rc<RefCell<Vec<usize>>>,
310:     }
311: 
312:     impl RendererPort for RecordingRenderer {
313:         fn upload_atlas(&mut self, texels: &[u32]) {
314:             self.uploads.borrow_mut().push(texels.len());
315:         }
316:         fn draw(&mut self, _frame: &FrameParams, chunks: &[ChunkDraw]) {
317:             self.draws.borrow_mut().push(chunks.len());
318:         }
319:     }
320: 
321:     struct FlatChunkSource;
322: 
323:     impl ChunkSourcePort for FlatChunkSource {
324:         fn load(&self, origin_x: f32, _origin_z: f32, _level: u32) -> ChunkPayload {
325:             ChunkPayload {
326:                 root: 0,
327:                 nodes: [1u32, 0, 0, 0].repeat(1024), // one padded row of air leaves
328:                 world_size: 12.8,
329:                 collision: vec![Aabb::new(
330:                     [origin_x, 0.0, 0.0],
331:                     [origin_x + 0.2, 3.0, 0.2],
332:                 )],
333:             }
334:         }
335:     }
336: 
337:     /// Chunk source that traps the player: one huge collision box around the
338:     /// spawn, and it records which level each load was for.
339:     struct TrappingChunkSource {
340:         levels: Rc<RefCell<Vec<u32>>>,
341:     }
342: 
343:     impl ChunkSourcePort for TrappingChunkSource {
344:         fn load(&self, _x: f32, _z: f32, level: u32) -> ChunkPayload {
345:             self.levels.borrow_mut().push(level);
346:             ChunkPayload {
347:                 root: 0,
348:                 nodes: [1u32, 0, 0, 0].repeat(1024),
349:                 world_size: 12.8,
350:                 collision: vec![Aabb::new([-100.0, 0.0, -100.0], [100.0, 3.0, 100.0])],
351:             }
352:         }
353:     }
354: 
355:     fn engine_with_recorder() -> (Engine, Rc<RefCell<Vec<usize>>>, Rc<RefCell<Vec<usize>>>) {
356:         let renderer = RecordingRenderer::default();
357:         let uploads = renderer.uploads.clone();
358:         let draws = renderer.draws.clone();
359:         let engine = Engine::new(
360:             EngineConfig::default(),
361:             Box::new(renderer),
362:             Box::new(FlatChunkSource),
363:         );
364:         (engine, uploads, draws)
365:     }
366: 
367:     #[test]
368:     fn streams_multiple_chunks_per_tick_up_to_max_loads() {
369:         let (mut engine, uploads, _draws) = engine_with_recorder();
370:         let input = InputFrame::default();
371:         
372:         // 9 chunks total are desired (radius 1). With max_loads_per_tick=2:
373:         // 2+2+2+2+1 over five ticks.
374:         for expected in [2usize, 4, 6, 8, 9] {
375:             engine.tick(1.0 / 60.0, &input);
376:             assert_eq!(engine.stats().resident_chunks, expected);
377:         }
378:         assert_eq!(uploads.borrow().len(), 5);
379: 
380:         // Subsequent ticks should not load anything or re-upload.
381:         for _ in 0..5 {
382:             engine.tick(1.0 / 60.0, &input);
383:         }
384:         assert_eq!(engine.stats().resident_chunks, 9);
385:         assert_eq!(uploads.borrow().len(), 5);
386:         assert!(engine.stats().ready);
387:     }
388: 
389:     #[test]
390:     fn steady_state_does_not_reupload_atlas() {
391:         let (mut engine, uploads, _) = engine_with_recorder();
392:         let input = InputFrame::default();
393:         for _ in 0..20 {
394:             engine.tick(1.0 / 60.0, &input);
395:         }
396:         assert_eq!(uploads.borrow().len(), 5, "no uploads once resident set is stable");
397:     }
398: 
399:     #[test]
400:     fn collision_world_tracks_resident_chunks() {
401:         let (mut engine, _, _) = engine_with_recorder();
402:         let input = InputFrame::default();
403:         for _ in 0..9 {
404:             engine.tick(1.0 / 60.0, &input);
405:         }
406:         assert_eq!(engine.collision_world().len(), 9);
407:     }
408: 
409:     #[test]
410:     fn pushing_into_a_wall_eventually_noclips_to_the_grassland() {
411:         let levels = Rc::new(RefCell::new(Vec::new()));
412:         let mut engine = Engine::new(
413:             EngineConfig::default(),
414:             Box::new(RecordingRenderer::default()),
415:             Box::new(TrappingChunkSource { levels: levels.clone() }),
416:         );
417:         assert_eq!(engine.level(), 0);
418: 
419:         // Hold forward into the wall. 20% per roll, one roll per second of
420:         // pushing: 120 simulated seconds without a switch is ~1e-11 likely.
421:         let input = InputFrame {
422:             intent: crate::application::player::MoveIntent { forward: true, ..Default::default() },
423:             locked: true,
424:             ..Default::default()
425:         };
426:         let mut switched_at = None;
427:         for tick in 0..(120 * 60) {
428:             engine.tick(1.0 / 60.0, &input);
429:             if engine.level() != 0 {
430:                 switched_at = Some(tick);
431:                 break;
432:             }
433:         }
434:         assert_eq!(engine.level(), 34, "never noclipped (switched_at={switched_at:?})");
435:         // New chunks must be requested for the grassland level.
436:         for _ in 0..5 {
437:             engine.tick(1.0 / 60.0, &input);
438:         }
439:         assert!(
440:             levels.borrow().iter().any(|&l| l == 34),
441:             "chunk source never asked for level 34: {:?}",
442:             levels.borrow()
443:         );
444:     }
445: 
446:     #[test]
447:     fn walking_freely_never_noclips() {
448:         let (mut engine, _, _) = engine_with_recorder();
449:         let input = InputFrame {
450:             intent: crate::application::player::MoveIntent { forward: true, ..Default::default() },
451:             locked: true,
452:             ..Default::default()
453:         };
454:         for _ in 0..(60 * 60) {
455:             engine.tick(1.0 / 60.0, &input);
456:         }
457:         assert_eq!(engine.level(), 0, "noclip fired without a wall");
458:     }
459: 
460:     #[test]
461:     fn governor_drops_resolution_under_sustained_load() {
462:         let mut governor = PerfGovernor::new();
463:         for _ in 0..200 {
464:             governor.update(50.0); // 20 fps
465:         }
466:         assert!(governor.scale() < 0.8);
467:     }
468: }

files.wasm_frontend/src/application/player.rs:
  1: //! First-person player controller: mouse look, WASD movement with friction,
  2: //! and axis-separated sliding collision against the [`CollisionWorld`].
  3: //!
  4: //! The tuning constants are carried over 1:1 from the original JS client so
  5: //! the wasm port feels identical.
  6: 
  7: use crate::application::collision::CollisionWorld;
  8: 
  9: /// Acceleration applied while a movement key is held (units/s^2 toward the
 10: /// wish direction). Terminal speed = ACCELERATION / FRICTION = 2.5 u/s (increased from 0.5 u/s).
 11: const ACCELERATION: f32 = 20.0;
 12: /// Exponential velocity damping factor (1/s).
 13: const FRICTION: f32 = 8.0;
 14: /// Radians of yaw/pitch per pixel of mouse movement.
 15: const MOUSE_SENSITIVITY: f32 = 0.002;
 16: /// Pitch is clamped just short of straight up/down to avoid gimbal flip.
 17: const PITCH_LIMIT: f32 = std::f32::consts::FRAC_PI_2 - 0.05;
 18: 
 19: /// Which movement keys are currently held.
 20: #[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
 21: pub struct MoveIntent {
 22:     pub forward: bool,
 23:     pub backward: bool,
 24:     pub left: bool,
 25:     pub right: bool,
 26: }
 27: 
 28: /// Player state. Position is the *eye* position in world space.
 29: #[derive(Debug, Clone)]
 30: pub struct Player {
 31:     pub position: [f32; 3],
 32:     pub yaw: f32,
 33:     pub pitch: f32,
 34:     /// Velocity in camera-local space: x = strafe, z = forward.
 35:     vel_strafe: f32,
 36:     vel_forward: f32,
 37: }
 38: 
 39: impl Player {
 40:     pub fn new(position: [f32; 3]) -> Self {
 41:         Self {
 42:             position,
 43:             yaw: 0.0,
 44:             pitch: 0.0,
 45:             vel_strafe: 0.0,
 46:             vel_forward: 0.0,
 47:         }
 48:     }
 49: 
 50:     /// Applies a mouse movement delta (in pixels) to yaw/pitch.
 51:     pub fn apply_look(&mut self, dx: f32, dy: f32) {
 52:         self.yaw -= dx * MOUSE_SENSITIVITY;
 53:         self.pitch = (self.pitch - dy * MOUSE_SENSITIVITY).clamp(-PITCH_LIMIT, PITCH_LIMIT);
 54:     }
 55: 
 56:     /// World-space unit forward vector projected on the ground plane.
 57:     pub fn forward(&self) -> [f32; 3] {
 58:         [-self.yaw.sin(), 0.0, -self.yaw.cos()]
 59:     }
 60: 
 61:     /// World-space unit right vector on the ground plane.
 62:     pub fn right(&self) -> [f32; 3] {
 63:         [self.yaw.cos(), 0.0, -self.yaw.sin()]
 64:     }
 65: 
 66:     /// Integrates one physics step and resolves collision by sliding:
 67:     /// the X and Z axes are moved and tested independently, so hitting a
 68:     /// wall diagonally slides the player along it instead of stopping dead.
 69:     pub fn step(&mut self, dt: f32, intent: &MoveIntent, world: &CollisionWorld) {
 70:         // Friction: exponential-style decay, matching `v -= v * 8 * dt`.
 71:         self.vel_strafe -= self.vel_strafe * FRICTION * dt;
 72:         self.vel_forward -= self.vel_forward * FRICTION * dt;
 73: 
 74:         let mut wish_forward = (intent.forward as i32 - intent.backward as i32) as f32;
 75:         let mut wish_strafe = (intent.right as i32 - intent.left as i32) as f32;
 76:         let len = (wish_forward * wish_forward + wish_strafe * wish_strafe).sqrt();
 77:         if len > 0.0 {
 78:             wish_forward /= len;
 79:             wish_strafe /= len;
 80:         }
 81: 
 82:         self.vel_forward += wish_forward * ACCELERATION * dt;
 83:         self.vel_strafe += wish_strafe * ACCELERATION * dt;
 84: 
 85:         let fwd = self.forward();
 86:         let rgt = self.right();
 87:         let step_x = (fwd[0] * self.vel_forward + rgt[0] * self.vel_strafe) * dt;
 88:         let step_z = (fwd[2] * self.vel_forward + rgt[2] * self.vel_strafe) * dt;
 89: 
 90:         let old = self.position;
 91: 
 92:         self.position[0] = old[0] + step_x;
 93:         if world.collides(self.position) {
 94:             self.position[0] = old[0];
 95:         }
 96: 
 97:         self.position[2] = old[2] + step_z;
 98:         if world.collides(self.position) {
 99:             self.position[2] = old[2];
100:         }
101:     }
102: }
103: 
104: #[cfg(test)]
105: mod tests {
106:     use super::*;
107:     use crate::application::collision::Aabb;
108: 
109:     fn walk(player: &mut Player, world: &CollisionWorld, intent: MoveIntent, seconds: f32) {
110:         let dt = 1.0 / 60.0;
111:         let steps = (seconds / dt) as usize;
112:         for _ in 0..steps {
113:             player.step(dt, &intent, world);
114:         }
115:     }
116: 
117:     #[test]
118:     fn forward_intent_moves_along_negative_z_at_zero_yaw() {
119:         let world = CollisionWorld::new();
120:         let mut p = Player::new([0.0, 1.7, 0.0]);
121:         walk(&mut p, &world, MoveIntent { forward: true, ..Default::default() }, 2.0);
122:         assert!(p.position[2] < -0.5, "expected forward motion, z = {}", p.position[2]);
123:         assert!(p.position[0].abs() < 1e-3);
124:     }
125: 
126:     #[test]
127:     fn speed_converges_to_terminal_velocity() {
128:         let world = CollisionWorld::new();
129:         let mut p = Player::new([0.0, 1.7, 0.0]);
130:         walk(&mut p, &world, MoveIntent { forward: true, ..Default::default() }, 5.0);
131:         let before = p.position[2];
132:         walk(&mut p, &world, MoveIntent { forward: true, ..Default::default() }, 1.0);
133:         let speed = (before - p.position[2]).abs();
134:         // Terminal speed = ACCELERATION / FRICTION = 2.5 u/s (was 0.5 u/s).
135:         assert!((speed - 2.5).abs() < 0.05, "speed was {speed}");
136:     }
137: 
138:     #[test]
139:     fn diagonal_wall_hit_slides_along_wall() {
140:         let mut world = CollisionWorld::new();
141:         // Wall blocking motion in -z ahead of the player.
142:         world.rebuild(&[Aabb::new([-10.0, 0.0, -2.0], [10.0, 3.0, -1.8])]);
143:         let mut p = Player::new([0.0, 1.7, 0.0]);
144:         // Move forward-right: z blocked by the wall, x should still advance.
145:         walk(
146:             &mut p,
147:             &world,
148:             MoveIntent { forward: true, right: true, ..Default::default() },
149:             4.0,
150:         );
151:         assert!(p.position[2] > -1.5, "should be stopped by wall");
152:         assert!(p.position[0] > 0.5, "should have slid along the wall, x = {}", p.position[0]);
153:     }
154: }

