  1: //! GLSL ES 3.00 shaders for the fullscreen SVO raymarcher.
  2: //!
  3: //! Ported 1:1 from the proven raw-WebGL2 path of the original JS client.
  4: //! Pipeline per fragment:
  5: //!   1. Reconstruct the camera ray from NDC + yaw/pitch.
  6: //!   2. Slab-test every resident chunk AABB, insertion-sorting hits by entry
  7: //!      distance so the nearest chunk is marched first (early out on hit).
  8: //!   3. March the chunk's SVO with stack-based descent + empty-space skipping:
  9: //!      an empty leaf/octant is exited in a single step via its AABB exit
 10: //!      plane instead of voxel-by-voxel DDA.
 11: //!   4. Shade from the leaf's packed RGB color, BFS light level, face normal
 12: //!      and exponential distance fog.
 13: //!
 14: //! The SVO node atlas lives in a 1024-texel-wide RGBA32UI texture; the texel
 15: //! encoding is documented in the core's `OctreeGpuSerializer`.
 16: 
 17: /// Fullscreen-triangle-pair vertex shader.
 18: pub const VERTEX_SHADER: &str = r#"#version 300 es
 19: in vec2 position;
 20: out vec2 vUv;
 21: void main() {
 22:     vUv = position * 0.5 + 0.5;
 23:     gl_Position = vec4(position, 0.0, 1.0);
 24: }
 25: "#;
 26: 
 27: pub const FRAGMENT_SHADER: &str = r#"#version 300 es
 28: precision highp float;
 29: precision highp usampler2D;
 30: 
 31: in vec2 vUv;
 32: out vec4 fragColor;
 33: 
 34: uniform vec3 uCameraPosition;
 35: uniform float uYaw;
 36: uniform float uPitch;
 37: uniform float uAspect;
 38: 
 39: uniform usampler2D uNodeTexture;
 40: uniform int uNumChunks;
 41: uniform vec3 uChunkOrigins[25];
 42: uniform int uChunkRootIndices[25];
 43: uniform float uChunkWorldSizes[25];
 44: 
 45: struct StackFrame {
 46:     int node_idx;
 47:     vec3 b_min;
 48:     vec3 b_max;
 49: };
 50: 
 51: struct ChunkHit {
 52:     int idx;
 53:     float t_min;
 54:     float t_max;
 55: };
 56: 
 57: struct DecodedNode {
 58:     bool isLeaf;
 59:     uint voxelType;
 60:     uint color;
 61:     uint lightLevel;
 62:     uint childBaseIndex;
 63:     uint childMask;
 64: };
 65: 
 66: ivec2 nodeIndexToTexel(int nodeIndex, int textureWidth) {
 67:     return ivec2(nodeIndex % textureWidth, nodeIndex / textureWidth);
 68: }
 69: 
 70: DecodedNode decodeNode(usampler2D octreeTex, int nodeIndex, int textureWidth) {
 71:     ivec2 texCoord = nodeIndexToTexel(nodeIndex, textureWidth);
 72:     uvec4 node = texelFetch(octreeTex, texCoord, 0);
 73: 
 74:     DecodedNode decoded;
 75:     decoded.isLeaf = (node.x == 1u);
 76: 
 77:     if (decoded.isLeaf) {
 78:         decoded.voxelType = node.y;
 79:         decoded.color = node.z;
 80:         decoded.lightLevel = node.w;
 81:         decoded.childBaseIndex = 0u;
 82:         decoded.childMask = 0u;
 83:     } else {
 84:         decoded.voxelType = 0u;
 85:         decoded.color = 0u;
 86:         decoded.lightLevel = 0u;
 87:         decoded.childBaseIndex = node.y;
 88:         decoded.childMask = node.z;
 89:     }
 90:     return decoded;
 91: }
 92: 
 93: bool raymarchSVO(
 94:     vec3 ro, vec3 rd,
 95:     int chunk_root_idx,
 96:     float t_entry, float t_exit,
 97:     float world_size,
 98:     out vec4 hitColor, out vec3 hitNormal, out bool isLight, out float hit_t
 99: ) {
100:     float t = t_entry;
101:     vec3 p = ro + t * rd;
102: 
103:     StackFrame stack[9];
104:     int stack_ptr = 0;
105: 
106:     int current_node = chunk_root_idx;
107:     vec3 current_min = vec3(0.0);
108:     vec3 current_max = vec3(world_size);
109: 
110:     int steps = 0;
111:     const int MAX_STEPS = 160;
112: 
113:     while (steps < MAX_STEPS) {
114:         steps++;
115: 
116:         DecodedNode node = decodeNode(uNodeTexture, current_node, 1024);
117: 
118:         if (node.isLeaf) {
119:             if (node.voxelType != 0u) {
120:                 float r = float((node.color >> 16) & 0xFFu) / 255.0;
121:                 float g = float((node.color >> 8) & 0xFFu) / 255.0;
122:                 float b = float(node.color & 0xFFu) / 255.0;
123:                 float light = float(node.lightLevel) / 15.0;
124: 
125:                 hitColor = vec4(r, g, b, light);
126:                 isLight = (node.voxelType == 4u);
127: 
128:                 vec3 hit_p = ro + t * rd;
129:                 vec3 center = (current_min + current_max) * 0.5;
130:                 vec3 size = (current_max - current_min) * 0.5;
131:                 vec3 local_p = (hit_p - center) / size;
132:                 vec3 abs_p = abs(local_p);
133: 
134:                 if (abs_p.x > abs_p.y && abs_p.x > abs_p.z) {
135:                     hitNormal = vec3(sign(local_p.x), 0.0, 0.0);
136:                 } else if (abs_p.y > abs_p.x && abs_p.y > abs_p.z) {
137:                     hitNormal = vec3(0.0, sign(local_p.y), 0.0);
138:                 } else {
139:                     hitNormal = vec3(0.0, 0.0, sign(local_p.z));
140:                 }
141:                 hit_t = t;
142:                 return true;
143:             } else {
144:                 // Empty-space skip: jump straight to this leaf's exit plane.
145:                 vec3 t_max_planes = (vec3(
146:                     rd.x > 0.0 ? current_max.x : current_min.x,
147:                     rd.y > 0.0 ? current_max.y : current_min.y,
148:                     rd.z > 0.0 ? current_max.z : current_min.z
149:                 ) - ro) / rd;
150: 
151:                 float t_exit_box = min(t_max_planes.x, min(t_max_planes.y, t_max_planes.z));
152:                 t = t_exit_box;
153:                 p = ro + t * rd;
154:                 // Snap every tied axis past its exit plane: leaving an axis
155:                 // exactly ON its plane stalls the march (t stops advancing).
156:                 if (abs(t_exit_box - t_max_planes.x) < 0.0001) p.x = (rd.x > 0.0 ? current_max.x : current_min.x) + (rd.x > 0.0 ? 0.001 : -0.001);
157:                 if (abs(t_exit_box - t_max_planes.y) < 0.0001) p.y = (rd.y > 0.0 ? current_max.y : current_min.y) + (rd.y > 0.0 ? 0.001 : -0.001);
158:                 if (abs(t_exit_box - t_max_planes.z) < 0.0001) p.z = (rd.z > 0.0 ? current_max.z : current_min.z) + (rd.z > 0.0 ? 0.001 : -0.001);
159: 
160:                 // Pop EVERY level the ray exited: a skip through a plane
161:                 // shared by several ancestor boxes leaves p outside more
162:                 // than one of them, and descending from a box that no
163:                 // longer contains p corrupts the traversal (wall cracks).
164:                 while (p.x < current_min.x || p.x > current_max.x ||
165:                        p.y < current_min.y || p.y > current_max.y ||
166:                        p.z < current_min.z || p.z > current_max.z) {
167: 
168:                     if (stack_ptr == 0) return false;
169:                     stack_ptr--;
170:                     current_node = stack[stack_ptr].node_idx;
171:                     current_min = stack[stack_ptr].b_min;
172:                     current_max = stack[stack_ptr].b_max;
173:                 }
174:             }
175:         } else {
176:             vec3 center = (current_min + current_max) * 0.5;
177:             int ox = p.x >= center.x ? 1 : 0;
178:             int oy = p.y >= center.y ? 1 : 0;
179:             int oz = p.z >= center.z ? 1 : 0;
180:             int child_idx = (oz << 2) | (oy << 1) | ox;
181: 
182:             if ((node.childMask & (1u << uint(child_idx))) != 0u) {
183:                 // Descend into the occupied octant.
184:                 if (stack_ptr < 8) {
185:                     stack[stack_ptr] = StackFrame(current_node, current_min, current_max);
186:                     stack_ptr++;
187:                 }
188:                 current_min.x = ox == 1 ? center.x : current_min.x;
189:                 current_max.x = ox == 1 ? current_max.x : center.x;
190:                 current_min.y = oy == 1 ? center.y : current_min.y;
191:                 current_max.y = oy == 1 ? current_max.y : center.y;
192:                 current_min.z = oz == 1 ? center.z : current_min.z;
193:                 current_max.z = oz == 1 ? current_max.z : center.z;
194:                 current_node = int(node.childBaseIndex) + child_idx;
195:             } else {
196:                 // Masked-out (air) octant: skip it in one step.
197:                 vec3 oct_max = vec3(
198:                     ox == 1 ? current_max.x : center.x,
199:                     oy == 1 ? current_max.y : center.y,
200:                     oz == 1 ? current_max.z : center.z
201:                 );
202:                 vec3 oct_min = vec3(
203:                     ox == 1 ? center.x : current_min.x,
204:                     oy == 1 ? center.y : current_min.y,
205:                     oz == 1 ? center.z : current_min.z
206:                 );
207:                  vec3 t_max_planes = (vec3(
208:                     rd.x > 0.0 ? oct_max.x : oct_min.x,
209:                     rd.y > 0.0 ? oct_max.y : oct_min.y,
210:                     rd.z > 0.0 ? oct_max.z : oct_min.z
211:                 ) - ro) / rd;
212: 
213:                 float t_exit_oct = min(t_max_planes.x, min(t_max_planes.y, t_max_planes.z));
214:                 t = t_exit_oct;
215:                 p = ro + t * rd;
216:                 if (abs(t_exit_oct - t_max_planes.x) < 0.0001) p.x = (rd.x > 0.0 ? oct_max.x : oct_min.x) + (rd.x > 0.0 ? 0.001 : -0.001);
217:                 if (abs(t_exit_oct - t_max_planes.y) < 0.0001) p.y = (rd.y > 0.0 ? oct_max.y : oct_min.y) + (rd.y > 0.0 ? 0.001 : -0.001);
218:                 if (abs(t_exit_oct - t_max_planes.z) < 0.0001) p.z = (rd.z > 0.0 ? oct_max.z : oct_min.z) + (rd.z > 0.0 ? 0.001 : -0.001);
219: 
220:                 // Same multi-level pop as the empty-leaf skip above.
221:                 while (p.x < current_min.x || p.x > current_max.x ||
222:                        p.y < current_min.y || p.y > current_max.y ||
223:                        p.z < current_min.z || p.z > current_max.z) {
224: 
225:                     if (stack_ptr == 0) return false;
226:                     stack_ptr--;
227:                     current_node = stack[stack_ptr].node_idx;
228:                     current_min = stack[stack_ptr].b_min;
229:                     current_max = stack[stack_ptr].b_max;
230:                 }
231:             }
232:         }
233:     }
234:     return false;
235: }
236: 
237: void main() {
238:     vec2 ndc = vUv * 2.0 - 1.0;
239:     // 0.767 = tan(75deg FOV / 2)
240:     vec3 rd_local = normalize(vec3(ndc.x * uAspect * 0.767, ndc.y * 0.767, -1.0));
241: 
242:     float cp = cos(uPitch);
243:     float sp = sin(uPitch);
244:     vec3 rd_pitched = vec3(
245:         rd_local.x,
246:         rd_local.y * cp - rd_local.z * sp,
247:         rd_local.y * sp + rd_local.z * cp
248:     );
249: 
250:     float cy = cos(uYaw);
251:     float sy = sin(uYaw);
252:     vec3 rd = vec3(
253:         rd_pitched.x * cy + rd_pitched.z * sy,
254:         rd_pitched.y,
255:         -rd_pitched.x * sy + rd_pitched.z * cy
256:     );
257: 
258:     vec3 ro = uCameraPosition;
259: 
260:     ChunkHit hits[25];
261:     int numHits = 0;
262: 
263:     vec3 safe_rd = vec3(
264:         abs(rd.x) < 1e-4 ? sign(rd.x) * 1e-4 : rd.x,
265:         abs(rd.y) < 1e-4 ? sign(rd.y) * 1e-4 : rd.y,
266:         abs(rd.z) < 1e-4 ? sign(rd.z) * 1e-4 : rd.z
267:     );
268:     vec3 invRd = 1.0 / safe_rd;
269: 
270:     // Chunk-level "coarse geometry" pass: slab-test each chunk AABB and
271:     // insertion-sort by entry distance so we march nearest-first.
272:     for (int i = 0; i < uNumChunks; i++) {
273:         vec3 local_ro = ro - uChunkOrigins[i];
274: 
275:         vec3 box_min = vec3(0.0);
276:         vec3 box_max = vec3(uChunkWorldSizes[i]);
277: 
278:         vec3 t1 = (box_min - local_ro) * invRd;
279:         vec3 t2 = (box_max - local_ro) * invRd;
280:         vec3 t_min_p = min(t1, t2);
281:         vec3 t_max_p = max(t1, t2);
282: 
283:         float t_entry = max(t_min_p.x, max(t_min_p.y, t_min_p.z));
284:         float t_exit = min(t_max_p.x, min(t_max_p.y, t_max_p.z));
285: 
286:         if (t_entry < t_exit && t_exit > 0.0) {
287:             float real_entry = max(t_entry, 0.0);
288:             int insert_pos = numHits;
289:             while (insert_pos > 0 && hits[insert_pos - 1].t_min > real_entry) {
290:                 hits[insert_pos] = hits[insert_pos - 1];
291:                 insert_pos--;
292:             }
293:             hits[insert_pos] = ChunkHit(i, real_entry, t_exit);
294:             numHits++;
295:         }
296:     }
297: 
298:     vec4 finalColor = vec4(0.0);
299:     vec3 finalNormal = vec3(0.0);
300:     bool hitSolid = false;
301:     bool hitIsLight = false;
302:     float closest_t = 1e6;
303:     int hit_chunk_idx = -1;
304: 
305:     for (int k = 0; k < numHits; k++) {
306:         int i = hits[k].idx;
307:         vec3 local_ro = ro - uChunkOrigins[i];
308: 
309:         vec4 col;
310:         vec3 norm;
311:         bool isL;
312:         float h_t;
313:         // Literate Documentation:
314:         // Pass safe_rd instead of the raw direction vector rd to prevent division-by-zero and
315:         // resulting NaN states in SVO traversal when the view direction aligns with any coordinate axis.
316:         if (raymarchSVO(local_ro, safe_rd, uChunkRootIndices[i], hits[k].t_min, hits[k].t_max,
317:                         uChunkWorldSizes[i], col, norm, isL, h_t)) {
318:             finalColor = col;
319:             finalNormal = norm;
320:             hitSolid = true;
321:             hitIsLight = isL;
322:             closest_t = h_t;
323:             hit_chunk_idx = i;
324:             break;
325:         }
326:     }
327: 
328:     if (hitSolid) {
329:         vec3 albedo = hitIsLight ? vec3(1.0) : finalColor.rgb;
330:         float staticLight = finalColor.a;
331:         
332:         vec3 N = finalNormal;
333:         vec3 V = -rd; // View direction pointing back to camera
334:         
335:         // Emissive light source: render as constant white
336:         if (hitIsLight) {
337:             fragColor = vec4(vec3(1.5), 1.0);
338:             return;
339:         }
340:         
341:         // 1. Natural Ambient & Better Shadows
342:         float voxel_scale = uChunkWorldSizes[hit_chunk_idx] > 20.0 ? 0.1 : 0.2;
343:         vec3 local_hit_p = (ro - uChunkOrigins[hit_chunk_idx]) + closest_t * rd;
344:         
345:         float distToFloor = local_hit_p.y - voxel_scale;
346:         float distToCeiling = (3.0 - voxel_scale) - local_hit_p.y;
347:         
348:         // Soft contact shadow AO in corners where walls meet floor/ceiling
349:         float edgeAO = 1.0;
350:         if (abs(N.y) < 0.5) { // Only apply to vertical walls
351:             edgeAO = smoothstep(0.0, 0.4, distToFloor) * smoothstep(0.0, 0.4, distToCeiling);
352:             edgeAO = mix(0.55, 1.0, edgeAO);
353:         }
354:         
355:         // Brighter and warmer ambient colors for a natural Backrooms look
356:         vec3 groundColor = vec3(0.24, 0.21, 0.16);
357:         vec3 skyColor = vec3(0.52, 0.48, 0.40);
358:         vec3 ambient = mix(groundColor, skyColor, N.y * 0.5 + 0.5) * (0.45 + 0.55 * staticLight) * edgeAO;
359:         
360:         // 2. Static Room/Ceiling Lights
361:         vec3 staticL = vec3(0.0, 1.0, 0.0); // Directional light from ceiling pointing down
362:         float staticDiffuse = max(dot(N, staticL), 0.0) * staticLight * 0.8;
363:         vec3 staticDiffuseContrib = staticDiffuse * albedo * vec3(1.0, 0.98, 0.90);
364:         
365:         // Specular reflections - active on walls and ceiling, but disabled on carpet floor
366:         float specularMask = 1.0 - smoothstep(0.3, 0.7, N.y);
367:         vec3 staticH = normalize(staticL + V);
368:         float staticSpecular = pow(max(dot(N, staticH), 0.0), 24.0) * staticLight * 0.18 * specularMask;
369:         vec3 staticSpecularContrib = staticSpecular * vec3(1.0, 0.98, 0.90);
370:         
371:         vec3 staticContrib = (staticDiffuseContrib + staticSpecularContrib) * edgeAO;
372:         
373:         // Total Lighting (No Flashlight)
374:         vec3 litColor = albedo * ambient + staticContrib;
375:         
376:         // 3. Fog and Vignette
377:         float dist = closest_t;
378:         float fogFactor = exp(-0.02 * dist);
379:         
380:         float vignette = vUv.x * vUv.y * (1.0 - vUv.x) * (1.0 - vUv.y);
381:         vignette = clamp(pow(16.0 * vignette, 0.25), 0.0, 1.0);
382:         
383:         fragColor = vec4(mix(vec3(0.0), litColor, fogFactor * vignette), 1.0);
384:     } else {
385:         fragColor = vec4(0.0, 0.0, 0.0, 1.0);
386:     }
387: }
388: "#;

