 22: use crate::adapters::local_chunk_source::LocalChunkSource;
 23: use crate::adapters::query_config::parse_generation_params;
 24: use crate::application::engine::{Engine, EngineConfig};
 25: use crate::application::ports::{ChunkDraw, FrameParams, RendererPort};
 26: use crate::drivers::console_telemetry::CONSOLE_TELEMETRY;
 27: use crate::drivers::cpu_canvas::CpuCanvasRenderer;
 28: use crate::drivers::webgl::WebGl2Renderer;
 29: 
 30: /// World seed shared with the native server so both render the same world.
 31: const WORLD_SEED: u32 = 42;
 32: /// HUD refresh cadence in frames.
 33: const HUD_INTERVAL: u32 = 30;
 34: /// Minimap pixels per world unit.
 35: const MINIMAP_SCALE: f64 = 12.0;
 36: 
 37: /// The two available renderer back ends. GPU raymarching is the default;
 38: /// the CPU microvoxel splatter is selected by `?renderer=cpu` or used as an
 39: /// automatic fallback when WebGL2 is unavailable.
 40: enum DriverRenderer {
 41:     Gpu(WebGl2Renderer),
 42:     Cpu(CpuCanvasRenderer),
 43: }
 44: 
 45: impl DriverRenderer {
 46:     fn resize(&mut self, width: u32, height: u32) {
 47:         match self {
 48:             DriverRenderer::Gpu(r) => r.resize(width, height),
 49:             DriverRenderer::Cpu(r) => r.resize(width, height),
 50:         }
 51:     }
 52: 
 53:     /// Base internal-resolution multiplier (further scaled by the adaptive
 54:     /// governor). Splatting every pixel on the CPU is far more expensive
 55:     /// than rasterizing a quad, so the CPU path renders much smaller and
 56:     /// lets CSS upscale with `image-rendering: pixelated`.
 57:     fn resolution_factor(&self) -> f64 {
 58:         match self {
 59:             DriverRenderer::Gpu(_) => 1.0,
 60:             DriverRenderer::Cpu(_) => 0.25,
 61:         }
 62:     }
 63: 
 64:     fn label(&self) -> &'static str {
 65:         match self {
 66:             DriverRenderer::Gpu(_) => "GPU raymarch",
 67:             DriverRenderer::Cpu(_) => "CPU splat",
 68:         }
 69:     }
 70: }
 71: 
 72: impl RendererPort for DriverRenderer {
 73:     fn upload_atlas(&mut self, texels: &[u32]) {
 74:         match self {
 75:             DriverRenderer::Gpu(r) => r.upload_atlas(texels),
 76:             DriverRenderer::Cpu(r) => r.upload_atlas(texels),
 77:         }
 78:     }
 79:     fn draw(&mut self, frame: &FrameParams, chunks: &[ChunkDraw]) {
 80:         match self {
 81:             DriverRenderer::Gpu(r) => r.draw(frame, chunks),
 82:             DriverRenderer::Cpu(r) => r.draw(frame, chunks),
 83:         }
 84:     }
 85: }
 86: 
 87: /// Engine owns its renderer behind the port; the driver also needs to call
 88: /// `resize` on the concrete type. This thin adapter shares one renderer
 89: /// between both without widening the port.
 90: struct SharedRenderer(Rc<RefCell<DriverRenderer>>);
 91: 
 92: impl RendererPort for SharedRenderer {
 93:     fn upload_atlas(&mut self, texels: &[u32]) {
 94:         self.0.borrow_mut().upload_atlas(texels);
 95:     }
 96:     fn draw(&mut self, frame: &FrameParams, chunks: &[ChunkDraw]) {
 97:         self.0.borrow_mut().draw(frame, chunks);
 98:     }
 99: }
100: 
101: /// Renderer selection: explicit `?renderer=cpu`, otherwise WebGL2 with a
102: /// logged fallback to the CPU splatter if context creation fails.
103: fn create_renderer(canvas: &HtmlCanvasElement, query: &str) -> Result<DriverRenderer, JsValue> {
104:     if query.contains("renderer=cpu") {
105:         return Ok(DriverRenderer::Cpu(CpuCanvasRenderer::new(canvas)?));
106:     }
107:     match WebGl2Renderer::new(canvas) {
108:         Ok(gpu) => Ok(DriverRenderer::Gpu(gpu)),
109:         Err(err) => {
110:             web_sys::console::warn_2(
111:                 &JsValue::from_str("WebGL2 unavailable, falling back to CPU splatting:"),
112:                 &err,
113:             );
114:             Ok(DriverRenderer::Cpu(CpuCanvasRenderer::new(canvas)?))
115:         }
116:     }
117: }
118: 
119: pub fn boot() -> Result<(), JsValue> {
120:     let window = web_sys::window().ok_or_else(|| JsValue::from_str("no window"))?;
121:     let document = window.document().ok_or_else(|| JsValue::from_str("no document"))?;
122: 
123:     let canvas: HtmlCanvasElement = element(&document, "view")?;
124:     let minimap: HtmlCanvasElement = element(&document, "minimap")?;
125:     let overlay: HtmlElement = element(&document, "overlay")?;
126:     let status_msg: HtmlElement = element(&document, "status-msg")?;
127:     let play_msg: HtmlElement = element(&document, "play-msg")?;
128: 
129:     // ?spec=high -> 20u chunks, 5x5 streaming radius, 0.1u voxels.
130:     // Default is the low-spec profile: 10u chunks, 3x3 radius, 0.2u voxels.
131:     // Generation controls: ?seed=… (number or any text) plus the density
132:     // knobs ?pillars= ?walls= ?atria= ?lights= (multipliers, default 1).
133:     let query = window.location().search().unwrap_or_default();
134:     let gen_params = parse_generation_params(&query, WORLD_SEED);
135:     let high_spec = query.contains("spec=high");
136:     let (generator_config, engine_config) = if high_spec {
137:         (
138:             GeneratorConfig::high_spec().with_tuning(gen_params.tuning),
139:             EngineConfig {
140:                 chunk_size: 20.0,
141:                 chunk_radius: 2,
142:                 seed: gen_params.seed,
143:                 ..EngineConfig::default()
144:             },
145:         )
146:     } else {
147:         (
148:             GeneratorConfig::low_spec().with_tuning(gen_params.tuning),
149:             EngineConfig { seed: gen_params.seed, ..EngineConfig::default() },
150:         )
151:     };
152: 
153:     let renderer = Rc::new(RefCell::new(create_renderer(&canvas, &query)?));
154:     if let Ok(hud_renderer) = element::<HtmlElement>(&document, "hud-renderer") {
155:         hud_renderer.set_text_content(Some(renderer.borrow().label()));
156:     }
157:     let source = LocalChunkSource::with_telemetry(
158:         SimpleNoiseProvider::new(),
159:         gen_params.seed,
160:         generator_config,
161:         &CONSOLE_TELEMETRY,
162:     );
163:     let engine = Rc::new(RefCell::new(Engine::new(
164:         engine_config,
165:         Box::new(SharedRenderer(renderer.clone())),
166:         Box::new(source),
167:     )));
168:     let input = Rc::new(RefCell::new(InputCollector::new()));
169: 
170:     attach_input_listeners(&document, &canvas, &overlay, &input)?;
171:     run_frame_loop(
172:         window, document, canvas, minimap, overlay, status_msg, play_msg, renderer, engine, input,
173:     )
174: }
175: 
176: fn element<T: JsCast>(document: &Document, id: &str) -> Result<T, JsValue> {
177:     document
178:         .get_element_by_id(id)
179:         .ok_or_else(|| JsValue::from_str(&format!("missing #{id} element")))?
180:         .dyn_into::<T>()
181:         .map_err(|_| JsValue::from_str(&format!("#{id} has unexpected element type")))
182: }
183: 
184: fn attach_input_listeners(
185:     document: &Document,
186:     canvas: &HtmlCanvasElement,
187:     overlay: &HtmlElement,
188:     input: &Rc<RefCell<InputCollector>>,
189: ) -> Result<(), JsValue> {
190:     // Keyboard: KeyboardEvent.code -> MoveIntent, mapped by the input adapter.
191:     for (event, pressed) in [("keydown", true), ("keyup", false)] {
192:         let input = input.clone();
193:         let closure = Closure::<dyn FnMut(KeyboardEvent)>::new(move |e: KeyboardEvent| {
194:             if !e.repeat() {
195:                 input.borrow_mut().key_event(&e.code(), pressed);
196:             }
197:         });
198:         document.add_event_listener_with_callback(event, closure.as_ref().unchecked_ref())?;
199:         closure.forget();
200:     }
201: 
202:     // Mouse look (deltas are ignored by the adapter unless pointer-locked).
203:     {
204:         let input = input.clone();
205:         let closure = Closure::<dyn FnMut(MouseEvent)>::new(move |e: MouseEvent| {
206:             input
207:                 .borrow_mut()
208:                 .mouse_delta(e.movement_x() as f32, e.movement_y() as f32);
209:         });
210:         document.add_event_listener_with_callback("mousemove", closure.as_ref().unchecked_ref())?;
211:         closure.forget();
212:     }
213: 
214:     // Click-to-play: the overlay requests pointer lock on the render canvas.
215:     {
216:         let canvas = canvas.clone();
217:         let closure = Closure::<dyn FnMut()>::new(move || {
218:             canvas.request_pointer_lock();
219:         });
220:         overlay.add_event_listener_with_callback("click", closure.as_ref().unchecked_ref())?;
221:         closure.forget();
222:     }
223: 
224:     // Pointer-lock state drives both the input adapter and overlay visibility.
225:     {
226:         let input = input.clone();
227:         let doc_for_closure = document.clone();
228:         let overlay = overlay.clone();
229:         let closure = Closure::<dyn FnMut()>::new(move || {
230:             let locked = doc_for_closure.pointer_lock_element().is_some();
231:             input.borrow_mut().set_locked(locked);
232:             let _ = overlay
233:                 .style()
234:                 .set_property("display", if locked { "none" } else { "flex" });
235:         });
236:         document
237:             .add_event_listener_with_callback("pointerlockchange", closure.as_ref().unchecked_ref())?;
238:         closure.forget();
239:     }
240: 
241:     Ok(())
242: }
243: 
244: #[allow(clippy::too_many_arguments)]
245: fn run_frame_loop(
246:     window: Window,
247:     _document: Document,
248:     canvas: HtmlCanvasElement,
249:     minimap: HtmlCanvasElement,
250:     _overlay: HtmlElement,
251:     status_msg: HtmlElement,
252:     play_msg: HtmlElement,
253:     renderer: Rc<RefCell<DriverRenderer>>,
254:     engine: Rc<RefCell<Engine>>,
255:     input: Rc<RefCell<InputCollector>>,
256: ) -> Result<(), JsValue> {
257:     let minimap_ctx: CanvasRenderingContext2d = minimap
258:         .get_context("2d")?
259:         .ok_or_else(|| JsValue::from_str("no 2d context for minimap"))?
260:         .dyn_into()?;
261: 
262:     let hud_fps: HtmlElement = element(window.document().as_ref().unwrap(), "hud-fps")?;
263:     let hud_chunks: HtmlElement = element(window.document().as_ref().unwrap(), "hud-chunks")?;
264:     let hud_nodes: HtmlElement = element(window.document().as_ref().unwrap(), "hud-nodes")?;
265:     let hud_scale: HtmlElement = element(window.document().as_ref().unwrap(), "hud-scale")?;
266: 
267:     let last_time = Rc::new(Cell::new(0.0f64));
268:     let frame_count = Rc::new(Cell::new(0u32));
269:     let hud_window_start = Rc::new(Cell::new(0.0f64));
270:     let was_ready = Rc::new(Cell::new(false));
271: 
272:     // Standard self-referential rAF closure pattern.
273:     let raf_handle: Rc<RefCell<Option<Closure<dyn FnMut(f64)>>>> = Rc::new(RefCell::new(None));
274:     let raf_handle_clone = raf_handle.clone();
275: 
276:     let loop_window = window.clone();
277:     *raf_handle.borrow_mut() = Some(Closure::new(move |time_ms: f64| {
278:         let dt = if last_time.get() > 0.0 {
279:             ((time_ms - last_time.get()) / 1000.0) as f32
280:         } else {
281:             1.0 / 60.0
282:         };
283:         last_time.set(time_ms);
284: 
285:         // Adaptive resolution: size the backing store to
286:         // window * governor scale * renderer base factor.
287:         {
288:             let scale = engine.borrow().stats().resolution_scale as f64
289:                 * renderer.borrow().resolution_factor();
290:             let target_w = (loop_window.inner_width().ok().and_then(|v| v.as_f64()).unwrap_or(800.0)
291:                 * scale)
292:                 .max(1.0) as u32;
293:             let target_h = (loop_window.inner_height().ok().and_then(|v| v.as_f64()).unwrap_or(600.0)
294:                 * scale)
295:                 .max(1.0) as u32;
296:             if canvas.width() != target_w || canvas.height() != target_h {
297:                 canvas.set_width(target_w);
298:                 canvas.set_height(target_h);
299:                 renderer.borrow_mut().resize(target_w, target_h);
300:             }
301:         }
302: 
303:         let frame_input = input.borrow_mut().take_frame();
304:         engine.borrow_mut().tick(dt, &frame_input);
305: 
306:         // Loading overlay: flip to "click to play" once the spawn chunk is in.
307:         let stats = engine.borrow().stats();
308:         if stats.ready && !was_ready.get() {
309:             was_ready.set(true);
310:             let _ = status_msg.style().set_property("display", "none");
311:             let _ = play_msg.style().set_property("display", "block");
312:         }
313: 
314:         draw_minimap(&minimap_ctx, &minimap, &engine.borrow());
315: 
316:         // HUD refresh at a fixed frame cadence.
317:         frame_count.set(frame_count.get() + 1);
318:         if frame_count.get() % HUD_INTERVAL == 0 {
319:             let elapsed = (time_ms - hud_window_start.get()) / 1000.0;
320:             if elapsed > 0.0 {
321:                 let fps = (HUD_INTERVAL as f64 / elapsed).round();
322:                 hud_fps.set_text_content(Some(&fps.to_string()));
323:             }
324:             hud_window_start.set(time_ms);
325:             hud_chunks.set_text_content(Some(&stats.resident_chunks.to_string()));
326:             hud_nodes.set_text_content(Some(&stats.atlas_nodes.to_string()));
327:             hud_scale.set_text_content(Some(&format!("{:.0}%", stats.resolution_scale * 100.0)));
328:         }
329: 
330:         // Schedule next frame.
331:         if let Some(closure) = raf_handle_clone.borrow().as_ref() {
332:             let _ = loop_window.request_animation_frame(closure.as_ref().unchecked_ref());
333:         }
334:     }));
335: 
336:     if let Some(closure) = raf_handle.borrow().as_ref() {
337:         window.request_animation_frame(closure.as_ref().unchecked_ref())?;
338:     }
339:     // Keep the closure (and everything it captures) alive forever.
340:     std::mem::forget(raf_handle);
341:     Ok(())
342: }
343: 
344: /// Top-down radar: solid collision boxes around the player, plus a player
345: /// dot and view direction line. Pure presentation — reads engine state only.
346: fn draw_minimap(ctx: &CanvasRenderingContext2d, canvas: &HtmlCanvasElement, engine: &Engine) {
347:     let w = canvas.width() as f64;
348:     let h = canvas.height() as f64;
349:     let cx = w / 2.0;
350:     let cy = h / 2.0;
351:     let player = engine.player();
352: 
353:     ctx.clear_rect(0.0, 0.0, w, h);
354:     ctx.set_fill_style_str("rgba(0, 0, 0, 0.5)");
355:     ctx.fill_rect(0.0, 0.0, w, h);
356: 
357:     ctx.set_fill_style_str("#ff5555");
358:     let range = (w / 2.0) / MINIMAP_SCALE + 1.0;
359:     for b in engine.collision_world().boxes() {
360:         let rel_x = (b.min[0] - player.position[0]) as f64;
361:         let rel_z = (b.min[2] - player.position[2]) as f64;
362:         if rel_x.abs() > range || rel_z.abs() > range {
363:             continue;
364:         }
365:         let size_x = (b.max[0] - b.min[0]) as f64 * MINIMAP_SCALE;
366:         let size_z = (b.max[2] - b.min[2]) as f64 * MINIMAP_SCALE;
367:         ctx.fill_rect(
368:             cx + rel_x * MINIMAP_SCALE,
369:             cy + rel_z * MINIMAP_SCALE,
370:             size_x.max(1.0),
371:             size_z.max(1.0),
372:         );
373:     }
374: 
375:     // Player dot.
376:     ctx.set_fill_style_str("#00ff00");
377:     ctx.begin_path();
378:     let _ = ctx.arc(cx, cy, 4.0, 0.0, std::f64::consts::TAU);
379:     ctx.fill();
380: 
381:     // View direction.
382:     ctx.set_stroke_style_str("#00ff00");
383:     ctx.set_line_width(2.0);
384:     ctx.begin_path();
385:     ctx.move_to(cx, cy);
386:     let yaw = player.yaw as f64;
387:     ctx.line_to(cx + yaw.sin() * -14.0, cy + yaw.cos() * -14.0);
388:     ctx.stroke();
389: }

