  1: //! Level 0 — the Backrooms proper.
  2: //!
  3: //! Everything is a pure function of *world-space* coordinates, so chunks tile
  4: //! seamlessly no matter which order they stream in. The goal is *believable
  5: //! building architecture* with depth — not flat mazes:
  6: //!
  7: //! * **Zones** (~25 u blobs of smooth noise) pick the local architecture:
  8: //!   - high zone → *atrium*: the ceiling vaults **continuously** from office
  9: //!     height up to ~5.4 u (a dome-like swell, not a step), ringed by a
 10: //!     colonnade of floor-to-vault pillars with glowing sconce bands at
 11: //!     human height — the "architectural marvel" moments.
 12: //!   - low zone  → *expanse*: wide open halls of sparse structural columns.
 13: //!   - middle    → *offices*: yellow wall grid with real **doorways** —
 14: //!     door-height openings under solid lintels, hashed per cell so no two
 15: //!     rooms line up — and **coffered ceilings** (a beam grid overhead).
 16: //! * **Halls**: two perpendicular corridor families on a 12 u period whose
 17: //!   centerlines *wander* (±2 u of low-frequency noise) and whose width
 18: //!   breathes between ~1.9 u and ~3.2 u. Halls carve through walls, run
 19: //!   under lowered soffit ceilings with light strips, and grow flanking
 20: //!   colonnades where they cross atria.
 21: //! * **Walkability is structural**: the hall network alone connects the
 22: //!   world; walls always carry a doorway per 7 u cell; pillars are point
 23: //!   obstacles. A BFS test enforces >95% connectivity.
 24: 
 25: use crate::domain::entities::voxel_grid::{
 26:     VoxelGrid, VOXEL_CEILING, VOXEL_FLOOR, VOXEL_LIGHT, VOXEL_RED_WALL, VOXEL_WALL,
 27: };
 28: use crate::entities::models::Position;
 29: use crate::use_cases::generate_chunk::{GeneratorConfig, LevelTuning};
 30: use crate::use_cases::level_generator::LevelGenerator;
 31: use crate::use_cases::ports::NoiseProvider;
 32: 
 33: /// Ceiling height of the tallest (atrium) vaults, world units.
 34: pub const MAX_CEILING_UNITS: f32 = 5.4;
 35: /// Total grid height: headroom above the tallest vault.
 36: pub const GRID_HEIGHT_UNITS: f32 = 5.8;
 37: 
 38: /// Corridor spacing / wander / width, world units.
 39: const HALL_PERIOD: f32 = 12.0;
 40: const HALL_WANDER: f32 = 2.0;
 41: const HALL_WIDTH_BASE: f32 = 2.55;
 42: const HALL_WIDTH_VAR: f32 = 0.65;
 43: /// Hall ceilings drop to this soffit height outside atria.
 44: const HALL_SOFFIT_UNITS: f32 = 2.9;
 45: 
 46: /// Office wall grid: cell size, doorway width and door (lintel) height.
 47: /// 3.0 units creates tight 2–3 m corridors matching authentic Level 0.
 48: const WALL_PERIOD: f32 = 3.0;
 49: const DOOR_WIDTH: f32 = 1.2;
 50: const DOOR_HEIGHT: f32 = 2.2;
 51: 
 52: /// Coffered-ceiling beam grid period and beam drop, world units.
 53: const COFFER_PERIOD: f32 = 2.8;
 54: const COFFER_DROP: f32 = 0.2;
 55: 
 56: /// Ceiling light panel spacing (aligned to coffer panel centers).
 57: const LIGHT_PERIOD: f32 = 2.8;
 58: 
 59: /// Sconce band height on atrium pillars.
 60: const SCONCE_UNITS: f32 = 2.4;
 61: 
 62: /// Keep a clearing around the world spawn point.
 63: const SPAWN: (f32, f32) = (5.0, 5.0);
 64: const SPAWN_CLEAR_RADIUS: f32 = 2.5;
 65: 
 66: pub struct BackroomsLevel;
 67: 
 68: /// What one (x, z) column of the level looks like.
 69: #[derive(Debug, Clone, Copy, PartialEq)]
 70: pub(crate) struct ColumnPlan {
 71:     /// Floor-to-ceiling solid (wall or pillar).
 72:     pub solid: bool,
 73:     /// Red accent variant of a solid column.
 74:     pub red: bool,
 75:     /// Ceiling height in world units (top of the walkable space).
 76:     pub ceiling_units: f32,
 77:     /// Ceiling light above this column.
 78:     pub light: bool,
 79:     /// Solid band hanging from the ceiling down to this height (door
 80:     /// lintels). The space below stays walkable.
 81:     pub lintel_from_units: Option<f32>,
 82:     /// Glowing sconce band on a solid column (atrium pillars).
 83:     pub sconce: bool,
 84: }
 85: 
 86: impl BackroomsLevel {
 87:     /// Smooth world-space noise in [-1, 1]. `scale` stretches the provider's
 88:     /// built-in ~20 u wavelength: wavelength = 20 / scale.
 89:     fn n(noise: &dyn NoiseProvider, seed: u32, salt: u32, x: f32, z: f32, scale: f32) -> f32 {
 90:         noise.evaluate_2d(seed ^ salt, Position::new(x * scale, z * scale))
 91:     }
 92: 
 93:     /// Decorrelated per-cell hash in [0, 1): samples the value noise exactly
 94:     /// on its lattice (provider frequency is 0.05, so inputs that are
 95:     /// multiples of 20 hit lattice points), where it is uniform rather than
 96:     /// interpolation-smoothed toward zero.
 97:     fn cell_hash(noise: &dyn NoiseProvider, seed: u32, salt: u32, cx: i64, cz: i64) -> f32 {
 98:         let v = noise.evaluate_2d(
 99:             seed ^ salt,
100:             Position::new(cx as f32 * 20.0, cz as f32 * 20.0),
101:         );
102:         (v * 0.5 + 0.5).clamp(0.0, 0.999)
103:     }
104: 
105:     fn smoothstep(t: f32) -> f32 {
106:         let t = t.clamp(0.0, 1.0);
107:         t * t * (3.0 - 2.0 * t)
108:     }
109: 
110:     /// Distance from `w` to the wandering centerline of corridor family
111:     /// `salt` at position `along` on the perpendicular axis.
112:     /// Returns (signed offset from center, half_width).
113:     fn hall_offset(
114:         noise: &dyn NoiseProvider,
115:         seed: u32,
116:         salt: u32,
117:         w: f32,
118:         along: f32,
119:     ) -> (f32, f32) {
120:         let k = ((w - HALL_PERIOD * 0.5) / HALL_PERIOD).round();
121:         let nominal = k * HALL_PERIOD + HALL_PERIOD * 0.5;
122:         let center =
123:             nominal + HALL_WANDER * Self::n(noise, seed, salt, along, k * 37.7, 0.45);
124:         let half_width = (HALL_WIDTH_BASE
125:             + HALL_WIDTH_VAR * Self::n(noise, seed, salt ^ 0x5A5A, along, k * 19.3, 0.8))
126:             * 0.5;
127:         (w - center, half_width)
128:     }
129: 
130:     /// Should a pillar site survive? Applies the user pillar-density knob
131:     /// plus a per-site hash so even default density feels irregular.
132:     fn pillar_alive(
133:         noise: &dyn NoiseProvider,
134:         seed: u32,
135:         tuning: &LevelTuning,
136:         wx: f32,
137:         wz: f32,
138:         period: f32,
139:     ) -> bool {
140:         let cx = (wx / period).floor() as i64;
141:         let cz = (wz / period).floor() as i64;
142:         Self::cell_hash(noise, seed, 0xF200, cx, cz) < 0.7 * tuning.pillars
143:     }
144: 
145:     /// The full column plan at world position (wx, wz), world units.
146:     pub(crate) fn column_plan(
147:         noise: &dyn NoiseProvider,
148:         seed: u32,
149:         tuning: &LevelTuning,
150:         wx: f32,
151:         wz: f32,
152:     ) -> ColumnPlan {
153:         // ---- ceiling field (flat and low everywhere like authentic Level 0) ----
154:         let coarse = Self::n(noise, seed, 0xB200, wx, wz, 0.55);
155:         let fine = Self::n(noise, seed, 0xB300, wx, wz, 1.6);
156:         let mut ceiling_units = (2.8 + 0.15 * coarse + 0.05 * fine).clamp(2.7, 3.0);
157:         
158:         // Coffered ceiling grid
159:         let on_beam = wx.rem_euclid(COFFER_PERIOD) < 0.22
160:             || wz.rem_euclid(COFFER_PERIOD) < 0.22;
161:         if on_beam {
162:             ceiling_units -= COFFER_DROP;
163:         }
164: 
165:         // ---- solids ------------------------------------------------------
166:         let spawn_d2 =
167:             (wx - SPAWN.0) * (wx - SPAWN.0) + (wz - SPAWN.1) * (wz - SPAWN.1);
168:         let in_spawn = spawn_d2 < SPAWN_CLEAR_RADIUS * SPAWN_CLEAR_RADIUS;
169: 
170:         let mut solid = false;
171:         let mut lintel_from_units: Option<f32> = None;
172:         let mut sconce = false;
173: 
174:         if !in_spawn {
175:             let fx = wx.rem_euclid(WALL_PERIOD);
176:             let fz = wz.rem_euclid(WALL_PERIOD);
177:             let cell_x = (wx / WALL_PERIOD).floor() as i64;
178:             let cell_z = (wz / WALL_PERIOD).floor() as i64;
179: 
180:             // (solid, lintel) contribution of one wall family.
181:             //
182:             // Directional noise strategy (Pattern: Strategy):
183:             // A Z-wall runs along the Z axis. To make it run *long*,
184:             // we sample noise with SLOW variation along Z (scale 0.25)
185:             // and FAST variation along X (scale 1.0). This means
186:             // adjacent cells along the wall share similar noise values
187:             // (wall stays solid for many cells), while different grid
188:             // lines (perpendicular) get independent values (some lines
189:             // have walls, some don't). The result: long, straight wall
190:             // runs forming tight corridors — exactly like Level 0.
191:             let wall_here = |f_wall: f32, f_along: f32, is_z_wall: bool| {
192:                 if f_wall >= 0.25 {
193:                     return (false, false);
194:                 }
195:                 
196:                 let (cx, cz) = if is_z_wall {
197:                     (cell_x - 1, cell_z)
198:                 } else {
199:                     (cell_x, cell_z - 1)
200:                 };
201: 
202:                 // World-space midpoint of this wall segment
203:                 let (wx_mid, wz_mid) = if is_z_wall {
204:                     (cx as f32 * WALL_PERIOD, (cz as f32 + 0.5) * WALL_PERIOD)
205:                 } else {
206:                     ((cx as f32 + 0.5) * WALL_PERIOD, cz as f32 * WALL_PERIOD)
207:                 };
208: 
209:                 // Directional noise (Pattern: Strategy):
210:                 // A single directional noise sample with slow variation
211:                 // along the wall axis creates long wall runs (5-10 cells).
212:                 //
213:                 // Threshold formula: 1.0 - walls.clamp(0, 2)
214:                 // Maps directly into the noise output range [-1, 1]:
215:                 //   walls=0.0 → threshold=1.0  → 0% kept (empty)
216:                 //   walls=0.3 → threshold=0.7  → ~15% kept (sparse)
217:                 //   walls=1.0 → threshold=0.0  → ~50% kept (default)
218:                 //   walls=2.0 → threshold=-1.0 → ~100% kept (dense)
219:                 let threshold = 1.0 - tuning.walls.clamp(0.0, 2.0);
220:                 let keep = if is_z_wall {
221:                     let n_val = Self::n(noise, seed, 0xD500, wx_mid, wz_mid * 0.5, 1.0);
222:                     n_val > threshold
223:                 } else {
224:                     let n_val = Self::n(noise, seed, 0xD600, wx_mid * 0.5, wz_mid, 1.0);
225:                     n_val > threshold
226:                 };
227: 
228:                 if !keep {
229:                     return (false, false);
230:                 }
231: 
232:                 // Doorways: 40% of kept walls get a door opening.
233:                 // This creates the authentic Level 0 feel: dense walls
234:                 // with occasional doorway passages between rooms.
235:                 let door_salt = if is_z_wall { 0xD700 } else { 0xD800 };
236:                 let door_hash = Self::cell_hash(noise, seed, door_salt, cx, cz);
237:                 if door_hash < 0.40 {
238:                     let door_pos = (WALL_PERIOD - DOOR_WIDTH) * 0.5;
239:                     if f_along >= door_pos && f_along < door_pos + DOOR_WIDTH {
240:                         return (false, true); // Doorway: open below, lintel above
241:                     }
242:                 }
243:                 (true, false) // Solid wall
244:             };
245: 
246:             let (sx, lx) = wall_here(fx, fz, true);
247:             let (sz, lz) = wall_here(fz, fx, false);
248:             solid = sx || sz;
249:             if !solid && (lx || lz) {
250:                 lintel_from_units = Some(DOOR_HEIGHT);
251:             }
252:         }
253: 
254:         // ---- lights ------------------------------------------------------
255:         let light = if !solid {
256:             // Room panels centered in the coffer bays.
257:             let lx = (wx - LIGHT_PERIOD * 0.5).rem_euclid(LIGHT_PERIOD);
258:             let lz = (wz - LIGHT_PERIOD * 0.5).rem_euclid(LIGHT_PERIOD);
259:             let cell_x = (wx / LIGHT_PERIOD).floor() as i64;
260:             let cell_z = (wz / LIGHT_PERIOD).floor() as i64;
261:             let keep = 0.78 * tuning.lights;
262:             let alive = Self::cell_hash(noise, seed, 0xE900, cell_x, cell_z) < keep;
263:             (lx < 0.45 && lz < 0.45 && alive) || spawn_d2 < 0.36
264:         } else {
265:             false
266:         };
267: 
268:         let red = solid
269:             && Self::cell_hash(noise, seed, 0xF100, (wx / 1.4) as i64, (wz / 1.4) as i64)
270:                 > 0.94;
271: 
272:         ColumnPlan { solid, red, ceiling_units, light, lintel_from_units, sconce }
273:     }
274: }
