276: impl LevelGenerator for BackroomsLevel {
277:     fn generate(
278:         &self,
279:         chunk_pos: Position,
280:         seed: u32,
281:         config: GeneratorConfig,
282:         noise: &dyn NoiseProvider,
283:     ) -> VoxelGrid {
284:         let s = config.voxel_scale;
285:         let width = (config.chunk_size / s) as usize;
286:         let depth = (config.chunk_size / s) as usize;
287:         let height = (GRID_HEIGHT_UNITS / s) as usize;
288:         let mut grid = VoxelGrid::new(width, height, depth);
289: 
290:         // Plan every column plus a 1-voxel margin: ceiling skirts must seal
291:         // height steps across chunk borders too.
292:         let tuning = config.tuning;
293:         let plan_at = |lx: i64, lz: i64| -> ColumnPlan {
294:             let wx = chunk_pos.x + (lx as f32 + 0.5) * s;
295:             let wz = chunk_pos.z + (lz as f32 + 0.5) * s;
296:             BackroomsLevel::column_plan(noise, seed, &tuning, wx, wz)
297:         };
298: 
299:         let mut plans = Vec::with_capacity((width + 2) * (depth + 2));
300:         for lz in -1..=(depth as i64) {
301:             for lx in -1..=(width as i64) {
302:                 plans.push(plan_at(lx, lz));
303:             }
304:         }
305:         let plan = |lx: i64, lz: i64| -> &ColumnPlan {
306:             &plans[((lz + 1) as usize) * (width + 2) + (lx + 1) as usize]
307:         };
308: 
309:         let max_y = height - 1;
310:         let to_vox = |units: f32| ((units / s) as usize).clamp(2, max_y);
311: 
312:         for z in 0..depth {
313:             for x in 0..width {
314:                 let p = *plan(x as i64, z as i64);
315:                 let ch = to_vox(p.ceiling_units);
316: 
317:                 grid.set(x, 0, z, VOXEL_FLOOR);
318: 
319:                 if p.solid {
320:                     let mat = if p.red { VOXEL_RED_WALL } else { VOXEL_WALL };
321:                     for y in 1..ch {
322:                         grid.set(x, y, z, mat);
323:                     }
324:                     if p.sconce {
325:                         let sy = to_vox(SCONCE_UNITS).min(ch - 1);
326:                         grid.set(x, sy, z, VOXEL_LIGHT);
327:                     }
328:                 } else if let Some(from) = p.lintel_from_units {
329:                     // Door lintel: solid from door height to the ceiling.
330:                     for y in to_vox(from)..ch {
331:                         grid.set(x, y, z, VOXEL_WALL);
332:                     }
333:                 }
334: 
335:                 // Ceiling plus a skirt down to the tallest neighbor, so a
336:                 // higher neighboring ceiling can never see over this one.
337:                 let neighbor_max = [
338:                     plan(x as i64 - 1, z as i64),
339:                     plan(x as i64 + 1, z as i64),
340:                     plan(x as i64, z as i64 - 1),
341:                     plan(x as i64, z as i64 + 1),
342:                 ]
343:                 .iter()
344:                 .map(|n| to_vox(n.ceiling_units))
345:                 .max()
346:                 .unwrap_or(ch);
347: 
348:                 for y in ch..=neighbor_max.max(ch) {
349:                     grid.set(x, y, z, VOXEL_CEILING);
350:                 }
351:                 if p.light && !p.solid {
352:                     grid.set(x, ch, z, VOXEL_LIGHT);
353:                 }
354:             }
355:         }
356: 
357:         grid
358:     }
359: }
