368:     fn generate(ox: f32, oz: f32) -> VoxelGrid {
369:         BackroomsLevel.generate(
370:             Position::new(ox, oz),
371:             42,
372:             GeneratorConfig::low_spec(),
373:             &SimpleNoiseProvider::new(),
374:         )
