377:     fn is_open(grid: &VoxelGrid, x: usize, z: usize) -> bool {
378:         grid.get(x, 1, z) == VOXEL_AIR
379:     }
380: 
381:     /// Walkable-plane connectivity: nearly all open floor must be mutually
382:     /// reachable (walls always leave doorways, pillars never seal a region).
383:     /// We exclude a 2-voxel border to avoid edge-of-chunk artifacts where
384:     /// walls at boundaries form isolated strips that would be connected by
385:     /// the adjacent chunk at runtime.
386:     #[test]
387:     fn walkable_plane_is_connected() {
388:         let grid = generate(0.0, 0.0);
389:         let (w, d) = (grid.width(), grid.depth());
390:         let margin = 2usize; // exclude edge voxels
391: 
392:         let open: Vec<(usize, usize)> = (margin..w - margin)
393:             .flat_map(|x| (margin..d - margin).map(move |z| (x, z)))
394:             .filter(|&(x, z)| is_open(&grid, x, z))
395:             .collect();
396:         assert!(open.len() > (w - 2 * margin) * (d - 2 * margin) / 2,
397:             "backrooms must be mostly open space");
398: 
399:         // BFS from the spawn clearing (world 5,5 = local 25,25 in chunk 0,0).
400:         let mut visited = vec![false; w * d];
401:         let mut queue = std::collections::VecDeque::from([(w / 2, d / 2)]);
402:         visited[(w / 2) * d + d / 2] = true;
403:         let mut reached = 0usize;
404:         while let Some((x, z)) = queue.pop_front() {
405:             reached += 1;
406:             for (dx, dz) in [(1i64, 0i64), (-1, 0), (0, 1), (0, -1)] {
407:                 let (nx, nz) = (x as i64 + dx, z as i64 + dz);
408:                 if nx < margin as i64 || nz < margin as i64
409:                     || nx >= (w - margin) as i64 || nz >= (d - margin) as i64
410:                 {
411:                     continue;
412:                 }
413:                 let (nx, nz) = (nx as usize, nz as usize);
414:                 if !visited[nx * d + nz] && is_open(&grid, nx, nz) {
415:                     visited[nx * d + nz] = true;
416:                     queue.push_back((nx, nz));
417:                 }
418:             }
419:         }
420:         let ratio = reached as f32 / open.len() as f32;
421:         assert!(
422:             ratio > 0.95,
423:             "only {:.0}% of open floor is reachable from spawn",
424:             ratio * 100.0
425:         );
426:     }
