544:     /// The generation knobs actually steer the output: zeroing pillars and
545:     /// walls empties the world of solids; cranking them fills it back up.
546:     #[test]
547:     fn tuning_knobs_control_density() {
548:         let noise = SimpleNoiseProvider::new();
549:         let count_solids = |tuning: LevelTuning| -> usize {
550:             let grid = BackroomsLevel.generate(
551:                 Position::new(10.0, 10.0),
552:                 42,
553:                 GeneratorConfig::low_spec().with_tuning(tuning),
554:                 &noise,
555:             );
556:             let mut n = 0;
557:             for z in 0..grid.depth() {
558:                 for x in 0..grid.width() {
559:                     if grid.get(x, 1, z) != VOXEL_AIR {
560:                         n += 1;
561:                     }
562:                 }
563:             }
564:             n
565:         };
566: 
567:         let none = count_solids(LevelTuning { pillars: 0.0, walls: 0.0, ..Default::default() });
568:         let sparse = count_solids(LevelTuning { pillars: 0.3, walls: 0.3, ..Default::default() });
569:         let default = count_solids(LevelTuning::default());
570:         let dense = count_solids(LevelTuning { pillars: 2.0, walls: 2.0, ..Default::default() });
571: 
572:         assert_eq!(none, 0, "pillars=0 walls=0 must produce an empty plane");
573:         assert!(sparse < default, "sparse ({sparse}) must be < default ({default})");
574:         assert!(default < dense, "default ({default}) must be < dense ({dense})");
575:     }
